		var err error
		re, err = regexp.Compile(pattern)
		if err != nil {
			regexpFailed[pattern] = true
			cs := C.CString(err.Error())
			C.zk_result_error(ctx, cs)
			C.free(unsafe.Pointer(cs))
			return
		}
		regexpCache[pattern] = re
	}
	if re.MatchString(text) {
		C.zk_result_int(ctx, 1)
	} else {
		C.zk_result_int(ctx, 0)
	}
}

func OpenDB(path string) (*DB, error) {
	var db *C.sqlite3
	cs := C.CString(path)
	defer C.free(unsafe.Pointer(cs))
	rc := C.sqlite3_open(cs, &db)
	if rc != C.SQLITE_OK {
		msg := "unable to open database"
		if db != nil {
			msg = C.GoString(C.sqlite3_errmsg(db))
			C.sqlite3_close(db)
		}
		return nil, errors.New(msg)
	}
	C.sqlite3_busy_timeout(db, 5000)
	C.zk_register_regexp(db)
	d := &DB{db: db}
	return d, nil
}

func (d *DB) Close() {
	if d.db != nil {
		C.sqlite3_close(d.db)
		d.db = nil
	}
}

func (d *DB) errmsg() string {
	return C.GoString(C.sqlite3_errmsg(d.db))
}

// Stmt is a prepared statement.
type Stmt struct {
	db   *DB
	stmt *C.sqlite3_stmt
	done bool
}

func (d *DB) prepare(query string) (*Stmt, error) {
	cs := C.CString(query)
	defer C.free(unsafe.Pointer(cs))
	var stmt *C.sqlite3_stmt
	rc := C.zk_prepare(d.db, cs, C.int(len(query)), &stmt)
	if rc != C.SQLITE_OK {
		return nil, fmt.Errorf("%s", d.errmsg())
	}
	return &Stmt{db: d, stmt: stmt}, nil
}

func (s *Stmt) bind(args []interface{}) error {
	for i, arg := range args {
		idx := C.int(i + 1)
		var rc C.int
		switch v := arg.(type) {
		case nil:
			rc = C.sqlite3_bind_null(s.stmt, idx)
		case string:
			cs := C.CString(v)
			rc = C.zk_bind_text(s.stmt, idx, cs, C.int(len(v)))
			C.free(unsafe.Pointer(cs))
		case []byte:
			if len(v) == 0 {
				rc = C.sqlite3_bind_zeroblob(s.stmt, idx, 0)
			} else {
				rc = C.sqlite3_bind_blob(s.stmt, idx, unsafe.Pointer(&v[0]), C.int(len(v)), nil)
			}
		case int:
			rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(v))
		case int64:
			rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(v))
		case bool:
			b := 0
			if v {
				b = 1
			}
			rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(b))
		case float64:
			rc = C.sqlite3_bind_double(s.stmt, idx, C.double(v))
		case time.Time:
			str := formatDBTime(v)
			cs := C.CString(str)
			rc = C.zk_bind_text(s.stmt, idx, cs, C.int(len(str)))
			C.free(unsafe.Pointer(cs))
		case *time.Time:
			if v == nil {
				rc = C.sqlite3_bind_null(s.stmt, idx)
			} else {
				str := formatDBTime(*v)
				cs := C.CString(str)
				rc = C.zk_bind_text(s.stmt, idx, cs, C.int(len(str)))
				C.free(unsafe.Pointer(cs))
			}
		case *string:
			if v == nil {
				rc = C.sqlite3_bind_null(s.stmt, idx)
			} else {
				cs := C.CString(*v)
				rc = C.zk_bind_text(s.stmt, idx, cs, C.int(len(*v)))
				C.free(unsafe.Pointer(cs))
			}
		case *int64:
			if v == nil {
				rc = C.sqlite3_bind_null(s.stmt, idx)
			} else {
				rc = C.sqlite3_bind_int64(s.stmt, idx, C.sqlite3_int64(*v))
			}
		default:
			return fmt.Errorf("unsupported bind type %T", arg)
		}
		if rc != C.SQLITE_OK {
			return fmt.Errorf("bind: %s", s.db.errmsg())
		}
	}
	return nil
}

func (s *Stmt) Close() {
	if s.stmt != nil {
		C.sqlite3_finalize(s.stmt)
		s.stmt = nil
	}
}

// Rows iterates over query results.
type Rows struct {
	s   *Stmt
	err error
}

func (d *DB) Query(query string, args ...interface{}) (*Rows, error) {
	s, err := d.prepare(query)
	if err != nil {
		return nil, err
	}
	if err := s.bind(args); err != nil {
		s.Close()
		return nil, err
	}
	return &Rows{s: s}, nil
}

func (r *Rows) Next() bool {
	if r.s == nil || r.s.stmt == nil {
		return false
	}
	rc := C.sqlite3_step(r.s.stmt)
	if rc == C.SQLITE_ROW {
		return true
	}
	if rc != C.SQLITE_DONE {
		r.err = fmt.Errorf("%s", r.s.db.errmsg())
	}
	r.Close()
	return false
}

func (r *Rows) Err() error { return r.err }

func (r *Rows) Close() {
	if r.s != nil {
		r.s.Close()
		r.s = nil
	}
}

// NullString mirrors sql.NullString.
type NullString struct {
	String string
	Valid  bool
}

// NullInt64 mirrors sql.NullInt64.
type NullInt64 struct {
	Int64 int64
	Valid bool
}

func (r *Rows) columnText(i int) string {
	p := C.sqlite3_column_text(r.s.stmt, C.int(i))
	if p == nil {
		return ""
	}
	n := C.sqlite3_column_bytes(r.s.stmt, C.int(i))
	return C.GoStringN((*C.char)(unsafe.Pointer(p)), n)
}

func (r *Rows) Scan(dest ...interface{}) error {
	if r.s == nil || r.s.stmt == nil {
		return errors.New("scan on closed rows")
	}
	for i, d := range dest {
		ci := C.int(i)
		ctype := C.sqlite3_column_type(r.s.stmt, ci)
		isNull := ctype == C.SQLITE_NULL
		switch v := d.(type) {
		case *string:
			*v = r.columnText(i)
		case *int64:
			*v = int64(C.sqlite3_column_int64(r.s.stmt, ci))
		case *int:
			*v = int(C.sqlite3_column_int64(r.s.stmt, ci))
		case *bool:
			*v = C.sqlite3_column_int64(r.s.stmt, ci) != 0
		case *float64:
			*v = float64(C.sqlite3_column_double(r.s.stmt, ci))
		case *[]byte:
			n := C.sqlite3_column_bytes(r.s.stmt, ci)
			p := C.sqlite3_column_blob(r.s.stmt, ci)
			if p == nil || n == 0 {
				*v = []byte{}
			} else {
				*v = C.GoBytes(p, n)
			}
		case *NullString:
			if isNull {
				*v = NullString{}
			} else {
				*v = NullString{String: r.columnText(i), Valid: true}
			}
		case *NullInt64:
			if isNull {
				*v = NullInt64{}
			} else {
				*v = NullInt64{Int64: int64(C.sqlite3_column_int64(r.s.stmt, ci)), Valid: true}
			}
		case *time.Time:
			t, err := parseDBTime(r.columnText(i))
			if err != nil {
				return err
			}
			*v = t
		case **time.Time:
			if isNull {
				*v = nil
			} else {
				t, err := parseDBTime(r.columnText(i))
				if err != nil {
					return err
				}
				*v = &t
			}
		default:
			return fmt.Errorf("unsupported scan type %T", d)
		}
	}
	return nil
}

// Exec runs a statement without results.
func (d *DB) Exec(query string, args ...interface{}) error {
	s, err := d.prepare(query)
	if err != nil {
		return err
	}
	defer s.Close()
	if err := s.bind(args); err != nil {
		return err
	}
	rc := C.sqlite3_step(s.stmt)
	if rc != C.SQLITE_DONE && rc != C.SQLITE_ROW {
		return fmt.Errorf("%s", d.errmsg())
	}
	return nil
}

// ExecScript runs multiple statements.
func (d *DB) ExecScript(script string) error {
	cs := C.CString(script)
	defer C.free(unsafe.Pointer(cs))
	var errmsg *C.char
	rc := C.sqlite3_exec(d.db, cs, nil, nil, &errmsg)
	if rc != C.SQLITE_OK {
		msg := ""
		if errmsg != nil {
			msg = C.GoString(errmsg)
			C.sqlite3_free(unsafe.Pointer(errmsg))
		}
		return errors.New(msg)
	}
	return nil
}

func (d *DB) LastInsertID() int64 {
	return int64(C.sqlite3_last_insert_rowid(d.db))
}

func (d *DB) Changes() int64 {
	return int64(C.sqlite3_changes(d.db))
}

// QueryInt64s returns the first column of each row as int64.
func (d *DB) QueryInt64s(query string, args ...interface{}) ([]int64, error) {
	rows, err := d.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []int64
	for rows.Next() {
		var v int64
		if err := rows.Scan(&v); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, rows.Err()
}

// QueryStrings returns the first column of each row as string.
func (d *DB) QueryStrings(query string, args ...interface{}) ([]string, error) {
	rows, err := d.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []string
	for rows.Next() {
		var v string
		if err := rows.Scan(&v); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	return out, rows.Err()
}

const dbTimeLayout = "2006-01-02 15:04:05.999999999-07:00"

func formatDBTime(t time.Time) string {
	return t.Format(dbTimeLayout)
}

var dbTimeLayouts = []string{
	"2006-01-02 15:04:05.999999999-07:00",
	"2006-01-02T15:04:05.999999999-07:00",
	"2006-01-02 15:04:05.999999999",
	"2006-01-02T15:04:05.999999999",
	"2006-01-02 15:04:05",
	"2006-01-02T15:04:05",
	"2006-01-02 15:04",
	"2006-01-02T15:04",
	"2006-01-02",
}

func parseDBTime(s string) (time.Time, error) {
	s = strings.TrimSpace(s)
	if s == "" {
		return time.Time{}, nil
	}
	for _, l := range dbTimeLayouts {
		if t, err := time.ParseInLocation(l, s, time.UTC); err == nil {
			return t, nil
		}
	}
	return time.Time{}, fmt.Errorf("invalid time %q", s)
}
