	if raw.Template != nil {
		out.BodyTemplatePath = *raw.Template
	}
	if raw.Exclude != nil {
		out.Exclude = append([]string{}, raw.Exclude...)
	}
	if raw.Ignore != nil {
		out.Exclude = append(out.Exclude, raw.Ignore...)
	}
	if raw.IDCharset != nil {
		out.IDCharset = *raw.IDCharset
	}
	if raw.IDLength != nil {
		out.IDLength = *raw.IDLength
	}
	if raw.IDCase != nil {
		out.IDCase = *raw.IDCase
	}
	return out
}

// GroupConfigNamed returns the config for the given group name.
func (c Config) GroupConfigNamed(name string) (GroupConfig, bool) {
	g, ok := c.Groups[name]
	return g, ok
}

// GroupNameForPath returns the group whose paths contain the given
// notebook-relative directory, or "" when none matches.
func (c Config) GroupNameForPath(dir string) string {
	dir = filepath.ToSlash(filepath.Clean(dir))
	// Deterministic iteration order.
	names := sortedKeys(c.Groups)
	for _, name := range names {
		g := c.Groups[name]
		for _, p := range g.Paths {
			p = filepath.ToSlash(filepath.Clean(p))
			if p == "." || p == "" {
				continue
			}
			if dir == p || strings.HasPrefix(dir, p+"/") {
				return name
			}
		}
	}
	return ""
}

func sortedKeys(m map[string]GroupConfig) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sortStrings(keys)
	return keys
}

func expandPath(p string) string {
	if strings.HasPrefix(p, "~/") || p == "~" {
		home, err := os.UserHomeDir()
		if err == nil {
			p = filepath.Join(home, strings.TrimPrefix(p, "~"))
		}
	}
	return os.ExpandEnv(p)
}

// LocateGlobalConfig returns the path of the global config file.
func locateGlobalConfig() string {
	if dir := os.Getenv("XDG_CONFIG_HOME"); dir != "" {
		return filepath.Join(dir, "zk", "config.toml")
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config", "zk", "config.toml")
}
