	}
	return out
}

// ParseConfig parses a TOML config and merges it on top of parent.
func ParseConfig(content []byte, path string, parent Config) (Config, error) {
	var raw tomlConfig
	md, err := toml.Decode(string(content), &raw)
	if err != nil {
		return parent, err
	}
	_ = md

	cfg := parent
	// copy maps
	cfg.Groups = map[string]GroupConfig{}
	for k, v := range parent.Groups {
		cfg.Groups[k] = v
	}
	cfg.Extra = map[string]string{}
	for k, v := range parent.Extra {
		cfg.Extra[k] = v
	}
	cfg.Filters = map[string]string{}
	for k, v := range parent.Filters {
		cfg.Filters[k] = v
	}
	cfg.Aliases = map[string]string{}
	for k, v := range parent.Aliases {
		cfg.Aliases[k] = v
	}
	cfg.LSP.Diagnostics = map[string]interface{}{}
	for k, v := range parent.LSP.Diagnostics {
		cfg.LSP.Diagnostics[k] = v
	}

	if raw.Notebook.Dir != nil {
		cfg.NotebookDir = expandPath(*raw.Notebook.Dir)
	}

	cfg.Note = mergeNoteConfig(cfg.Note, raw.Note)

	for k, v := range raw.Extra {
		cfg.Extra[k] = fmt.Sprint(v)
	}

	for name, g := range raw.Groups {
		base := cfg.Note
		extra := map[string]string{}
		for k, v := range cfg.Extra {
			extra[k] = v
		}
		if existing, ok := cfg.Groups[name]; ok {
			base = existing.Note
			for k, v := range existing.Extra {
				extra[k] = v
			}
		}
		for k, v := range g.Extra {
			extra[k] = fmt.Sprint(v)
		}
		paths := g.Paths
		if paths == nil {
			if existing, ok := cfg.Groups[name]; ok && len(existing.Paths) > 0 {
				paths = existing.Paths
			} else {
				paths = []string{name}
			}
		}
		cfg.Groups[name] = GroupConfig{
			Paths: paths,
			Note:  mergeNoteConfig(base, g.Note),
			Extra: extra,
		}
	}
	// Groups declared only in the parent should inherit new global extra values.
	for name, g := range cfg.Groups {
		if _, ok := raw.Groups[name]; ok {
			continue
		}
		extra := map[string]string{}
		for k, v := range cfg.Extra {
			extra[k] = v
		}
		for k, v := range g.Extra {
			extra[k] = v
		}
		g.Extra = extra
		cfg.Groups[name] = g
	}

	m := raw.Format.Markdown
	if m.Hashtags != nil {
		cfg.Format.Hashtags = *m.Hashtags
	}
	if m.ColonTags != nil {
		cfg.Format.ColonTags = *m.ColonTags
	}
	if m.MultiwordTags != nil {
		cfg.Format.MultiwordTags = *m.MultiwordTags
	}
	if m.LinkFormat != nil {
		cfg.Format.LinkFormat = *m.LinkFormat
		if m.LinkEncodePath == nil {
			cfg.Format.LinkEncodePath = *m.LinkFormat == "markdown"
		}
	}
	if m.LinkEncodePath != nil {
		cfg.Format.LinkEncodePath = *m.LinkEncodePath
	}
	if m.LinkDropExtension != nil {
		cfg.Format.LinkDropExtension = *m.LinkDropExtension
	}

	t := raw.Tool
	if t.Editor != nil {
		cfg.Tool.Editor = *t.Editor
	}
	if t.Shell != nil {
		cfg.Tool.Shell = *t.Shell
	}
	if t.Pager != nil {
		p := *t.Pager
		cfg.Tool.Pager = &p
	}
	if t.FzfPreview != nil {
		p := *t.FzfPreview
		cfg.Tool.FzfPreview = &p
	}
	if t.FzfLine != nil {
		cfg.Tool.FzfLine = *t.FzfLine
	}
	if t.FzfOptions != nil {
		cfg.Tool.FzfOptions = *t.FzfOptions
	}
	if t.FzfBindNew != nil {
		cfg.Tool.FzfBindNew = *t.FzfBindNew
	}

	d := raw.LSP.Diagnostics
	if d.WikiTitle != nil {
		cfg.LSP.Diagnostics["wiki-title"] = d.WikiTitle
	}
	if d.DeadLink != nil {
		cfg.LSP.Diagnostics["dead-link"] = d.DeadLink
	}
	if d.SelfLink != nil {
		cfg.LSP.Diagnostics["self-link"] = d.SelfLink
	}
	if d.MissingBacklink != nil {
		cfg.LSP.Diagnostics["missing-backlink"] = d.MissingBacklink
	}
	c := raw.LSP.Completion
	if c.NoteLabel != nil {
		cfg.LSP.Completion.NoteLabel = c.NoteLabel
	}
	if c.NoteFilterText != nil {
		cfg.LSP.Completion.NoteFilterText = c.NoteFilterText
	}
	if c.NoteDetail != nil {
		cfg.LSP.Completion.NoteDetail = c.NoteDetail
	}
	if c.UseAdditionalTextEdits != nil {
		cfg.LSP.Completion.UseAdditionalTextEdits = c.UseAdditionalTextEdits
	}

	for k, v := range raw.Filters {
		cfg.Filters[k] = v
	}
	for k, v := range raw.Aliases {
		cfg.Aliases[k] = v
	}

	return cfg, nil
}

func mergeNoteConfig(base NoteConfig, raw tomlNoteConfig) NoteConfig {
	out := base
	if raw.Language != nil {
		out.Language = *raw.Language
