cd /workspace && cat > handlebars.go <<'EOF'
package main

import (
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"unicode"
)

// A small Handlebars implementation modeled after the subset of features
// needed by zk templates.

type hbNode interface{}

type hbText struct {
	text string
}

type hbComment struct{}

type hbMustache struct {
	expr *hbExpr
	raw  bool
	pos  int
}

type hbBlock struct {
	expr        *hbExpr
	program     []hbNode
	inverse     []hbNode
	blockParams []string
	inverted    bool // {{^foo}}
	pos         int
}

type hbExpr struct {
	path   *hbPath
	params []hbNode // *hbPath, hbLiteral, *hbExpr
	hash   map[string]hbNode
	hashOrder []string
	pos    int
	original string
}

type hbPath struct {
	original string
	depth    int
	parts    []string
	isData   bool
	isThis   bool
	pos      int
}

type hbLiteral struct {
	value interface{}
	pos   int
	kind  string // "String", "Number", "Boolean", "Null", "Undefined"
	raw   string
}

type hbTemplate struct {
	nodes []hbNode
}

type hbParseError struct {
	msg string
}

func (e *hbParseError) Error() string { return e.msg }

// ---------------------------------------------------------------------------
// Parser

type hbParser struct {
	src  string
	pos  int
	line int
}

func hbParse(src string) (*hbTemplate, error) {
	p := &hbParser{src: src, line: 1}
	nodes, closing, err := p.parseProgram()
	if err != nil {
		return nil, err
	}
	if closing != "" {
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nUnexpected closing tag '%s'", p.line, closing)}
	}
	return &hbTemplate{nodes: nodes}, nil
}

type hbTag struct {
	kind        string // "mustache", "raw", "comment", "open", "close", "else", "inverse-open", "partial"
	content     string
	stripBefore bool
	stripAfter  bool
	pos         int
}

func (p *hbParser) lineOf(pos int) int {
	return strings.Count(p.src[:pos], "\n") + 1
}

// parseProgram parses nodes until a closing tag or else tag is found.
// It returns the nodes and the name of the terminating tag ("" at EOF,
// "else" for an else tag, "/name" for a closing tag).
func (p *hbParser) parseProgram() ([]hbNode, string, error) {
	var nodes []hbNode
	for p.pos < len(p.src) {
		idx := strings.Index(p.src[p.pos:], "{{")
		if idx < 0 {
			nodes = append(nodes, &hbText{text: p.src[p.pos:]})
			p.pos = len(p.src)
			break
		}
		if idx > 0 {
			nodes = append(nodes, &hbText{text: p.src[p.pos : p.pos+idx]})
		}
		p.pos += idx
		tag, err := p.readTag()
		if err != nil {
			return nil, "", err
		}
		if tag.stripBefore {
			if n := len(nodes); n > 0 {
				if t, ok := nodes[n-1].(*hbText); ok {
					t.text = strings.TrimRightFunc(t.text, unicode.IsSpace)
				}
			}
		}
		if tag.stripAfter {
			p.pos += len(p.src[p.pos:]) - len(strings.TrimLeftFunc(p.src[p.pos:], unicode.IsSpace))
		}
		switch tag.kind {
		case "comment":
			nodes = append(nodes, &hbComment{})
		case "partial":
			// Partials are not supported; render nothing.
			nodes = append(nodes, &hbComment{})
		case "mustache", "raw":
			expr, err := p.parseExpr(tag.content, tag.pos)
			if err != nil {
				return nil, "", err
			}
			nodes = append(nodes, &hbMustache{expr: expr, raw: tag.kind == "raw", pos: tag.pos})
		case "open", "inverse-open":
			block, err := p.parseBlock(tag)
			if err != nil {
				return nil, "", err
			}
			nodes = append(nodes, block)
		case "close":
			return nodes, "/" + strings.TrimSpace(tag.content), nil
		case "else":
			return nodes, "else" + tag.content, nil
		}
	}
	return nodes, "", nil
}

func (p *hbParser) readTag() (hbTag, error) {
	start := p.pos
	tag := hbTag{pos: start}
	src := p.src
	i := p.pos + 2
	raw := false
	if strings.HasPrefix(src[i:], "{") {
		raw = true
		i++
	}
	if strings.HasPrefix(src[i:], "~") {
		tag.stripBefore = true
		i++
	}
	// comments
	if strings.HasPrefix(src[i:], "!--") {
		end := strings.Index(src[i:], "--}}")
		if end < 0 {
			return tag, &hbParseError{fmt.Sprintf("Parse error on line %d:\nUnterminated comment", p.lineOf(start))}
		}
		p.pos = i + end + 4
		if strings.HasPrefix(src[i+end+2:], "~}}") {
			tag.stripAfter = true
		}
		tag.kind = "comment"
		return tag, nil
	}
	if strings.HasPrefix(src[i:], "!") {
		end := strings.Index(src[i:], "}}")
		if end < 0 {
			return tag, &hbParseError{fmt.Sprintf("Parse error on line %d:\nUnterminated comment", p.lineOf(start))}
		}
		p.pos = i + end + 2
		tag.kind = "comment"
		return tag, nil
	}
	closer := "}}"
	if raw {
		closer = "}}}"
	}
	// find the closing, skipping string literals
	j := i
	inStr := byte(0)
	end := -1
	for j < len(src) {
		c := src[j]
		if inStr != 0 {
			if c == '\\' && j+1 < len(src) {
				j += 2
				continue
			}
			if c == inStr {
				inStr = 0
			}
			j++
			continue
		}
		if c == '"' || c == '\'' {
			inStr = c
			j++
			continue
		}
		if strings.HasPrefix(src[j:], closer) {
			end = j
			break
		}
		j++
	}
	if end < 0 {
		return tag, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting 'CLOSE', got 'EOF'", p.lineOf(start))}
	}
	content := src[i:end]
	if strings.HasSuffix(content, "~") {
		tag.stripAfter = true
		content = content[:len(content)-1]
	}
	p.pos = end + len(closer)
	content = strings.TrimSpace(content)
	if raw {
		tag.kind = "raw"
		tag.content = content
		return tag, nil
	}
	switch {
	case strings.HasPrefix(content, "#"):
		tag.kind = "open"
		tag.content = strings.TrimSpace(content[1:])
	case strings.HasPrefix(content, "^"):
		rest := strings.TrimSpace(content[1:])
		if rest == "" {
			tag.kind = "else"
			tag.content = ""
		} else {
			tag.kind = "inverse-open"
			tag.content = rest
		}
	case strings.HasPrefix(content, "/"):
		tag.kind = "close"
		tag.content = strings.TrimSpace(content[1:])
	case content == "else" || strings.HasPrefix(content, "else ") || strings.HasPrefix(content, "else\t") || strings.HasPrefix(content, "else\n"):
		tag.kind = "else"
		tag.content = strings.TrimSpace(content[4:])
		if tag.content != "" {
			tag.content = " " + tag.content
		}
	case strings.HasPrefix(content, ">"):
		tag.kind = "partial"
		tag.content = strings.TrimSpace(content[1:])
	case strings.HasPrefix(content, "&"):
		tag.kind = "raw"
		tag.content = strings.TrimSpace(content[1:])
	default:
		tag.kind = "mustache"
		tag.content = content
	}
	return tag, nil
}

func (p *hbParser) parseBlock(open hbTag) (*hbBlock, error) {
	content := open.content
	var blockParams []string
	if idx := strings.Index(content, " as |"); idx >= 0 {
		rest := content[idx+5:]
		if end := strings.Index(rest, "|"); end >= 0 {
			blockParams = strings.Fields(rest[:end])
			content = strings.TrimSpace(content[:idx])
		}
	}
	expr, err := p.parseExpr(content, open.pos)
	if err != nil {
		return nil, err
	}
	block := &hbBlock{expr: expr, blockParams: blockParams, inverted: open.kind == "inverse-open", pos: open.pos}
	program, closing, err := p.parseProgram()
	if err != nil {
		return nil, err
	}
	block.program = program
	name := expr.path.original
	for strings.HasPrefix(closing, "else") {
		elseContent := strings.TrimSpace(strings.TrimPrefix(closing, "else"))
		if elseContent != "" {
			// chained else: {{else if cond}}
			chainTag := hbTag{kind: "open", content: elseContent, pos: open.pos}
			chained, err := p.parseBlockChained(chainTag, name)
			if err != nil {
				return nil, err
			}
			block.inverse = []hbNode{chained.block}
			closing = chained.closing
			break
		}
		inverse, c, err := p.parseProgram()
		if err != nil {
			return nil, err
		}
		block.inverse = inverse
		closing = c
	}
	if closing != "/"+name {
		if closing == "" {
			return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting 'OPEN_ENDBLOCK', got 'EOF'", p.lineOf(len(p.src)))}
		}
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\n%s doesn't match %s", p.lineOf(p.pos), name, strings.TrimPrefix(closing, "/"))}
	}
	return block, nil
}

type hbChained struct {
	block   *hbBlock
	closing string
}

// parseBlockChained parses a chained {{else if ...}} block, which is
// terminated by the closing tag of the outer block.
func (p *hbParser) parseBlockChained(open hbTag, outerName string) (*hbChained, error) {
	content := open.content
	var blockParams []string
	if idx := strings.Index(content, " as |"); idx >= 0 {
		rest := content[idx+5:]
		if end := strings.Index(rest, "|"); end >= 0 {
			blockParams = strings.Fields(rest[:end])
			content = strings.TrimSpace(content[:idx])
		}
	}
	expr, err := p.parseExpr(content, open.pos)
	if err != nil {
		return nil, err
	}
	block := &hbBlock{expr: expr, blockParams: blockParams, pos: open.pos}
	program, closing, err := p.parseProgram()
	if err != nil {
		return nil, err
	}
	block.program = program
	for strings.HasPrefix(closing, "else") {
		elseContent := strings.TrimSpace(strings.TrimPrefix(closing, "else"))
		if elseContent != "" {
			chainTag := hbTag{kind: "open", content: elseContent, pos: open.pos}
			chained, err := p.parseBlockChained(chainTag, outerName)
			if err != nil {
				return nil, err
			}
			block.inverse = []hbNode{chained.block}
			return &hbChained{block: block, closing: chained.closing}, nil
		}
		inverse, c, err := p.parseProgram()
		if err != nil {
			return nil, err
		}
		block.inverse = inverse
		closing = c
	}
	return &hbChained{block: block, closing: closing}, nil
}

// Expression tokenizer

type hbToken struct {
	kind string // "id", "string", "number", "bool", "null", "undefined", "open", "close", "equals", "data"
	text string
	pos  int
}

func hbTokenize(s string, base int) ([]hbToken, error) {
	var toks []hbToken
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '(':
			toks = append(toks, hbToken{kind: "open", text: "(", pos: base + i})
			i++
		case c == ')':
			toks = append(toks, hbToken{kind: "close", text: ")", pos: base + i})
			i++
		case c == '=':
			toks = append(toks, hbToken{kind: "equals", text: "=", pos: base + i})
			i++
		case c == '"' || c == '\'':
			j := i + 1
			var sb strings.Builder
			for j < len(s) && s[j] != c {
				if s[j] == '\\' && j+1 < len(s) {
					sb.WriteByte(s[j+1])
					j += 2
					continue
				}
				sb.WriteByte(s[j])
				j++
			}
			if j >= len(s) {
				return nil, &hbParseError{"Parse error:\nUnterminated string"}
			}
			toks = append(toks, hbToken{kind: "string", text: sb.String(), pos: base + i})
			i = j + 1
		default:
			j := i
			for j < len(s) {
				d := s[j]
				if d == ' ' || d == '\t' || d == '\n' || d == '\r' || d == '(' || d == ')' || d == '=' {
					break
				}
				if d == '[' {
					// literal segment
					end := strings.IndexByte(s[j:], ']')
					if end < 0 {
						return nil, &hbParseError{"Parse error:\nUnterminated segment literal"}
					}
					j += end + 1
					continue
				}
				j++
			}
			text := s[i:j]
			tok := hbToken{text: text, pos: base + i}
			switch {
			case text == "true" || text == "false":
				tok.kind = "bool"
			case text == "null":
				tok.kind = "null"
			case text == "undefined":
				tok.kind = "undefined"
			case hbIsNumber(text):
				tok.kind = "number"
			default:
				tok.kind = "id"
			}
			toks = append(toks, tok)
			i = j
		}
	}
	return toks, nil
}

func hbIsNumber(s string) bool {
	if s == "" {
		return false
	}
	start := 0
	if s[0] == '-' {
		start = 1
		if len(s) == 1 {
			return false
		}
	}
	dot := false
	for i := start; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			if dot {
				return false
			}
			dot = true
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func (p *hbParser) parseExpr(content string, pos int) (*hbExpr, error) {
	toks, err := hbTokenize(content, pos+2)
	if err != nil {
		return nil, err
	}
	if len(toks) == 0 {
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting ID, got: 'CLOSE'", p.lineOf(pos))}
	}
	idx := 0
	expr, err := p.parseExprTokens(toks, &idx, pos, content)
	if err != nil {
		return nil, err
	}
	if idx != len(toks) {
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting 'CLOSE', got: '%s'", p.lineOf(pos), toks[idx].text)}
	}
	return expr, nil
}

func (p *hbParser) parseExprTokens(toks []hbToken, idx *int, pos int, original string) (*hbExpr, error) {
	if *idx >= len(toks) {
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting ID, got: 'CLOSE'", p.lineOf(pos))}
	}
	first := toks[*idx]
	expr := &hbExpr{hash: map[string]hbNode{}, pos: first.pos - 2, original: original}
	if first.kind != "id" {
		if first.kind == "number" {
			return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting ID, got: 'Number{\"%s\"}'", p.lineOf(pos), first.text)}
		}
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting ID, got: '%s'", p.lineOf(pos), first.text)}
	}
	path, err := p.parsePath(first)
	if err != nil {
		return nil, err
	}
	expr.path = path
	*idx++
	for *idx < len(toks) {
		tok := toks[*idx]
		if tok.kind == "close" {
			break
		}
		// hash param?
		if tok.kind == "id" && *idx+1 < len(toks) && toks[*idx+1].kind == "equals" {
			key := tok.text
			*idx += 2
			if *idx >= len(toks) {
				return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting value after '='", p.lineOf(pos))}
			}
			val, err := p.parseParam(toks, idx, pos, original)
			if err != nil {
				return nil, err
			}
			expr.hash[key] = val
			expr.hashOrder = append(expr.hashOrder, key)
			continue
		}
		val, err := p.parseParam(toks, idx, pos, original)
		if err != nil {
			return nil, err
		}
		expr.params = append(expr.params, val)
	}
	return expr, nil
}

func (p *hbParser) parseParam(toks []hbToken, idx *int, pos int, original string) (hbNode, error) {
	tok := toks[*idx]
	switch tok.kind {
	case "open":
		*idx++
		sub, err := p.parseExprTokens(toks, idx, pos, original)
		if err != nil {
			return nil, err
		}
		if *idx >= len(toks) || toks[*idx].kind != "close" {
			return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting 'CLOSE_SEXPR'", p.lineOf(pos))}
		}
		*idx++
		return sub, nil
	case "string":
		*idx++
		return hbLiteral{value: tok.text, pos: tok.pos, kind: "String", raw: tok.text}, nil
	case "number":
		*idx++
		if strings.Contains(tok.text, ".") {
			f, _ := strconv.ParseFloat(tok.text, 64)
			return hbLiteral{value: f, pos: tok.pos, kind: "Number", raw: tok.text}, nil
		}
		n, _ := strconv.Atoi(tok.text)
		return hbLiteral{value: n, pos: tok.pos, kind: "Number", raw: tok.text}, nil
	case "bool":
		*idx++
		return hbLiteral{value: tok.text == "true", pos: tok.pos, kind: "Boolean", raw: tok.text}, nil
	case "null":
		*idx++
		return hbLiteral{value: nil, pos: tok.pos, kind: "Null", raw: tok.text}, nil
	case "undefined":
		*idx++
		return hbLiteral{value: nil, pos: tok.pos, kind: "Undefined", raw: tok.text}, nil
	case "id":
		*idx++
		return p.parsePath(tok)
	case "equals":
		return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nExpecting ID, got: 'EQUALS'", p.lineOf(pos))}
	}
	return nil, &hbParseError{fmt.Sprintf("Parse error on line %d:\nUnexpected token '%s'", p.lineOf(pos), tok.text)}
}

func (p *hbParser) parsePath(tok hbToken) (*hbPath, error) {
	s := tok.text
	path := &hbPath{original: s, pos: tok.pos}
	if strings.HasPrefix(s, "@") {
		path.isData = true
		s = s[1:]
	}
	// split on '/' and '.', honoring [literal] segments
	var segs []string
	var cur strings.Builder
	i := 0
	for i < len(s) {
		c := s[i]
		if c == '[' {
			end := strings.IndexByte(s[i:], ']')
			if end < 0 {
				return nil, &hbParseError{"Parse error:\nUnterminated segment literal"}
			}
			cur.WriteString(s[i+1 : i+end])
			i += end + 1
			continue
		}
		if c == '/' || c == '.' {
			// ".." as a segment
			if c == '.' && i+1 < len(s) && s[i+1] == '.' && cur.Len() == 0 {
				segs = append(segs, "..")
				i += 2
				continue
			}
			if c == '.' && cur.Len() == 0 && (i+1 == len(s) || s[i+1] == '/') {
				segs = append(segs, ".")
				i++
				continue
			}
			segs = append(segs, cur.String())
			cur.Reset()
			i++
			continue
		}
		cur.WriteByte(c)
		i++
	}
	if cur.Len() > 0 || len(segs) == 0 {
		segs = append(segs, cur.String())
	}
	var parts []string
	for _, seg := range segs {
		switch seg {
		case "..":
			if len(parts) > 0 {
				return nil, &hbParseError{fmt.Sprintf("Parse error:\nInvalid path: %s", path.original)}
			}
			path.depth++
		case ".", "this", "":
			if len(parts) == 0 {
				path.isThis = true
			}
		default:
			parts = append(parts, seg)
		}
	}
	path.parts = parts
	return path, nil
}

// ---------------------------------------------------------------------------
// Evaluation

type hbFrame struct {
	ctx         interface{}
	data        map[string]interface{}
	parent      *hbFrame
	blockParams map[string]interface{}
}

type hbEvalError struct {
	msg string
}

func (e *hbEvalError) Error() string { return e.msg }

type hbHelperOptions struct {
	frame   *hbFrame
	hash    map[string]interface{}
	fn      func(ctx interface{}, data map[string]interface{}, blockParams []interface{}) (string, error)
	inverse func(ctx interface{}) (string, error)
	isBlock bool
	engine  *hbEngine
	node    hbNode
}

type hbHelper func(params []interface{}, opts *hbHelperOptions) (interface{}, error)

type hbEngine struct {
	helpers map[string]hbHelper
}

// ContextLookup allows custom context types.
type ContextLookup interface {
	HBGet(key string) (interface{}, bool)
}

func newHBEngine() *hbEngine {
	e := &hbEngine{helpers: map[string]hbHelper{}}
	e.registerBuiltins()
	return e
}

func (e *hbEngine) RegisterHelper(name string, h hbHelper) {
	e.helpers[name] = h
}

func (e *hbEngine) Render(tpl *hbTemplate, ctx interface{}) (string, error) {
	frame := &hbFrame{ctx: ctx, data: map[string]interface{}{"root": ctx}}
	return e.renderNodes(tpl.nodes, frame)
}

func (e *hbEngine) renderNodes(nodes []hbNode, frame *hbFrame) (string, error) {
	var sb strings.Builder
	for _, n := range nodes {
		switch node := n.(type) {
		case *hbText:
			sb.WriteString(node.text)
		case *hbComment:
		case *hbMustache:
			val, err := e.evalMustache(node, frame)
			if err != nil {
				return "", err
			}
			sb.WriteString(val)
		case *hbBlock:
			val, err := e.evalBlock(node, frame)
			if err != nil {
				return "", err
			}
			sb.WriteString(val)
		}
	}
	return sb.String(), nil
}

func (e *hbEngine) evalMustache(node *hbMustache, frame *hbFrame) (string, error) {
	expr := node.expr
	// Helper?
	if helper, ok := e.helpers[expr.path.original]; ok && !expr.path.isData && len(expr.path.parts) == 1 && expr.path.depth == 0 {
		params, hash, err := e.evalParams(expr, frame)
		if err != nil {
			return "", err
		}
		opts := &hbHelperOptions{frame: frame, hash: hash, engine: e, node: node}
		res, err := helper(params, opts)
		if err != nil {
			return "", err
		}
		return hbStr(res), nil
	}
	if len(expr.params) > 0 || len(expr.hash) > 0 {
		// Not a helper but called with params: evaluates to nothing.
		return "", nil
	}
	val := e.resolvePath(expr.path, frame)
	return hbStr(val), nil
}

func (e *hbEngine) evalParams(expr *hbExpr, frame *hbFrame) ([]interface{}, map[string]interface{}, error) {
	var params []interface{}
	for _, p := range expr.params {
		v, err := e.evalParam(p, frame)
		if err != nil {
			return nil, nil, err
		}
		params = append(params, v)
	}
	hash := map[string]interface{}{}
	for k, p := range expr.hash {
		v, err := e.evalParam(p, frame)
		if err != nil {
			return nil, nil, err
		}
		hash[k] = v
	}
	return params, hash, nil
}

func (e *hbEngine) evalParam(p hbNode, frame *hbFrame) (interface{}, error) {
	switch v := p.(type) {
	case hbLiteral:
		return v.value, nil
	case *hbPath:
		return e.resolvePath(v, frame), nil
	case *hbExpr:
		if helper, ok := e.helpers[v.path.original]; ok {
			params, hash, err := e.evalParams(v, frame)
			if err != nil {
				return nil, err
			}
			opts := &hbHelperOptions{frame: frame, hash: hash, engine: e, node: v}
			return helper(params, opts)
		}
		return e.resolvePath(v.path, frame), nil
	}
	return nil, nil
}

func (e *hbEngine) evalBlock(node *hbBlock, frame *hbFrame) (string, error) {
	expr := node.expr
	fn := func(ctx interface{}, data map[string]interface{}, blockParams []interface{}) (string, error) {
		child := &hbFrame{ctx: ctx, parent: frame, data: map[string]interface{}{}}
		for k, v := range frame.data {
			child.data[k] = v
		}
		for k, v := range data {
			child.data[k] = v
		}
		if len(node.blockParams) > 0 {
			child.blockParams = map[string]interface{}{}
			for i, name := range node.blockParams {
				if i < len(blockParams) {
					child.blockParams[name] = blockParams[i]
				}
			}
		}
		return e.renderNodes(node.program, child)
	}
	inverse := func(ctx interface{}) (string, error) {
		child := &hbFrame{ctx: ctx, parent: frame, data: frame.data}
		return e.renderNodes(node.inverse, child)
	}
	if node.inverted {
		// {{^foo}}...{{/foo}}: render when falsy
		val := e.resolvePath(expr.path, frame)
		if !hbTruthy(val) {
			return fn(frame.ctx, nil, nil)
		}
		return inverse(frame.ctx)
	}
	if helper, ok := e.helpers[expr.path.original]; ok && !expr.path.isData {
		params, hash, err := e.evalParams(expr, frame)
		if err != nil {
			return "", err
		}
		opts := &hbHelperOptions{frame: frame, hash: hash, fn: fn, inverse: inverse, isBlock: true, engine: e, node: node}
		res, err := helper(params, opts)
		if err != nil {
			return "", err
		}
		return hbStr(res), nil
	}
	// Mustache-style section.
	val := e.resolvePath(expr.path, frame)
	rv := reflect.ValueOf(val)
	if val != nil && rv.Kind() == reflect.Slice {
		var sb strings.Builder
		n := rv.Len()
		if n == 0 {
			return inverse(frame.ctx)
		}
		for i := 0; i < n; i++ {
			item := rv.Index(i).Interface()
			s, err := fn(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == n-1}, []interface{}{item, i})
			if err != nil {
				return "", err
			}
			sb.WriteString(s)
		}
		return sb.String(), nil
	}
	if hbTruthy(val) {
		return fn(val, nil, []interface{}{val})
	}
	return inverse(frame.ctx)
}

func (e *hbEngine) resolvePath(path *hbPath, frame *hbFrame) interface{} {
	f := frame
	for i := 0; i < path.depth; i++ {
		if f.parent == nil {
			return nil
		}
		f = f.parent
	}
	if path.isData {
		var cur interface{}
		if len(path.parts) == 0 {
			return nil
		}
		v, ok := f.data[path.parts[0]]
		if !ok {
			return nil
		}
		cur = v
		for _, part := range path.parts[1:] {
			cur = hbLookupKey(cur, part)
		}
		return cur
	}
	var cur interface{} = f.ctx
	if len(path.parts) == 0 {
		return cur
	}
	// block params
	if path.depth == 0 {
		for ff := frame; ff != nil; ff = ff.parent {
			if ff.blockParams != nil {
				if v, ok := ff.blockParams[path.parts[0]]; ok {
					cur = v
					for _, part := range path.parts[1:] {
						cur = hbLookupKey(cur, part)
					}
					return cur
				}
			}
			if ff.ctx != nil && ff != frame {
				// block params only apply within their scope; keep walking
			}
		}
	}
	for _, part := range path.parts {
		cur = hbLookupKey(cur, part)
		if cur == nil {
			return nil
		}
	}
	return cur
}

func hbLookupKey(v interface{}, key string) interface{} {
	if v == nil {
		return nil
	}
	if cl, ok := v.(ContextLookup); ok {
		r, ok := cl.HBGet(key)
		if !ok {
			return nil
		}
		return r
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Map:
		kv := reflect.ValueOf(key)
		if rv.Type().Key().Kind() != reflect.String {
			return nil
		}
		r := rv.MapIndex(kv)
		if !r.IsValid() {
			return nil
		}
		return r.Interface()
	case reflect.Slice, reflect.Array:
		idx, err := strconv.Atoi(key)
		if err != nil || idx < 0 || idx >= rv.Len() {
			return nil
		}
		return rv.Index(idx).Interface()
	case reflect.Struct:
		f := rv.FieldByName(key)
		if f.IsValid() {
			return f.Interface()
		}
		return nil
	case reflect.Ptr:
		if rv.IsNil() {
			return nil
		}
		return hbLookupKey(rv.Elem().Interface(), key)
	}
	return nil
}

func hbTruthy(v interface{}) bool {
	if v == nil {
		return false
	}
	switch x := v.(type) {
	case bool:
		return x
	case string:
		return x != ""
	case int:
		return x != 0
	case int64:
		return x != 0
	case float64:
		return x != 0
	}
	rv := reflect.ValueOf(v)
	switch rv.Kind() {
	case reflect.Slice, reflect.Array, reflect.Map:
		return rv.Len() > 0
	case reflect.Ptr, reflect.Interface:
		return !rv.IsNil()
	}
	return true
}

// hbStr converts a value to its string representation.
func hbStr(v interface{}) string {
	if v == nil {
		return ""
	}
	switch x := v.(type) {
	case string:
		return x
	case bool:
		if x {
			return "true"
		}
		return "false"
	case int:
		return strconv.Itoa(x)
	case int64:
		return strconv.FormatInt(x, 10)
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64)
	case []string:
		var sb strings.Builder
		for _, s := range x {
			sb.WriteString(s)
		}
		return sb.String()
	case []interface{}:
		var sb strings.Builder
		for _, s := range x {
			sb.WriteString(hbStr(s))
		}
		return sb.String()
	}
	rv := reflect.ValueOf(v)
	if rv.Kind() == reflect.Slice {
		var sb strings.Builder
		for i := 0; i < rv.Len(); i++ {
			sb.WriteString(hbStr(rv.Index(i).Interface()))
		}
		return sb.String()
	}
	return fmt.Sprintf("%s", v)
}

// ---------------------------------------------------------------------------
// Built-in helpers

func (e *hbEngine) registerBuiltins() {
	e.helpers["if"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 1 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'if' called with wrong number of arguments, needed 1 but got %d", len(params))}
		}
		if !opts.isBlock {
			return "", nil
		}
		if hbTruthy(params[0]) {
			return opts.fn(opts.frame.ctx, nil, nil)
		}
		return opts.inverse(opts.frame.ctx)
	}
	e.helpers["unless"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 1 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'unless' called with wrong number of arguments, needed 1 but got %d", len(params))}
		}
		if !opts.isBlock {
			return "", nil
		}
		if !hbTruthy(params[0]) {
			return opts.fn(opts.frame.ctx, nil, nil)
		}
		return opts.inverse(opts.frame.ctx)
	}
	e.helpers["with"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 1 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'with' called with wrong number of arguments, needed 1 but got %d", len(params))}
		}
		if !opts.isBlock {
			return "", nil
		}
		if hbTruthy(params[0]) {
			return opts.fn(params[0], nil, []interface{}{params[0]})
		}
		return opts.inverse(opts.frame.ctx)
	}
	e.helpers["each"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 1 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'each' called with wrong number of arguments, needed 1 but got %d", len(params))}
		}
		if !opts.isBlock {
			return "", nil
		}
		val := params[0]
		if val == nil {
			return opts.inverse(opts.frame.ctx)
		}
		rv := reflect.ValueOf(val)
		var sb strings.Builder
		switch rv.Kind() {
		case reflect.Slice, reflect.Array:
			n := rv.Len()
			if n == 0 {
				return opts.inverse(opts.frame.ctx)
			}
			for i := 0; i < n; i++ {
				item := rv.Index(i).Interface()
				s, err := opts.fn(item, map[string]interface{}{"index": i, "first": i == 0, "last": i == n-1}, []interface{}{item, i})
				if err != nil {
					return nil, err
				}
				sb.WriteString(s)
			}
		case reflect.Map:
			keys := rv.MapKeys()
			n := len(keys)
			if n == 0 {
				return opts.inverse(opts.frame.ctx)
			}
			for i, k := range keys {
				item := rv.MapIndex(k).Interface()
				s, err := opts.fn(item, map[string]interface{}{"key": k.Interface(), "index": i, "first": i == 0, "last": i == n-1}, []interface{}{item, k.Interface()})
				if err != nil {
					return nil, err
				}
				sb.WriteString(s)
			}
		default:
			return opts.inverse(opts.frame.ctx)
		}
		return sb.String(), nil
	}
	e.helpers["lookup"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 2 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'lookup' called with wrong number of arguments, needed 2 but got %d", len(params))}
		}
		return hbLookupKey(params[0], hbStr(params[1])), nil
	}
	e.helpers["equal"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		if len(params) != 2 {
			return nil, &hbEvalError{fmt.Sprintf("Helper 'equal' called with wrong number of arguments, needed 2 but got %d", len(params))}
		}
		eq := hbStr(params[0]) == hbStr(params[1]) && reflect.TypeOf(params[0]) == reflect.TypeOf(params[1])
		if !eq {
			// loosely compare numbers
			if a, ok := hbToFloat(params[0]); ok {
				if b, ok := hbToFloat(params[1]); ok {
					eq = a == b
				}
			}
		}
		if opts.isBlock {
			if eq {
				return opts.fn(opts.frame.ctx, nil, nil)
			}
			return opts.inverse(opts.frame.ctx)
		}
		return eq, nil
	}
	e.helpers["log"] = func(params []interface{}, opts *hbHelperOptions) (interface{}, error) {
		return "", nil
	}
}

func hbToFloat(v interface{}) (float64, bool) {
	switch x := v.(type) {
	case int:
		return float64(x), true
	case int64:
		return float64(x), true
	case float64:
		return x, true
	}
	return 0, false
}

// hbNodeString describes a node for error messages (approximating raymond).
func hbNodeString(n hbNode) string {
	switch v := n.(type) {
	case hbLiteral:
		switch v.kind {
		case "String":
			return fmt.Sprintf("String{Value:'%s', Pos:%d}", v.raw, v.pos)
		case "Number":
			return fmt.Sprintf("Number{Value:%s, Pos:%d}", v.raw, v.pos)
		case "Boolean":
			return fmt.Sprintf("Boolean{Value:%s, Pos:%d}", v.raw, v.pos)
		}
		return fmt.Sprintf("%s{Pos:%d}", v.kind, v.pos)
	case *hbPath:
		return fmt.Sprintf("Path{Original:'%s', Pos:%d}", v.original, v.pos)
	case *hbExpr:
		return fmt.Sprintf("Expr{Path:Path{Original:'%s', Pos:%d}, Pos:%d}", v.path.original, v.path.pos, v.pos)
	case *hbMustache:
		return fmt.Sprintf("Expr{Path:Path{Original:'%s', Pos:%d}, Pos:%d}", v.expr.path.original, v.expr.path.pos, v.expr.pos)
	case *hbBlock:
		return fmt.Sprintf("Expr{Path:Path{Original:'%s', Pos:%d}, Pos:%d}", v.expr.path.original, v.expr.path.pos, v.expr.pos)
	}
	return fmt.Sprintf("%v", n)
}
