package main

import (
	"fmt"
	"net/url"
	"path"
	"path/filepath"
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"

	"gopkg.in/yaml.v3"
)

// Link represents a link found in a note.
type Link struct {
	Title        string
	Href         string
	Type         string // "markdown", "wiki-link", "implicit"
	IsExternal   bool
	Rels         []string
	Snippet      string
	SnippetStart int
	SnippetEnd   int
}

// ParsedNote is the result of parsing a note's content.
type ParsedNote struct {
	Title      string
	Lead       string
	Body       string
	RawContent string
	WordCount  int
	Links      []Link
	Tags       []string
	Metadata   map[string]interface{}
}

type MarkdownOptions struct {
	Hashtags      bool
	ColonTags     bool
	MultiwordTags bool
}

// ---------------------------------------------------------------------------
// Frontmatter

var frontmatterOpenRe = regexp.MustCompile(`^---[ \t]*(\r?\n|$)`)
var frontmatterCloseRe = regexp.MustCompile(`^-{3,}[ \t]*$`)

// parseFrontmatter returns the metadata, the byte offset where the body
// starts and whether a frontmatter was found.
func parseFrontmatter(content string) (map[string]interface{}, int, bool, error) {
	if !frontmatterOpenRe.MatchString(content) {
		return nil, 0, false, nil
	}
	firstNL := strings.IndexByte(content, '\n')
	if firstNL < 0 {
		return nil, 0, false, nil
	}
	pos := firstNL + 1
	yamlStart := pos
	for pos <= len(content) {
		nl := strings.IndexByte(content[pos:], '\n')
		var line string
		var next int
		if nl < 0 {
			line = content[pos:]
			next = len(content) + 1
		} else {
			line = content[pos : pos+nl]
			next = pos + nl + 1
		}
		line = strings.TrimRight(line, "\r")
		if frontmatterCloseRe.MatchString(line) {
			yamlSrc := content[yamlStart:pos]
			meta := map[string]interface{}{}
			var node yaml.Node
			if err := yaml.Unmarshal([]byte(yamlSrc), &node); err != nil {
				return nil, 0, false, err
			}
			var raw map[string]interface{}
			if node.Kind != 0 {
				if err := node.Decode(&raw); err != nil {
					var anyVal interface{}
					if err2 := node.Decode(&anyVal); err2 != nil {
						return nil, 0, false, err
					}
					if m, ok := anyVal.(map[string]interface{}); ok {
						raw = m
					}
				}
			}
			for k, v := range raw {
				meta[strings.ToLower(k)] = normalizeYAML(v)
			}
			end := next
			if end > len(content) {
				end = len(content)
			}
			return meta, end, true, nil
		}
		if nl < 0 {
			break
		}
		pos = next
	}
	return nil, 0, false, nil
}

func normalizeYAML(v interface{}) interface{} {
	switch x := v.(type) {
	case map[string]interface{}:
		out := map[string]interface{}{}
		for k, vv := range x {
			out[k] = normalizeYAML(vv)
		}
		return out
	case map[interface{}]interface{}:
		out := map[string]interface{}{}
		for k, vv := range x {
			out[fmt.Sprint(k)] = normalizeYAML(vv)
		}
		return out
	case []interface{}:
		out := make([]interface{}, len(x))
		for i, vv := range x {
			out[i] = normalizeYAML(vv)
		}
		return out
	}
	return v
}

// ---------------------------------------------------------------------------
// Block parsing

type mdLine struct {
	text  string // content with container prefixes stripped
	start int    // offset of text in the raw source
	end   int    // offset of the end of the text in the raw source
}

type mdBlock struct {
	kind     string // "paragraph", "heading", "code", "html", "quote", "list", "hr", "linkdef"
	level    int
	lines    []mdLine
	children []*mdBlock
	// For headings: the raw offset right after the heading content.
	contentEnd int
}

type mdLinkDef struct {
	dest  string
	title string
}

type mdParser struct {
	src     string
	linkDefs map[string]mdLinkDef
}

func splitLines(src string) []mdLine {
	var lines []mdLine
	pos := 0
	for pos < len(src) {
		nl := strings.IndexByte(src[pos:], '\n')
		var end int
		if nl < 0 {
			end = len(src)
		} else {
			end = pos + nl
		}
		text := src[pos:end]
		textEnd := end
		if strings.HasSuffix(text, "\r") {
			text = text[:len(text)-1]
			textEnd--
		}
		lines = append(lines, mdLine{text: text, start: pos, end: textEnd})
		if nl < 0 {
			break
		}
		pos = end + 1
	}
	return lines
}

func isBlankLine(s string) bool {
	return strings.TrimSpace(s) == ""
}

func leadingSpaces(s string) int {
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

// expandTabs converts leading tabs to spaces for indentation purposes.
func indentWidth(s string) int {
	w := 0
	for _, c := range s {
		if c == ' ' {
			w++
		} else if c == '\t' {
			w += 4 - (w % 4)
		} else {
			break
		}
	}
	return w
}

var atxHeadingRe = regexp.MustCompile(`^ {0,3}(#{1,6})([ \t]+|$)`)
var thematicBreakRe = regexp.MustCompile(`^ {0,3}((\*[ \t]*){3,}|(-[ \t]*){3,}|(_[ \t]*){3,})$`)
var setextRe = regexp.MustCompile(`^ {0,3}(=+|-+)[ \t]*$`)
var fenceOpenRe = regexp.MustCompile("^( {0,3})(`{3,}|~{3,})(.*)$")
var bulletRe = regexp.MustCompile(`^( {0,3})([-+*])([ \t]+|$)`)
var orderedRe = regexp.MustCompile(`^( {0,3})(\d{1,9})([.)])([ \t]+|$)`)
var blockquoteRe = regexp.MustCompile(`^ {0,3}>`)
var htmlBlockStartRe = regexp.MustCompile(`^ {0,3}(<[A-Za-z][A-Za-z0-9-]*(\s|/?>|$)|</[A-Za-z][A-Za-z0-9-]*(\s|>|$)|<!--|<\?|<![A-Z]|<!\[CDATA\[)`)
var linkDefRe = regexp.MustCompile(`^ {0,3}\[((?:[^\]\\]|\\.)+)\]:[ \t]*(<[^>]*>|\S+)(?:[ \t]+("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|\((?:[^)\\]|\\.)*\)))?[ \t]*$`)

func (p *mdParser) parseBlocks(lines []mdLine) []*mdBlock {
	var blocks []*mdBlock
	i := 0
	for i < len(lines) {
		line := lines[i]
		if isBlankLine(line.text) {
			i++
			continue
		}
		// Fenced code block
		if m := fenceOpenRe.FindStringSubmatch(line.text); m != nil {
			fence := m[2]
			info := m[3]
			if !(fence[0] == '`' && strings.Contains(info, "`")) {
				b := &mdBlock{kind: "code"}
				j := i + 1
				for j < len(lines) {
					t := strings.TrimLeft(lines[j].text, " ")
					if leadingSpaces(lines[j].text) <= 3 && strings.HasPrefix(t, fence) && strings.TrimSpace(strings.TrimLeft(t, string(fence[0]))) == "" && len(strings.TrimRight(t, " \t")) >= len(fence) && strings.Trim(strings.TrimRight(t, " \t"), string(fence[0])) == "" {
						j++
						break
					}
					j++
				}
				b.lines = lines[i:j]
				blocks = append(blocks, b)
				i = j
				continue
			}
		}
		// Indented code block
		if indentWidth(line.text) >= 4 {
			b := &mdBlock{kind: "code"}
			j := i
			for j < len(lines) && (indentWidth(lines[j].text) >= 4 || isBlankLine(lines[j].text)) {
				j++
			}
			// trim trailing blank lines
			for j > i && isBlankLine(lines[j-1].text) {
				j--
			}
			b.lines = lines[i:j]
			blocks = append(blocks, b)
			i = j
			continue
		}
		// ATX heading
		if m := atxHeadingRe.FindStringSubmatch(line.text); m != nil {
			level := len(m[1])
			rest := line.text[len(m[0]):]
			// strip closing sequence
			content := strings.TrimRight(rest, " \t")
			trimmed := strings.TrimRight(content, "#")
			if trimmed != content {
				if trimmed == "" || strings.HasSuffix(trimmed, " ") || strings.HasSuffix(trimmed, "\t") {
					content = strings.TrimRight(trimmed, " \t")
				}
			}
			leadWS := len(content) - len(strings.TrimLeft(content, " \t"))
			content = strings.TrimLeft(content, " \t")
			startOff := line.start + len(m[0]) + leadWS
			b := &mdBlock{kind: "heading", level: level}
			b.lines = []mdLine{{text: content, start: startOff, end: startOff + len(content)}}
			b.contentEnd = startOff + len(content)
			blocks = append(blocks, b)
			i++
			continue
		}
		// Thematic break
		if thematicBreakRe.MatchString(line.text) {
			blocks = append(blocks, &mdBlock{kind: "hr", lines: []mdLine{line}})
			i++
			continue
		}
		// Block quote
		if blockquoteRe.MatchString(line.text) {
			var inner []mdLine
			j := i
			for j < len(lines) {
				l := lines[j]
				if blockquoteRe.MatchString(l.text) {
					idx := strings.IndexByte(l.text, '>')
					off := idx + 1
					if off < len(l.text) && l.text[off] == ' ' {
						off++
					}
					inner = append(inner, mdLine{text: l.text[off:], start: l.start + off, end: l.end})
					j++
					continue
				}
				// lazy continuation
				if isBlankLine(l.text) || !p.lazyContinues(inner, l) {
					break
				}
				inner = append(inner, l)
				j++
			}
			b := &mdBlock{kind: "quote"}
			b.children = p.parseBlocks(inner)
			blocks = append(blocks, b)
			i = j
			continue
		}
		// HTML block
		if htmlBlockStartRe.MatchString(line.text) {
			b := &mdBlock{kind: "html"}
			j := i
			t := strings.TrimLeft(line.text, " ")
			if strings.HasPrefix(t, "<!--") {
				for j < len(lines) {
					if strings.Contains(lines[j].text, "-->") {
						j++
						break
					}
					j++
				}
			} else {
				for j < len(lines) && !isBlankLine(lines[j].text) {
					j++
				}
			}
			b.lines = lines[i:j]
			blocks = append(blocks, b)
			i = j
			continue
		}
		// List
		if bm := bulletRe.FindStringSubmatch(line.text); bm != nil || orderedRe.MatchString(line.text) {
			b, next := p.parseList(lines, i)
			blocks = append(blocks, b)
			i = next
			continue
		}
		// Paragraph (possibly link reference definitions, setext heading)
		j := i
		var paraLines []mdLine
		for j < len(lines) {
			l := lines[j]
			if j > i {
				if isBlankLine(l.text) {
					break
				}
				if setextRe.MatchString(l.text) {
					// setext heading
					level := 2
					if strings.Contains(l.text, "=") {
						level = 1
					}
					b := &mdBlock{kind: "heading", level: level}
					b.lines = trimParagraphLines(paraLines)
					b.contentEnd = b.lines[len(b.lines)-1].end
					blocks = append(blocks, b)
					i = j + 1
					paraLines = nil
					break
				}
				if p.interruptsParagraph(l.text) {
					break
				}
			}
			paraLines = append(paraLines, l)
			j++
		}
		if paraLines == nil {
			continue
		}
		// link reference definitions at the beginning of the paragraph
		for len(paraLines) > 0 {
			m := linkDefRe.FindStringSubmatch(paraLines[0].text)
			if m == nil {
				break
			}
			label := normalizeLabel(m[1])
			dest := m[2]
			if strings.HasPrefix(dest, "<") && strings.HasSuffix(dest, ">") {
				dest = dest[1 : len(dest)-1]
			}
			title := ""
			if m[3] != "" {
				title = m[3][1 : len(m[3])-1]
			}
			if _, exists := p.linkDefs[label]; !exists {
				p.linkDefs[label] = mdLinkDef{dest: dest, title: title}
			}
			paraLines = paraLines[1:]
		}
		if len(paraLines) > 0 {
			b := &mdBlock{kind: "paragraph"}
			b.lines = trimParagraphLines(paraLines)
			blocks = append(blocks, b)
		}
		i = j
	}
	return blocks
}

func trimParagraphLines(lines []mdLine) []mdLine {
	out := make([]mdLine, len(lines))
	for i, l := range lines {
		t := l.text
		lead := len(t) - len(strings.TrimLeft(t, " \t"))
		if i == 0 {
			t = t[lead:]
			out[i] = mdLine{text: t, start: l.start + lead, end: l.end}
		} else {
			t = t[lead:]
			out[i] = mdLine{text: t, start: l.start + lead, end: l.end}
		}
	}
	// trailing whitespace of the last line
	last := &out[len(out)-1]
	trimmed := strings.TrimRight(last.text, " \t")
	last.end -= len(last.text) - len(trimmed)
	last.text = trimmed
	return out
}

func normalizeLabel(s string) string {
	s = strings.ToLower(strings.TrimSpace(s))
	return strings.Join(strings.Fields(s), " ")
}

func (p *mdParser) interruptsParagraph(text string) bool {
	if atxHeadingRe.MatchString(text) {
		return true
	}
	if fenceOpenRe.MatchString(text) {
		return true
	}
	if blockquoteRe.MatchString(text) {
		return true
	}
	if thematicBreakRe.MatchString(text) {
		return true
	}
	if htmlBlockStartRe.MatchString(text) {
		return true
	}
	if m := bulletRe.FindStringSubmatch(text); m != nil {
		if strings.TrimSpace(text[len(m[0]):]) != "" {
			return true
		}
	}
	if m := orderedRe.FindStringSubmatch(text); m != nil {
		if m[2] == "1" && strings.TrimSpace(text[len(m[0]):]) != "" {
			return true
		}
	}
	return false
}

func (p *mdParser) lazyContinues(inner []mdLine, l mdLine) bool {
	if len(inner) == 0 {
		return false
	}
	// Only continue if the last inner block would be a paragraph.
	blocks := p.parseBlocksNoDefs(inner)
	if len(blocks) == 0 {
		return false
	}
	last := blocks[len(blocks)-1]
	for last.kind == "quote" || last.kind == "list" {
		if len(last.children) == 0 {
			return false
		}
		last = last.children[len(last.children)-1]
	}
	if last.kind != "paragraph" {
		return false
	}
	return !p.interruptsParagraph(l.text) && indentWidth(l.text) < 4
}

func (p *mdParser) parseBlocksNoDefs(lines []mdLine) []*mdBlock {
	saved := p.linkDefs
	p.linkDefs = map[string]mdLinkDef{}
	for k, v := range saved {
		p.linkDefs[k] = v
	}
	blocks := p.parseBlocks(lines)
	p.linkDefs = saved
	return blocks
}

func (p *mdParser) parseList(lines []mdLine, start int) (*mdBlock, int) {
	list := &mdBlock{kind: "list"}
	i := start
	first := lines[i].text
	var marker string
	ordered := false
	if m := bulletRe.FindStringSubmatch(first); m != nil {
		marker = m[2]
	} else if m := orderedRe.FindStringSubmatch(first); m != nil {
		marker = m[3]
		ordered = true
	}
	for i < len(lines) {
		line := lines[i]
		var m []string
		if ordered {
			m = orderedRe.FindStringSubmatch(line.text)
			if m == nil || m[3] != marker {
				break
			}
		} else {
			m = bulletRe.FindStringSubmatch(line.text)
			if m == nil || m[2] != marker {
				break
			}
		}
		markerEnd := len(m[0])
		// content indent
		spacesAfter := len(m[len(m)-1])
		contentIndent := markerEnd
		if spacesAfter >= 5 || strings.TrimSpace(line.text[markerEnd:]) == "" {
			contentIndent = markerEnd - spacesAfter + 1
			if spacesAfter == 0 {
				contentIndent = markerEnd
			}
		}
		var itemLines []mdLine
		firstText := line.text[markerEnd:]
		if strings.TrimSpace(line.text[markerEnd:]) == "" {
			firstText = ""
		}
		itemLines = append(itemLines, mdLine{text: firstText, start: line.start + markerEnd, end: line.end})
		j := i + 1
		for j < len(lines) {
			l := lines[j]
			if isBlankLine(l.text) {
				// look ahead: next non-blank line must be indented
				k := j
				for k < len(lines) && isBlankLine(lines[k].text) {
					k++
				}
				if k >= len(lines) || indentWidth(lines[k].text) < contentIndent {
					break
				}
				for ; j < k; j++ {
					itemLines = append(itemLines, mdLine{text: "", start: lines[j].start, end: lines[j].end})
				}
				continue
			}
			if indentWidth(l.text) >= contentIndent {
				off := stripIndent(l.text, contentIndent)
				itemLines = append(itemLines, mdLine{text: l.text[off:], start: l.start + off, end: l.end})
				j++
				continue
			}
			// lazy continuation
			if p.lazyContinues(itemLines, l) {
				itemLines = append(itemLines, l)
				j++
				continue
			}
			break
		}
		item := &mdBlock{kind: "item"}
		item.children = p.parseBlocks(itemLines)
		list.children = append(list.children, item)
		i = j
		// A blank line followed by a non-list line ends the list; handled by the marker check above.
	}
	return list, i
}

// stripIndent returns the byte offset after removing n columns of indentation.
func stripIndent(s string, n int) int {
	w := 0
	i := 0
	for i < len(s) && w < n {
		if s[i] == ' ' {
			w++
		} else if s[i] == '\t' {
			w += 4 - (w % 4)
		} else {
			break
		}
		i++
	}
	return i
}

// ---------------------------------------------------------------------------
// Inline parsing

type inlineLink struct {
	title string
	href  string
	kind  string
	rels  []string
}

type inlineResult struct {
	text  strings.Builder
	links []inlineLink
	tags  []string
}

type inlineParser struct {
	opts     MarkdownOptions
	linkDefs map[string]mdLinkDef
}

var autolinkRe = regexp.MustCompile(`^<([A-Za-z][A-Za-z0-9+.\-]{1,31}:[^\s<>]*)>`)
var emailAutolinkRe = regexp.MustCompile("^<[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*>")
var htmlTagRe = regexp.MustCompile(`^(?:<[A-Za-z][A-Za-z0-9-]*(?:\s+[A-Za-z_:][A-Za-z0-9_.:-]*(?:\s*=\s*(?:[^\s"'=<>` + "`" + `]+|'[^']*'|"[^"]*"))?)*\s*/?>|</[A-Za-z][A-Za-z0-9-]*\s*>|<\?.*?\?>|<![A-Za-z]+[^>]*>|<!\[CDATA\[.*?\]\]>)`)
var urlLinkifyRe = regexp.MustCompile(`^https?://[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b[-a-zA-Z0-9()@:%_\+.~#?&/=]*`)
var wwwLinkifyRe = regexp.MustCompile(`^www\.[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b[-a-zA-Z0-9()@:%_\+.~#?&/=]*`)

func isTagChar(r rune) bool {
	if unicode.IsLetter(r) || unicode.IsNumber(r) {
		return true
	}
	switch r {
	case '-', '_', '/', '\'', ':', '@', '$', '%', '&', '+', '=', '~':
		return true
	}
	return false
}

func isASCIIPunct(c byte) bool {
	return (c >= '!' && c <= '/') || (c >= ':' && c <= '@') || (c >= '[' && c <= '`') || (c >= '{' && c <= '~')
}

func isAlnumByte(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func allDigits(s string) bool {
	if s == "" {
		return true
	}
	for _, r := range s {
		if !unicode.IsDigit(r) {
			return false
		}
	}
	return true
}

// parse parses inline content. atEnd indicates that the text ends exactly
// at the end of the enclosing block content (used for the wiki-link quirk).
func (ip *inlineParser) parse(s string, res *inlineResult) {
	ip.parseRange(s, res, true)
}

func (ip *inlineParser) parseRange(s string, res *inlineResult, topLevel bool) {
	// Emphasis delimiters are handled by a simple pass removing matched runs.
	i := 0
	n := len(s)
	prevChar := func(pos int) rune {
		if pos <= 0 {
			return 0
		}
		r, _ := utf8.DecodeLastRuneInString(s[:pos])
		return r
	}
	for i < n {
		c := s[i]
		switch {
		case c == '\\':
			if i+1 < n && isASCIIPunct(s[i+1]) {
				res.text.WriteString(s[i : i+2])
				i += 2
			} else {
				res.text.WriteByte(c)
				i++
			}
		case c == '`':
			// code span
			j := i
			for j < n && s[j] == '`' {
				j++
			}
			run := s[i:j]
			rest := s[j:]
			closed := -1
			k := 0
			for k < len(rest) {
				idx := strings.Index(rest[k:], run)
				if idx < 0 {
					break
				}
				end := k + idx + len(run)
				if end < len(rest) && rest[end] == '`' {
					// longer run, skip
					for end < len(rest) && rest[end] == '`' {
						end++
					}
					k = end
					continue
				}
				closed = k + idx
				break
			}
			if closed < 0 {
				res.text.WriteString(run)
				i = j
				continue
			}
			content := rest[:closed]
			content = strings.ReplaceAll(content, "\n", " ")
			if len(content) >= 2 && content[0] == ' ' && content[len(content)-1] == ' ' && strings.TrimSpace(content) != "" {
				content = content[1 : len(content)-1]
			}
			res.text.WriteString(content)
			i = j + closed + len(run)
		case c == '<':
			if m := autolinkRe.FindStringSubmatch(s[i:]); m != nil {
				res.links = append(res.links, inlineLink{title: m[1], href: m[1], kind: "implicit"})
				i += len(m[0])
				continue
			}
			if m := emailAutolinkRe.FindString(s[i:]); m != "" {
				i += len(m)
				continue
			}
			if strings.HasPrefix(s[i:], "<!--") {
				end := strings.Index(s[i+4:], "-->")
				if end >= 0 {
					i += 4 + end + 3
					continue
				}
			}
			if m := htmlTagRe.FindString(s[i:]); m != "" {
				i += len(m)
				continue
			}
			res.text.WriteByte(c)
			i++
		case c == '!' && i+1 < n && s[i+1] == '[':
			// image
			end, ok := ip.matchBracket(s, i+1)
			if !ok {
				res.text.WriteByte(c)
				i++
				continue
			}
			alt := s[i+2 : end]
			consumed, dest, _, found := ip.parseLinkTail(s, end+1, alt)
			if !found {
				res.text.WriteByte(c)
				i++
				continue
			}
			_ = dest
			sub := &inlineResult{}
			ip.parseRange(alt, sub, false)
			res.text.WriteString(sub.text.String())
			res.tags = append(res.tags, sub.tags...)
			i = consumed
		case c == '[':
			// wiki link?
			if i+1 < n && s[i+1] == '[' && (i+2 >= n || s[i+2] != '[') {
				if end := strings.Index(s[i+2:], "]]"); end >= 0 {
					inner := s[i+2 : i+2+end]
					if !strings.Contains(inner, "\n") || true {
						href := inner
						label := ""
						if pipe := strings.Index(inner, "|"); pipe >= 0 {
							href = inner[:pipe]
							label = inner[pipe+1:]
						}
						href = strings.TrimSpace(href)
						label = strings.TrimSpace(label)
						var rels []string
						if strings.HasPrefix(href, "#") {
							href = strings.TrimSpace(href[1:])
							rels = append(rels, "up")
						} else if prevChar(i) == '#' {
							rels = append(rels, "up")
						}
						if href != "" {
							after := i + 2 + end + 2
							if after < n && s[after] == '#' {
								rels = append(rels, "down")
								after++
							}
							text := label
							if text == "" {
								text = href
							}
							title := text
							res.links = append(res.links, inlineLink{title: title, href: href, kind: "wiki-link", rels: rels})
							res.text.WriteString(text)
							if topLevel && i+2+end+2 == n {
								// goldmark/zk quirk: a wiki-link closing at the very
								// end of the block leaves a stray bracket.
								res.text.WriteString("]")
							}
							i = after
							continue
						}
					}
				}
			}
			end, ok := ip.matchBracket(s, i)
			if !ok {
				res.text.WriteByte(c)
				i++
				continue
			}
			text := s[i+1 : end]
			consumed, dest, title, found := ip.parseLinkTail(s, end+1, text)
			if !found {
				res.text.WriteByte(c)
				i++
				continue
			}
			sub := &inlineResult{}
			ip.parseRange(text, sub, false)
			res.text.WriteString(sub.text.String())
			res.tags = append(res.tags, sub.tags...)
			res.links = append(res.links, sub.links...)
			if dest != "" {
				var rels []string
				if title != "" {
					rels = strings.Fields(title)
				}
				res.links = append(res.links, inlineLink{title: sub.text.String(), href: dest, kind: "markdown", rels: rels})
			}
			i = consumed
		case c == '#' && ip.opts.Hashtags:
			tag, consumed, ok := ip.parseHashtag(s, i, prevChar(i))
			if ok {
				res.tags = append(res.tags, tag)
				i = consumed
				continue
			}
			res.text.WriteByte(c)
			i++
		case c == ':' && ip.opts.ColonTags:
			tags, consumed, ok := ip.parseColonTags(s, i, prevChar(i))
			if ok {
				res.tags = append(res.tags, tags...)
				i = consumed
				continue
			}
			res.text.WriteByte(c)
			i++
		case (c == 'h' || c == 'w') && (i == 0 || !isAlnumByte(s[i-1])):
			var m string
			isWWW := false
			if c == 'h' {
				m = urlLinkifyRe.FindString(s[i:])
			} else {
				m = wwwLinkifyRe.FindString(s[i:])
				isWWW = true
			}
			if m == "" {
				res.text.WriteByte(c)
				i++
				continue
			}
			m = trimLinkifyTail(m)
			href := m
			if isWWW {
				href = "http://" + m
			}
			res.links = append(res.links, inlineLink{title: m, href: href, kind: "implicit"})
			i += len(m)
		case c == '*' || c == '_':
			j := i
			for j < n && s[j] == c {
				j++
			}
			if ip.emphasisMatched(s, i, j, c) {
				// drop delimiter run
			} else {
				res.text.WriteString(s[i:j])
			}
			i = j
		default:
			res.text.WriteByte(c)
			i++
		}
	}
}

// emphasisMatched decides whether a delimiter run should be dropped from the
// text content (i.e. it is part of an emphasis). This is an approximation of
// the CommonMark delimiter algorithm.
func (ip *inlineParser) emphasisMatched(s string, start, end int, c byte) bool {
	run := s[start:end]
	before := rune(' ')
	if start > 0 {
		before, _ = utf8.DecodeLastRuneInString(s[:start])
	}
	after := rune(' ')
	if end < len(s) {
		after, _ = utf8.DecodeRuneInString(s[end:])
	}
	leftFlanking := !unicode.IsSpace(after) && (!isPunctRune(after) || unicode.IsSpace(before) || isPunctRune(before))
	rightFlanking := !unicode.IsSpace(before) && (!isPunctRune(before) || unicode.IsSpace(after) || isPunctRune(after))
	if c == '_' {
		leftFlanking = leftFlanking && (!rightFlanking || isPunctRune(before))
		rightFlanking = rightFlanking && (!leftFlanking || isPunctRune(after))
	}
	if leftFlanking {
		// look for a closer later
		idx := strings.Index(s[end:], run)
		for idx >= 0 {
			cs := end + idx
			ce := cs + len(run)
			b, _ := utf8.DecodeLastRuneInString(s[:cs])
			a := rune(' ')
			if ce < len(s) {
				a, _ = utf8.DecodeRuneInString(s[ce:])
			}
			rf := !unicode.IsSpace(b) && (!isPunctRune(b) || unicode.IsSpace(a) || isPunctRune(a))
			if rf && (ce >= len(s) || s[ce] != c) {
				return true
			}
			next := strings.Index(s[ce:], run)
			if next < 0 {
				break
			}
			idx = (ce - end) + next
		}
		return false
	}
	if rightFlanking {
		// look for an opener earlier
		idx := strings.LastIndex(s[:start], run)
		for idx >= 0 {
			os := idx
			oe := idx + len(run)
			b := rune(' ')
			if os > 0 {
				b, _ = utf8.DecodeLastRuneInString(s[:os])
			}
			a, _ := utf8.DecodeRuneInString(s[oe:])
			lf := !unicode.IsSpace(a) && (!isPunctRune(a) || unicode.IsSpace(b) || isPunctRune(b))
			if lf && (os == 0 || s[os-1] != c) {
				return true
			}
			if os == 0 {
				break
			}
			idx = strings.LastIndex(s[:os], run)
		}
	}
	return false
}

func isPunctRune(r rune) bool {
	return unicode.IsPunct(r) || unicode.IsSymbol(r)
}

func trimLinkifyTail(m string) string {
	for len(m) > 0 {
		last := m[len(m)-1]
		if strings.IndexByte("?!.,:*_~", last) >= 0 {
			m = m[:len(m)-1]
			continue
		}
		if last == ')' {
			if strings.Count(m, ")") > strings.Count(m, "(") {
				m = m[:len(m)-1]
				continue
			}
		}
		break
	}
	return m
}

// matchBracket finds the closing ']' for the '[' at position start,
// honoring nesting and escapes and skipping code spans.
func (ip *inlineParser) matchBracket(s string, start int) (int, bool) {
	depth := 0
	i := start
	for i < len(s) {
		c := s[i]
		switch c {
		case '\\':
			i += 2
			continue
		case '`':
			j := i
			for j < len(s) && s[j] == '`' {
				j++
			}
			run := s[i:j]
			if idx := strings.Index(s[j:], run); idx >= 0 {
				i = j + idx + len(run)
				continue
			}
			i = j
			continue
		case '[':
			depth++
		case ']':
			depth--
			if depth == 0 {
				return i, true
			}
		}
		i++
	}
	return 0, false
}

// parseLinkTail parses what follows a link text: (dest "title"), [ref], or
// nothing (shortcut reference). Returns the end position, dest, title and
// whether a link was found.
func (ip *inlineParser) parseLinkTail(s string, pos int, text string) (int, string, string, bool) {
	if pos < len(s) && s[pos] == '(' {
		// inline link
		i := pos + 1
		for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') {
			i++
		}
		var dest string
		if i < len(s) && s[i] == '<' {
			end := strings.IndexByte(s[i:], '>')
			if end < 0 || strings.Contains(s[i:i+end], "\n") {
				return 0, "", "", false
			}
			dest = s[i+1 : i+end]
			i += end + 1
		} else {
			j := i
			depth := 0
			for j < len(s) {
				c := s[j]
				if c == '\\' && j+1 < len(s) {
					j += 2
					continue
				}
				if c == ' ' || c == '\t' || c == '\n' {
					break
				}
				if c == '(' {
					depth++
				} else if c == ')' {
					if depth == 0 {
						break
					}
					depth--
				}
				if c < 0x20 {
					return 0, "", "", false
				}
				j++
			}
			dest = s[i:j]
			i = j
		}
		for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') {
			i++
		}
		title := ""
		if i < len(s) && (s[i] == '"' || s[i] == '\'' || s[i] == '(') {
			closer := s[i]
			if closer == '(' {
				closer = ')'
			}
			j := i + 1
			for j < len(s) && s[j] != closer {
				if s[j] == '\\' {
					j++
				}
				j++
			}
			if j >= len(s) {
				return 0, "", "", false
			}
			title = s[i+1 : j]
			i = j + 1
			for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n') {
				i++
			}
		}
		if i < len(s) && s[i] == ')' {
			return i + 1, unescapeMD(dest), unescapeMD(title), true
		}
		return 0, "", "", false
	}
	if pos < len(s) && s[pos] == '[' {
		end := strings.IndexByte(s[pos:], ']')
		if end >= 0 {
			label := s[pos+1 : pos+end]
			if label == "" {
				label = text
			}
			if def, ok := ip.linkDefs[normalizeLabel(label)]; ok {
				return pos + end + 1, def.dest, def.title, true
			}
			return 0, "", "", false
		}
	}
	// shortcut reference
	if def, ok := ip.linkDefs[normalizeLabel(text)]; ok {
		return pos, def.dest, def.title, true
	}
	return 0, "", "", false
}

func unescapeMD(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) && isASCIIPunct(s[i+1]) {
			sb.WriteByte(s[i+1])
			i++
			continue
		}
		sb.WriteByte(s[i])
	}
	return sb.String()
}

func (ip *inlineParser) parseHashtag(s string, i int, prev rune) (string, int, bool) {
	if prev != 0 && isTagChar(prev) {
		return "", 0, false
	}
	// Multiword tag: #word word#
	if ip.opts.MultiwordTags {
		if tag, consumed, ok := ip.parseMultiwordTag(s, i); ok {
			return tag, consumed, true
		}
	}
	j := i + 1
	var sb strings.Builder
	for j < len(s) {
		r, size := utf8.DecodeRuneInString(s[j:])
		if r == '\\' {
			j += size
			continue
		}
		if !isTagChar(r) {
			break
		}
		sb.WriteRune(r)
		j += size
	}
	tag := sb.String()
	if tag == "" || allDigits(tag) {
		return "", 0, false
	}
	if j < len(s) && s[j] == '#' {
		return "", 0, false
	}
	return tag, j, true
}

func (ip *inlineParser) parseMultiwordTag(s string, i int) (string, int, bool) {
	j := i + 1
	var sb strings.Builder
	for j < len(s) {
		r, size := utf8.DecodeRuneInString(s[j:])
		if r == '#' {
			tag := strings.TrimSpace(sb.String())
			if tag == "" || allDigits(tag) || !strings.Contains(tag, " ") && false {
				return "", 0, false
			}
			if strings.ContainsAny(tag, "\n") {
				return "", 0, false
			}
			return tag, j + 1, true
		}
		if r == '\n' {
			return "", 0, false
		}
		if !isTagChar(r) && r != ' ' {
			return "", 0, false
		}
		sb.WriteRune(r)
		j += size
	}
	return "", 0, false
}

func (ip *inlineParser) parseColonTags(s string, i int, prev rune) ([]string, int, bool) {
	if prev != 0 && isTagChar(prev) {
		return nil, 0, false
	}
	var tags []string
	j := i + 1
	var sb strings.Builder
	for j < len(s) {
		r, size := utf8.DecodeRuneInString(s[j:])
		if r == ':' {
			tag := sb.String()
			if tag == "" {
				return nil, 0, false
			}
			tags = append(tags, tag)
			sb.Reset()
			j += size
			// continue if another tag follows
			if j < len(s) {
				r2, _ := utf8.DecodeRuneInString(s[j:])
				if isTagChar(r2) && r2 != ':' {
					continue
				}
			}
			return tags, j, true
		}
		if !isTagChar(r) {
			return nil, 0, false
		}
		sb.WriteRune(r)
		j += size
	}
	return nil, 0, false
}

// ---------------------------------------------------------------------------
// Note parsing

type mdContainer struct {
	block *mdBlock
}

// collectInlineBlocks returns inline-containing blocks in document order.
func collectInlineBlocks(blocks []*mdBlock, out *[]*mdBlock) {
	for _, b := range blocks {
		switch b.kind {
		case "paragraph", "heading":
			*out = append(*out, b)
		case "quote", "list", "item":
			collectInlineBlocks(b.children, out)
		}
	}
}

func inlineText(b *mdBlock) string {
	var parts []string
	for _, l := range b.lines {
		parts = append(parts, l.text)
	}
	return strings.Join(parts, "\n")
}

// ParseMarkdown parses a note's content.
func ParseMarkdown(content string, opts MarkdownOptions) (*ParsedNote, error) {
	note := &ParsedNote{RawContent: content, Metadata: map[string]interface{}{}}
	meta, bodyStart, hasFM, err := parseFrontmatter(content)
	if err != nil {
		return nil, err
	}
	if hasFM {
		note.Metadata = meta
	}
	note.WordCount = len(strings.Fields(content))

	p := &mdParser{src: content, linkDefs: map[string]mdLinkDef{}}
	lines := splitLines(content[bodyStart:])
	for i := range lines {
		lines[i].start += bodyStart
		lines[i].end += bodyStart
	}
	blocks := p.parseBlocks(lines)

	var inlineBlocks []*mdBlock
	collectInlineBlocks(blocks, &inlineBlocks)

	ip := &inlineParser{opts: opts, linkDefs: p.linkDefs}

	var titleBlock *mdBlock
	var tags []string
	seenTags := map[string]bool{}
	addTag := func(t string) {
		if t == "" {
			return
		}
		if !seenTags[t] {
			seenTags[t] = true
			tags = append(tags, t)
		}
	}

	for _, b := range inlineBlocks {
		text := inlineText(b)
		res := &inlineResult{}
		ip.parse(text, res)
		if b.kind == "heading" && titleBlock == nil {
			titleBlock = b
			t := res.text.String()
			t = removeSoftBreaks(t)
			note.Title = strings.TrimSpace(t)
		}
		for _, t := range res.tags {
			addTag(t)
		}
		if len(res.links) > 0 {
			start := b.lines[0].start
			end := b.lines[len(b.lines)-1].end
			snippet := content[start:end]
			for _, l := range res.links {
				note.Links = append(note.Links, Link{
					Title:        l.title,
					Href:         l.href,
					Type:         l.kind,
					Rels:         l.rels,
					Snippet:      snippet,
					SnippetStart: start,
					SnippetEnd:   end,
				})
			}
		}
	}

	// Title from metadata takes precedence.
	titleFromMeta := false
	if hasFM {
		if t, ok := meta["title"]; ok && t != nil {
			if ts, ok := t.(string); ok {
				note.Title = ts
				titleFromMeta = true
			} else {
				note.Title = fmt.Sprint(t)
				titleFromMeta = true
			}
		}
	}

	// Body
	switch {
	case titleFromMeta:
		note.Body = strings.TrimSpace(content[bodyStart:])
	case titleBlock != nil:
		note.Body = strings.TrimSpace(content[titleBlock.contentEnd:])
	default:
		note.Body = strings.TrimSpace(content)
	}
	note.Lead = extractLead(note.Body)

	// Tags from metadata
	if hasFM {
		for _, key := range []string{"tags", "keywords"} {
			if v, ok := meta[key]; ok {
				for _, t := range metadataTags(v) {
					addTag(t)
				}
			}
		}
	}
	note.Tags = tags
	if note.Tags == nil {
		note.Tags = []string{}
	}
	return note, nil
}

func removeSoftBreaks(t string) string {
	if !strings.Contains(t, "\n") {
		return t
	}
	lines := strings.Split(t, "\n")
	for i, l := range lines {
		l = strings.TrimRight(l, " \t")
		l = strings.TrimSuffix(l, "\\")
		if i > 0 {
			l = strings.TrimLeft(l, " \t")
		}
		lines[i] = l
	}
	return strings.Join(lines, "")
}

func extractLead(body string) string {
	if body == "" {
		return ""
	}
	lines := strings.Split(body, "\n")
	var out []string
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			break
		}
		out = append(out, l)
	}
	return strings.TrimSpace(strings.Join(out, "\n"))
}

func metadataTags(v interface{}) []string {
	var out []string
	switch x := v.(type) {
	case []interface{}:
		for _, item := range x {
			out = append(out, strings.TrimPrefix(fmt.Sprint(item), "#"))
		}
	case string:
		for _, f := range strings.Fields(x) {
			out = append(out, strings.TrimPrefix(f, "#"))
		}
	case nil:
	default:
		out = append(out, strings.TrimPrefix(fmt.Sprint(x), "#"))
	}
	return out
}

// ---------------------------------------------------------------------------
// Href resolution

// isExternalHref reports whether the href points outside of the notebook.
func isExternalHref(href string) bool {
	u, err := url.Parse(href)
	if err != nil {
		return false
	}
	return u.Scheme != "" && u.Host != ""
}

// resolveMarkdownHref converts a markdown link href into a notebook-relative
// path. It returns ok=false when the href is empty or outside the notebook.
func resolveMarkdownHref(href string, noteRelDir string, notebookDir string) (string, bool, string) {
	if href == "" {
		return "", false, ""
	}
	if isExternalHref(href) {
		return href, true, ""
	}
	decoded, err := url.PathUnescape(href)
	if err == nil {
		href = decoded
	}
	abs := filepath.Join(notebookDir, noteRelDir, href)
	rel, err := filepath.Rel(notebookDir, abs)
	if err != nil || rel == ".." || strings.HasPrefix(rel, "../") {
		return "", false, abs
	}
	rel = filepath.ToSlash(rel)
	if rel == "." {
		rel = ""
	}
	return rel, true, ""
}

func cleanWikiHref(href string) string {
	return href
}

