package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// Notebook represents an opened notebook.
type Notebook struct {
	Path   string // absolute path of the notebook root
	Config Config
	db     *DB
}

const zkDirName = ".zk"

var errNotebookNotFound = errors.New("notebook not found")

// findNotebookDir looks for a notebook in the given directory or its parents.
func findNotebookDir(dir string) (string, bool) {
	dir = filepath.Clean(dir)
	for {
		if fi, err := os.Stat(filepath.Join(dir, zkDirName)); err == nil && fi.IsDir() {
			return dir, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

// loadGlobalConfig loads the user-level config, if any.
func loadGlobalConfig() (Config, error) {
	cfg := defaultConfig()
	path := locateGlobalConfig()
	if path == "" {
		return cfg, nil
	}
	content, err := os.ReadFile(path)
	if err != nil {
		return cfg, nil
	}
	parsed, err := ParseConfig(content, path, cfg)
	if err != nil {
		return cfg, fmt.Errorf("failed to read config: %w", err)
	}
	return parsed, nil
}

// openNotebook opens the notebook at the given root directory.
func openNotebook(root string, globalCfg Config) (*Notebook, error) {
	cfg := globalCfg
	cfgPath := filepath.Join(root, zkDirName, "config.toml")
	if content, err := os.ReadFile(cfgPath); err == nil {
		parsed, err := ParseConfig(content, cfgPath, cfg)
		if err != nil {
			return nil, fmt.Errorf("failed to read config: %w", err)
		}
		cfg = parsed
	}
	nb := &Notebook{Path: root, Config: cfg}
	return nb, nil
}

func (nb *Notebook) DB() (*DB, error) {
	if nb.db != nil {
		return nb.db, nil
	}
	dbPath := filepath.Join(nb.Path, zkDirName, "notebook.db")
	db, err := OpenDB(dbPath)
	if err != nil {
		return nil, err
	}
	if err := db.Exec("PRAGMA foreign_keys = ON"); err != nil {
		return nil, err
	}
	if err := db.ExecScript(dbSchemaScript); err != nil {
		db.Close()
		return nil, err
	}
	nb.db = db
	return db, nil
}

func (nb *Notebook) Close() {
	if nb.db != nil {
		nb.db.Close()
		nb.db = nil
	}
}

// RelPath converts an absolute path to a notebook-relative path.
func (nb *Notebook) RelPath(abs string) (string, error) {
	rel, err := filepath.Rel(nb.Path, abs)
	if err != nil {
		return "", err
	}
	return filepath.ToSlash(rel), nil
}

func (nb *Notebook) AbsPath(rel string) string {
	return filepath.Join(nb.Path, filepath.FromSlash(rel))
}

func (nb *Notebook) TemplatesDir() string {
	return filepath.Join(nb.Path, zkDirName, "templates")
}

// ResolveTemplatePath resolves a template path relative to the templates dir.
func (nb *Notebook) ResolveTemplatePath(p string) string {
	p = expandPath(p)
	if filepath.IsAbs(p) {
		return p
	}
	return filepath.Join(nb.TemplatesDir(), p)
}

const dbSchemaScript = `
CREATE TABLE IF NOT EXISTS notes (
						id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
						path TEXT NOT NULL,
						sortable_path TEXT NOT NULL,
						title TEXT DEFAULT('') NOT NULL,
						lead TEXT DEFAULT('') NOT NULL,
						body TEXT DEFAULT('') NOT NULL,
						raw_content TEXT DEFAULT('') NOT NULL,
						word_count INTEGER DEFAULT(0) NOT NULL,
						checksum TEXT NOT NULL,
						created DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL,
						modified DATETIME DEFAULT(CURRENT_TIMESTAMP) NOT NULL, metadata TEXT DEFAULT('{}') NOT NULL, filename TEXT DEFAULT('') NOT NULL,
						UNIQUE(path)
					);
CREATE INDEX IF NOT EXISTS index_notes_checksum ON notes (checksum);
CREATE INDEX IF NOT EXISTS index_notes_path ON notes (path);
CREATE TABLE IF NOT EXISTS links (
						id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
						source_id INTEGER NOT NULL REFERENCES notes(id)
							ON DELETE CASCADE,
						target_id INTEGER REFERENCES notes(id)
							ON DELETE SET NULL,
						title TEXT DEFAULT('') NOT NULL,
						href TEXT NOT NULL,
						external INT DEFAULT(0) NOT NULL,
						rels TEXT DEFAULT('') NOT NULL,
						snippet TEXT DEFAULT('') NOT NULL
					, snippet_start INTEGER DEFAULT(0) NOT NULL, snippet_end INTEGER DEFAULT(0) NOT NULL, type TEXT DEFAULT('') NOT NULL);
CREATE INDEX IF NOT EXISTS index_links_source_id_target_id ON links (source_id, target_id);
CREATE VIRTUAL TABLE IF NOT EXISTS notes_fts USING fts5(
						path, title, body,
						content = notes,
						content_rowid = id,
						tokenize = "porter unicode61 remove_diacritics 1 tokenchars '''&/'"
					);
CREATE TRIGGER IF NOT EXISTS trigger_notes_ai AFTER INSERT ON notes BEGIN
						INSERT INTO notes_fts(rowid, path, title, body) VALUES (new.id, new.path, new.title, new.body);
					END;
CREATE TRIGGER IF NOT EXISTS trigger_notes_ad AFTER DELETE ON notes BEGIN
						INSERT INTO notes_fts(notes_fts, rowid, path, title, body) VALUES('delete', old.id, old.path, old.title, old.body);
					END;
CREATE TRIGGER IF NOT EXISTS trigger_notes_au AFTER UPDATE ON notes BEGIN
						INSERT INTO notes_fts(notes_fts, rowid, path, title, body) VALUES('delete', old.id, old.path, old.title, old.body);
						INSERT INTO notes_fts(rowid, path, title, body) VALUES (new.id, new.path, new.title, new.body);
					END;
CREATE TABLE IF NOT EXISTS collections (
						id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
						kind TEXT NO NULL,
						name TEXT NOT NULL,
						UNIQUE(kind, name)
					);
CREATE INDEX IF NOT EXISTS index_collections ON collections (kind, name);
CREATE TABLE IF NOT EXISTS notes_collections (
						id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL,
						note_id INTEGER NOT NULL REFERENCES notes(id)
							ON DELETE CASCADE,
						collection_id INTEGER NOT NULL REFERENCES collections(id)
							ON DELETE CASCADE
					);
CREATE INDEX IF NOT EXISTS index_notes_collections ON notes_collections (note_id, collection_id);
CREATE VIEW IF NOT EXISTS notes_with_metadata AS
					 SELECT n.*, GROUP_CONCAT(c.name, '\x01') AS tags
					   FROM notes n
					   LEFT JOIN notes_collections nc ON nc.note_id = n.id
					   LEFT JOIN collections c ON nc.collection_id = c.id AND c.kind = 'tag'
					  GROUP BY n.id;
CREATE TABLE IF NOT EXISTS metadata (
						key TEXT PRIMARY KEY NOT NULL,
						value TEXT NO NULL
					);
CREATE VIEW IF NOT EXISTS resolved_links AS
					 SELECT l.*, s.path AS source_path, s.title AS source_title, t.path AS target_path, t.title AS target_title
					   FROM links l
					   LEFT JOIN notes s ON l.source_id = s.id
					   LEFT JOIN notes t ON l.target_id = t.id;
CREATE INDEX IF NOT EXISTS index_notes_filename ON notes (filename);
INSERT OR IGNORE INTO metadata (key, value) VALUES ('zk.reindexing_required', 'false');
`

func init() {
	// The GROUP_CONCAT separator is the \x01 character.
	_ = strings.ReplaceAll
}
EOF
echo ok"}

