package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// IndexStats holds the results of an indexing pass.
type IndexStats struct {
	SourceCount   int
	AddedCount    int
	ModifiedCount int
	RemovedCount  int
	Duration      time.Duration
}

func (s IndexStats) String() string {
	return fmt.Sprintf("Indexed %d %s in %s\n  + %d added\n  ~ %d modified\n  - %d removed",
		s.SourceCount, pluralize("note", s.SourceCount), s.Duration, s.AddedCount, s.ModifiedCount, s.RemovedCount)
}

func pluralize(word string, count int) string {
	if count > 1 {
		return word + "s"
	}
	return word
}

type indexedNote struct {
	id       int64
	modified time.Time
	created  time.Time
}

// Index indexes the notes of the notebook.
func (nb *Notebook) Index(force bool, logger func(string)) (IndexStats, error) {
	start := time.Now()
	stats := IndexStats{}
	db, err := nb.DB()
	if err != nil {
		return stats, err
	}

	// Existing notes
	existing := map[string]indexedNote{}
	rows, err := db.Query("SELECT id, path, modified, created FROM notes")
	if err != nil {
		return stats, err
	}
	for rows.Next() {
		var n indexedNote
		var p string
		var mod, cre string
		if err := rows.Scan(&n.id, &p, &mod, &cre); err != nil {
			rows.Close()
			return stats, err
		}
		n.modified, _ = parseDBTime(mod)
		n.created, _ = parseDBTime(cre)
		existing[p] = n
	}
	rows.Close()

	files, err := nb.noteFiles()
	if err != nil {
		return stats, err
	}

	if err := db.Exec("BEGIN"); err != nil {
		return stats, err
	}
	committed := false
	defer func() {
		if !committed {
			db.Exec("ROLLBACK")
		}
	}()

	seen := map[string]bool{}
	for _, f := range files {
		seen[f.rel] = true
		ex, ok := existing[f.rel]
		if ok && !force && ex.modified.Equal(f.modified) {
			if logger != nil {
				logger("- unchanged " + f.rel)
			}
			continue
		}
		content, err := os.ReadFile(f.abs)
		if err != nil {
			return stats, err
		}
		parsed, err := ParseMarkdown(string(content), nb.markdownOptions())
		if err != nil {
			printWarning(fmt.Sprintf("%s: %v", f.abs, err))
			if ok {
				// keep the old version of the note
				if logger != nil {
					logger("- unchanged " + f.rel)
				}
			}
			continue
		}
		if ok {
			if logger != nil {
				logger("- modified " + f.rel)
			}
			if err := nb.updateNote(ex, f, parsed, content); err != nil {
				return stats, err
			}
			stats.ModifiedCount++
		} else {
			if logger != nil {
				logger("- added " + f.rel)
			}
			if err := nb.addNote(f, parsed, content); err != nil {
				return stats, err
			}
			stats.AddedCount++
		}
	}
	// Removed notes
	var removed []string
	for p := range existing {
		if !seen[p] {
			removed = append(removed, p)
		}
	}
	sort.Strings(removed)
	for _, p := range removed {
		if logger != nil {
			logger("- removed " + p)
		}
		if err := db.Exec("DELETE FROM notes WHERE id = ?", existing[p].id); err != nil {
			return stats, err
		}
		stats.RemovedCount++
	}
	if err := db.Exec("UPDATE metadata SET value = 'false' WHERE key = 'zk.reindexing_required'"); err != nil {
		return stats, err
	}
	if err := db.Exec("COMMIT"); err != nil {
		return stats, err
	}
	committed = true

	count, err := db.QueryInt64s("SELECT COUNT(*) FROM notes")
	if err == nil && len(count) > 0 {
		stats.SourceCount = int(count[0])
	}
	stats.Duration = time.Since(start).Round(time.Second)
	return stats, nil
}

func (nb *Notebook) markdownOptions() MarkdownOptions {
	return MarkdownOptions{
		Hashtags:      nb.Config.Format.Hashtags,
		ColonTags:     nb.Config.Format.ColonTags,
		MultiwordTags: nb.Config.Format.MultiwordTags,
	}
}

type noteFile struct {
	rel      string
	abs      string
	modified time.Time
}

// noteFiles walks the notebook and returns the note files sorted by path.
func (nb *Notebook) noteFiles() ([]noteFile, error) {
	var files []noteFile
	ext := nb.Config.Note.Extension
	excludes := nb.Config.Note.Exclude
	err := filepath.WalkDir(nb.Path, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil
		}
		if p == nb.Path {
			return nil
		}
		rel, err := filepath.Rel(nb.Path, p)
		if err != nil {
			return nil
		}
		rel = filepath.ToSlash(rel)
		name := d.Name()
		if d.IsDir() {
			if strings.HasPrefix(name, ".") {
				return filepath.SkipDir
			}
			if matchesExclude(rel, excludes, true) {
				return filepath.SkipDir
			}
			return nil
		}
		if strings.HasPrefix(name, ".") {
			return nil
		}
		if d.Type()&fs.ModeSymlink != 0 {
			// follow symlinks to files
			fi, err := os.Stat(p)
			if err != nil || fi.IsDir() {
				return nil
			}
		}
		if ext != "" && !strings.EqualFold(strings.TrimPrefix(filepath.Ext(name), "."), ext) {
			if filepath.Ext(name) != "."+ext {
				return nil
			}
		}
		if matchesExclude(rel, excludes, false) {
			return nil
		}
		fi, err := os.Stat(p)
		if err != nil {
			return nil
		}
		files = append(files, noteFile{rel: rel, abs: p, modified: fi.ModTime()})
		return nil
	})
	if err != nil {
		return nil, err
	}
	return files, nil
}

func matchesExclude(rel string, patterns []string, isDir bool) bool {
	for _, pat := range patterns {
		pat = filepath.ToSlash(filepath.Clean(pat))
		if pat == "." {
			continue
		}
		if globMatch(pat, rel) {
			return true
		}
		if !isDir {
			// match any parent directory
			dir := rel
			for {
				dir = filepath.ToSlash(filepath.Dir(dir))
				if dir == "." || dir == "/" || dir == "" {
					break
				}
				if globMatch(pat, dir) {
					return true
				}
			}
		}
	}
	return false
}

// globMatch matches a path against a glob pattern supporting *, ** and ?.
func globMatch(pattern, name string) bool {
	return globMatchParts(strings.Split(pattern, "/"), strings.Split(name, "/"))
}

func globMatchParts(pp, np []string) bool {
	if len(pp) == 0 {
		return len(np) == 0
	}
	if pp[0] == "**" {
		for i := 0; i <= len(np); i++ {
			if globMatchParts(pp[1:], np[i:]) {
				return true
			}
		}
		return false
	}
	if len(np) == 0 {
		return false
	}
	ok, err := filepath.Match(pp[0], np[0])
	if err != nil || !ok {
		return false
	}
	return globMatchParts(pp[1:], np[1:])
}

func sortablePath(p string) string {
	return strings.ReplaceAll(p, "/", "\x01")
}

func checksum(content []byte) string {
	sum := sha256.Sum256(content)
	return hex.EncodeToString(sum[:])
}

