}

func metadataDate(meta map[string]interface{}) (time.Time, bool) {
	v, ok := meta["date"]
	if !ok || v == nil {
		return time.Time{}, false
	}
	var s string
	switch x := v.(type) {
	case string:
		s = x
	case time.Time:
		return x, true
	default:
		return time.Time{}, false
	}
	s = strings.TrimSpace(s)
	for _, l := range metadataDateLayouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

func (nb *Notebook) addNote(f noteFile, parsed *ParsedNote, content []byte) error {
	db := nb.db
	created := time.Now()
	if d, ok := metadataDate(parsed.Metadata); ok {
		created = d
	}
	err := db.Exec(`INSERT INTO notes (path, sortable_path, title, lead, body, raw_content, word_count, checksum, created, modified, metadata, filename)
		VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
		f.rel, sortablePath(f.rel), parsed.Title, parsed.Lead, parsed.Body, parsed.RawContent, parsed.WordCount,
		checksum(content), created, f.modified, metadataJSON(parsed.Metadata), filepath.Base(f.rel))
	if err != nil {
		return err
	}
	id := db.LastInsertID()
	if err := nb.insertLinks(id, f.rel, parsed.Links); err != nil {
		return err
	}
	if err := nb.setTags(id, parsed.Tags); err != nil {
		return err
	}
	return nb.repointLinks(id, f.rel)
}

func (nb *Notebook) updateNote(ex indexedNote, f noteFile, parsed *ParsedNote, content []byte) error {
	db := nb.db
	created := ex.created
	if d, ok := metadataDate(parsed.Metadata); ok {
		created = d
	}
	err := db.Exec(`UPDATE notes SET title = ?, lead = ?, body = ?, raw_content = ?, word_count = ?, checksum = ?, created = ?, modified = ?, metadata = ?, filename = ?, sortable_path = ? WHERE id = ?`,
		parsed.Title, parsed.Lead, parsed.Body, parsed.RawContent, parsed.WordCount, checksum(content), created, f.modified,
		metadataJSON(parsed.Metadata), filepath.Base(f.rel), sortablePath(f.rel), ex.id)
	if err != nil {
		return err
	}
	if err := db.Exec("DELETE FROM links WHERE source_id = ?", ex.id); err != nil {
		return err
	}
	if err := nb.insertLinks(ex.id, f.rel, parsed.Links); err != nil {
		return err
	}
	if err := db.Exec("DELETE FROM notes_collections WHERE note_id = ?", ex.id); err != nil {
		return err
	}
