		parsed.Title, parsed.Lead, parsed.Body, parsed.RawContent, parsed.WordCount, checksum(content), created, f.modified,
		metadataJSON(parsed.Metadata), filepath.Base(f.rel), sortablePath(f.rel), ex.id)
	if err != nil {
		return err
	}
	if err := db.Exec("DELETE FROM links WHERE source_id = ?", ex.id); err != nil {
		return err
	}
	if err := nb.insertLinks(ex.id, f.rel, parsed.Links); err != nil {
		return err
	}
	if err := db.Exec("DELETE FROM notes_collections WHERE note_id = ?", ex.id); err != nil {
		return err
	}
	return nb.setTags(ex.id, parsed.Tags)
}

func encodeRels(rels []string) string {
	if len(rels) == 0 {
		return ""
	}
	return "\x01" + strings.Join(rels, "\x01") + "\x01"
}

func decodeRels(s string) []string {
	s = strings.Trim(s, "\x01")
	if s == "" {
		return []string{}
	}
	return strings.Split(s, "\x01")
}

func (nb *Notebook) insertLinks(sourceID int64, sourceRel string, links []Link) error {
	db := nb.db
	noteDir := filepath.ToSlash(filepath.Dir(sourceRel))
	if noteDir == "." {
		noteDir = ""
	}
	for _, l := range links {
		href := l.Href
		external := l.IsExternal
		switch l.Type {
		case "markdown":
			resolved, ok, outside := resolveMarkdownHref(l.Href, noteDir, nb.Path)
			if !ok {
				if outside != "" {
					printWarning(fmt.Sprintf("%s: path is outside the notebook at %s", outside, nb.Path))
				}
				continue
			}
			href = resolved
			external = isExternalHref(l.Href)
		case "wiki-link":
			if href == "" {
				continue
			}
			external = isExternalHref(href)
		case "implicit":
			external = true
		}
		var targetID interface{}
		if !external {
			if id, ok := nb.resolveLinkTarget(href, l.Type); ok {
				targetID = id
			}
		}
		err := db.Exec(`INSERT INTO links (source_id, target_id, title, href, external, rels, snippet, snippet_start, snippet_end, type)
			VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
			sourceID, targetID, l.Title, href, external, encodeRels(l.Rels), l.Snippet, l.SnippetStart, l.SnippetEnd, l.Type)
		if err != nil {
			return err
		}
	}
	return nil
}

func stripFragment(href string) string {
	if idx := strings.Index(href, "#"); idx >= 0 {
		return href[:idx]
	}
	return href
}

// resolveLinkTarget finds the note matching the given href.
func (nb *Notebook) resolveLinkTarget(href string, linkType string) (int64, bool) {
	db := nb.db
	h := stripFragment(href)
	// prefix match
	ids, err := db.QueryInt64s("SELECT id FROM notes WHERE path LIKE ? ORDER BY LENGTH(path) ASC, path ASC LIMIT 1", h+"%")
	if err == nil && len(ids) > 0 {
		return ids[0], true
	}
	if linkType == "wiki-link" {
		ids, err := db.QueryInt64s("SELECT id FROM notes WHERE path LIKE ? ORDER BY LENGTH(path) ASC, id ASC LIMIT 1", "%"+h+"%")
		if err == nil && len(ids) > 0 {
			return ids[0], true
		}
	}
	return 0, false
}

// repointLinks updates existing links which could target the newly added note.
func (nb *Notebook) repointLinks(noteID int64, notePath string) error {
	db := nb.db
	rows, err := db.Query(`SELECT l.id, l.href, l.type, t.path FROM links l LEFT JOIN notes t ON t.id = l.target_id WHERE l.external = 0 AND (l.target_id IS NULL OR LENGTH(t.path) >= ?)`, len(notePath))
	if err != nil {
		return err
	}
	var toUpdate []int64
	for rows.Next() {
		var id int64
		var href, typ string
		var target NullString
		if err := rows.Scan(&id, &href, &typ, &target); err != nil {
			rows.Close()
			return err
		}
		h := stripFragment(href)
		if h == "" {
			continue
		}
		var match bool
		if typ == "wiki-link" {
			match = strings.Contains(notePath, h)
		} else {
			match = strings.HasPrefix(notePath, h)
		}
		if match {
			toUpdate = append(toUpdate, id)
		}
	}
	rows.Close()
	for _, id := range toUpdate {
		if err := db.Exec("UPDATE links SET target_id = ? WHERE id = ?", noteID, id); err != nil {
			return err
		}
	}
	return nil
}

func (nb *Notebook) setTags(noteID int64, tags []string) error {
	db := nb.db
	for _, tag := range tags {
		ids, err := db.QueryInt64s("SELECT id FROM collections WHERE kind = 'tag' AND name = ?", tag)
		if err != nil {
			return err
		}
		var cid int64
		if len(ids) > 0 {
			cid = ids[0]
		} else {
			if err := db.Exec("INSERT INTO collections (kind, name) VALUES ('tag', ?)", tag); err != nil {
				return err
			}
			cid = db.LastInsertID()
		}
		if err := db.Exec("INSERT INTO notes_collections (note_id, collection_id) VALUES (?, ?)", noteID, cid); err != nil {
			return err
		}
	}
	return nil
}
