package main

import (
	"errors"
	"fmt"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// Note is an indexed note as returned by queries.
type Note struct {
	ID         int64
	Path       string // notebook-relative
	Title      string
	Lead       string
	Body       string
	RawContent string
	WordCount  int
	Tags       []string
	Metadata   map[string]interface{}
	Created    time.Time
	Modified   time.Time
	Checksum   string
	Snippets   []string
}

type NoteSorter struct {
	Field     string // created, modified, path, title, random, word-count
	Ascending bool
}

type NoteFindOpts struct {
	Match         []string
	MatchStrategy string
	IncludePaths  []string
	ExcludePaths  []string
	Tags          []string
	Mention       []string
	MentionedBy   []string
	LinkTo        []string
	NoLinkTo      []string
	LinkedBy      []string
	NoLinkedBy    []string
	Orphan        bool
	Tagless       bool
	MissingBacklink bool
	Related       []string
	MaxDistance   int
	Recursive     bool
	CreatedStart  *time.Time
	CreatedEnd    *time.Time
	ModifiedStart *time.Time
	ModifiedEnd   *time.Time
	Sorters       []NoteSorter
	Limit         int
	// Rendering of FTS snippet markers.
	SnippetStart string
	SnippetEnd   string
}

type notFoundError struct {
	paths []string
}

func (e *notFoundError) Error() string {
	return "could not find notes at: " + strings.Join(e.paths, ", ")
}

// parseNoteSorters parses sort terms.
func parseNoteSorters(terms []string) ([]NoteSorter, error) {
	var sorters []NoteSorter
	for _, t := range terms {
		s, err := parseNoteSorter(t)
		if err != nil {
			return nil, err
		}
		sorters = append(sorters, s)
	}
	return sorters, nil
}

func parseNoteSorter(term string) (NoteSorter, error) {
	orderSet := false
	asc := true
	name := term
	if strings.HasSuffix(name, "+") {
		name = name[:len(name)-1]
		orderSet = true
		asc = true
	} else if strings.HasSuffix(name, "-") {
		name = name[:len(name)-1]
		orderSet = true
		asc = false
	}
	var field string
	defaultAsc := true
	switch name {
	case "created", "c":
		field = "created"
		defaultAsc = false
	case "modified", "m":
		field = "modified"
		defaultAsc = false
	case "path", "p":
		field = "path"
	case "title", "t":
		field = "title"
	case "random", "r":
		field = "random"
	case "word-count", "wc":
		field = "word-count"
	default:
		return NoteSorter{}, fmt.Errorf("%s: unknown sorting term\ntry created, modified, path, title, random or word-count", term)
	}
	if !orderSet {
		asc = defaultAsc
	}
	return NoteSorter{Field: field, Ascending: asc}, nil
}

func (s NoteSorter) sql() string {
	dir := "ASC"
	if !s.Ascending {
		dir = "DESC"
	}
	switch s.Field {
	case "created":
		return "n.created " + dir
	case "modified":
		return "n.modified " + dir
	case "path":
		return "n.sortable_path " + dir
	case "title":
		return "n.title " + dir
	case "random":
		return "RANDOM()"
	case "word-count":
		return "n.word_count " + dir
	}
	return ""
}

// pathCondition builds the SQL condition matching notes at the given
// notebook-relative path (see the path filter semantics).
func (nb *Notebook) pathCondition(rel string) (string, []interface{}, bool) {
	rel = strings.TrimSuffix(rel, "/")
	if rel == "." {
		rel = ""
	}
	if rel == ".." || strings.HasPrefix(rel, "../") {
		return "", nil, false
	}
	db := nb.db
	ext := nb.Config.Note.Extension
	if rel != "" {
		exact := rel + "." + ext
		ids, err := db.QueryInt64s("SELECT id FROM notes WHERE path = ?", exact)
		if err == nil && len(ids) > 0 {
			return "n.path = ?", []interface{}{exact}, true
		}
	}
	cond := "((n.path LIKE ? ESCAPE '\\' AND n.path NOT LIKE ? ESCAPE '\\') OR n.path LIKE ? ESCAPE '\\')"
	esc := escapeLike(rel)
	return cond, []interface{}{esc + "%", esc + "%/%", esc + "/%"}, true
}

func escapeLike(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "%", "\\%")
	s = strings.ReplaceAll(s, "_", "\\_")
	return s
}

// findIdsMatchingPaths returns the ids of notes whose path contains one of
// the given (notebook-relative) paths, used for link filters.
func (nb *Notebook) findIdsMatchingPaths(paths []string) ([]int64, error) {
	db := nb.db
	var ids []int64
	var notFound []string
	for _, p := range paths {
		p = strings.TrimSuffix(p, "/")
		if p == "." {
			p = ""
		}
		if p == ".." || strings.HasPrefix(p, "../") {
			p = ""
		}
		found, err := db.QueryInt64s("SELECT id FROM notes WHERE path LIKE ? ORDER BY id", "%"+p+"%")
		if err != nil {
			return nil, err
		}
		if len(found) == 0 {
			notFound = append(notFound, p)
			continue
		}
		ids = append(ids, found...)
	}
	if len(notFound) > 0 {
		return nil, &notFoundError{paths: notFound}
	}
	return ids, nil
}

func int64sPlaceholders(ids []int64) (string, []interface{}) {
	if len(ids) == 0 {
		return "(NULL)", nil
	}
	ph := make([]string, len(ids))
	args := make([]interface{}, len(ids))
	for i, id := range ids {
		ph[i] = "?"
		args[i] = id
	}
	return "(" + strings.Join(ph, ", ") + ")", args
}

type linkEdge struct {
	source, target int64
}

func (nb *Notebook) allLinkEdges() ([]linkEdge, error) {
	rows, err := nb.db.Query("SELECT source_id, target_id FROM links WHERE target_id IS NOT NULL ORDER BY id")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var edges []linkEdge
	for rows.Next() {
		var e linkEdge
		if err := rows.Scan(&e.source, &e.target); err != nil {
			return nil, err
		}
		edges = append(edges, e)
	}
	return edges, rows.Err()
}

// bfs computes the distance from the start set following the given adjacency.
func bfs(start []int64, adj map[int64][]int64, maxDist int) map[int64]int {
	dist := map[int64]int{}
	queue := []int64{}
	for _, s := range start {
		if _, ok := dist[s]; !ok {
			dist[s] = 0
			queue = append(queue, s)
		}
	}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		d := dist[cur]
		if maxDist > 0 && d >= maxDist {
			continue
		}
		for _, next := range adj[cur] {
			if _, ok := dist[next]; !ok {
				dist[next] = d + 1
				queue = append(queue, next)
			}
		}
	}
	return dist
}

func sortedIDs(m map[int64]int) []int64 {
	ids := make([]int64, 0, len(m))
	for id := range m {
		ids = append(ids, id)
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	return ids
}

// FindNotes queries the notes matching the given options.
func (nb *Notebook) FindNotes(opts NoteFindOpts) ([]Note, error) {
	db, err := nb.DB()
	if err != nil {
		return nil, err
	}

	var where []string
	var args []interface{}
	var ftsTerms []string
	joinFTS := false
	hasLinkJoinFilter := false
	var distanceOrder map[int64]int
	var mentionedByCounts map[int64]int

	// Match
	strategy := opts.MatchStrategy
	if strategy == "" {
		strategy = "fts"
	}
	for _, m := range opts.Match {
		switch strategy {
		case "fts":
			ftsTerms = append(ftsTerms, "("+ftsQuery(m)+")")
			joinFTS = true
		case "re":
			where = append(where, "n.raw_content REGEXP ?")
			args = append(args, m)
		case "exact":
			where = append(where, "n.raw_content LIKE ? ESCAPE '\\'")
			args = append(args, "%"+escapeLike(m)+"%")
		}
	}

	// Paths
	if len(opts.IncludePaths) > 0 {
		var conds []string
		for _, p := range opts.IncludePaths {
			cond, a, ok := nb.pathCondition(p)
			if !ok {
				continue
			}
			conds = append(conds, cond)
			args = append(args, a...)
		}
		if len(conds) > 0 {
			where = append(where, "("+strings.Join(conds, " OR ")+")")
		}
	}
	if len(opts.ExcludePaths) > 0 {
		var conds []string
		for _, p := range opts.ExcludePaths {
			cond, a, ok := nb.pathCondition(p)
			if !ok {
				continue
			}
			conds = append(conds, cond)
			args = append(args, a...)
		}
		if len(conds) > 0 {
			where = append(where, "NOT ("+strings.Join(conds, " OR ")+")")
		}
	}

	// Tags
	for _, term := range opts.Tags {
		cond, a, err := tagCondition(term)
		if err != nil {
			return nil, err
		}
		if cond == "" {
			continue
		}
		where = append(where, cond)
		args = append(args, a...)
	}

	// Mention
	if len(opts.Mention) > 0 {
		ids, err := nb.findIdsMatchingPaths(opts.Mention)
		if err != nil {
			return nil, err
		}
		phrases, err := nb.mentionPhrases(ids)
		if err != nil {
			return nil, err
		}
		if len(phrases) == 0 {
			where = append(where, "0")
		} else {
			ftsTerms = append(ftsTerms, "("+strings.Join(phrases, " OR ")+")")
			joinFTS = true
			ph, a := int64sPlaceholders(ids)
			where = append(where, "n.id NOT IN "+ph)
			args = append(args, a...)
		}
	}

	// Mentioned by
	if len(opts.MentionedBy) > 0 {
		ids, err := nb.findIdsMatchingPaths(opts.MentionedBy)
		if err != nil {
			return nil, err
		}
		mentioned, err := nb.notesMentionedBy(ids)
		if err != nil {
			return nil, err
		}
		mentionedByCounts = map[int64]int{}
		for _, id := range mentioned {
			mentionedByCounts[id]++
		}
		ph, a := int64sPlaceholders(uniqueInts(mentioned))
		where = append(where, "n.id IN "+ph)
		args = append(args, a...)
	}

	// Links
	var edges []linkEdge
	edgesLoaded := false
	loadEdges := func() error {
		if edgesLoaded {
			return nil
		}
		e, err := nb.allLinkEdges()
		if err != nil {
			return err
		}
		edges = e
		edgesLoaded = true
		return nil
	}
	linkFilter := func(paths []string, forward bool, negate bool) error {
		ids, err := nb.findIdsMatchingPaths(paths)
		if err != nil {
			return err
		}
		if !negate {
			hasLinkJoinFilter = true
		}
		if err := loadEdges(); err != nil {
			return err
		}
		adj := map[int64][]int64{}
		for _, e := range edges {
			if forward {
				// notes linking to targets: traverse backwards
				adj[e.target] = append(adj[e.target], e.source)
			} else {
				adj[e.source] = append(adj[e.source], e.target)
			}
		}
		maxDist := 1
		if opts.Recursive {
			maxDist = opts.MaxDistance
		}
		dist := bfs(ids, adj, maxDist)
		var result []int64
		for id, d := range dist {
			if d == 0 {
				// the start notes themselves are only included if reachable
				continue
			}
			result = append(result, id)
		}
		// Start notes reachable through a cycle: compute separately.
		if !negate {
			// check whether a start note is reachable from another path
			startSet := map[int64]bool{}
			for _, id := range ids {
				startSet[id] = true
			}
			for _, e := range edges {
				var from, to int64
				if forward {
					from, to = e.target, e.source
				} else {
					from, to = e.source, e.target
				}
				if startSet[to] {
					if _, ok := dist[from]; ok && (maxDist <= 0 || dist[from] < maxDist) {
						if _, present := dist[to]; present && dist[to] == 0 {
							result = append(result, to)
							if distanceOrder == nil {
								distanceOrder = map[int64]int{}
							}
							distanceOrder[to] = dist[from] + 1
						}
					}
				}
			}
		}
		sort.Slice(result, func(i, j int) bool { return result[i] < result[j] })
		if !negate && opts.Recursive {
			if distanceOrder == nil {
				distanceOrder = map[int64]int{}
			}
			for id, d := range dist {
				if d > 0 {
					if cur, ok := distanceOrder[id]; !ok || d < cur {
						distanceOrder[id] = d
					}
				}
			}
		}
		ph, a := int64sPlaceholders(uniqueInts(result))
		if negate {
			where = append(where, "n.id NOT IN "+ph)
		} else {
			where = append(where, "n.id IN "+ph)
		}
		args = append(args, a...)
		return nil
	}
	if len(opts.LinkTo) > 0 {
		if err := linkFilter(opts.LinkTo, true, false); err != nil {
			return nil, err
		}
	}
	if len(opts.NoLinkTo) > 0 {
		if err := linkFilter(opts.NoLinkTo, true, true); err != nil {
			return nil, err
		}
	}
	if len(opts.LinkedBy) > 0 {
		if err := linkFilter(opts.LinkedBy, false, false); err != nil {
			return nil, err
		}
	}
	if len(opts.NoLinkedBy) > 0 {
		if err := linkFilter(opts.NoLinkedBy, false, true); err != nil {
			return nil, err
		}
	}

	// Related
	if len(opts.Related) > 0 {
		ids, err := nb.findIdsMatchingPaths(opts.Related)
		if err != nil {
			return nil, err
		}
		hasLinkJoinFilter = true
		if err := loadEdges(); err != nil {
			return nil, err
		}
		adj := map[int64][]int64{}
		for _, e := range edges {
			adj[e.source] = append(adj[e.source], e.target)
			adj[e.target] = append(adj[e.target], e.source)
		}
		dist := bfs(ids, adj, 2)
		var result []int64
		for id, d := range dist {
			if d == 2 {
				result = append(result, id)
			}
		}
		sort.Slice(result, func(i, j int) bool { return result[i] < result[j] })
		ph, a := int64sPlaceholders(result)
		where = append(where, "n.id IN "+ph)
		args = append(args, a...)
	}

	if opts.Orphan {
		where = append(where, "n.id NOT IN (SELECT target_id FROM links WHERE target_id IS NOT NULL)")
	}
	if opts.Tagless {
		where = append(where, "n.tags IS NULL")
	}
	if opts.MissingBacklink {
		where = append(where, "n.id IN (SELECT l.target_id FROM links l WHERE l.target_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM links b WHERE b.source_id = l.target_id AND b.target_id = l.source_id))")
	}

	if opts.CreatedStart != nil {
		where = append(where, "n.created >= ?")
		args = append(args, *opts.CreatedStart)
	}
	if opts.CreatedEnd != nil {
		where = append(where, "n.created < ?")
		args = append(args, *opts.CreatedEnd)
	}
	if opts.ModifiedStart != nil {
		where = append(where, "n.modified >= ?")
		args = append(args, *opts.ModifiedStart)
	}
	if opts.ModifiedEnd != nil {
		where = append(where, "n.modified < ?")
		args = append(args, *opts.ModifiedEnd)
	}

	// Replicate zk behavior: FTS matching combined with link joins yields nothing.
	if joinFTS && hasLinkJoinFilter && len(ftsTerms) > 0 && strategy == "fts" && len(opts.Match) > 0 {
		return []Note{}, nil
	}

	snippetCol := "n.lead"
	var ftsArgs []interface{}
	if joinFTS {
		snippetCol = "snippet(notes_fts, 2, ?, ?, '…', 20)"
		ftsArgs = append(ftsArgs, opts.SnippetStart, opts.SnippetEnd)
	}

	query := "SELECT n.id, n.path, n.title, n.lead, n.body, n.raw_content, n.word_count, n.created, n.modified, n.metadata, n.checksum, n.tags, " + snippetCol + "\n"
	query += " FROM notes_with_metadata n\n"
	allArgs := append([]interface{}{}, ftsArgs...)
	if joinFTS {
		query += " JOIN notes_fts ON n.id = notes_fts.rowid\n"
		where = append([]string{"notes_fts MATCH ?"}, where...)
		allArgs = append(allArgs, strings.Join(ftsTerms, " AND "))
	}
	allArgs = append(allArgs, args...)
	if len(where) > 0 {
		query += " WHERE " + strings.Join(where, "\n   AND ") + "\n"
	}

	// Ordering
	var orderTerms []string
	for i := len(opts.Sorters) - 1; i >= 0; i-- {
		orderTerms = append(orderTerms, opts.Sorters[i].sql())
	}
	if len(opts.Sorters) == 0 {
		if joinFTS {
			orderTerms = append(orderTerms, "rank")
		} else {
			if distanceOrder != nil && opts.Recursive {
				// ORDER BY distance using a CASE expression
				var sb strings.Builder
				sb.WriteString("CASE n.id")
				ids := sortedIDs(distanceOrder)
				for _, id := range ids {
					sb.WriteString(fmt.Sprintf(" WHEN %d THEN %d", id, distanceOrder[id]))
				}
				sb.WriteString(" ELSE 999999 END ASC")
				orderTerms = append(orderTerms, sb.String())
			}
			orderTerms = append(orderTerms, "n.title ASC")
		}
	}
	query += " ORDER BY " + strings.Join(orderTerms, ", ") + "\n"
	if opts.Limit > 0 {
		query += fmt.Sprintf(" LIMIT %d\n", opts.Limit)
	}

	rows, err := db.Query(query, allArgs...)
	if err != nil {
		if joinFTS {
			// FTS syntax errors yield no results.
			return []Note{}, nil
		}
		return nil, err
	}
	defer rows.Close()
	notes := []Note{}
	for rows.Next() {
		var n Note
		var created, modified, metadata, snippet string
		var tags NullString
		if err := rows.Scan(&n.ID, &n.Path, &n.Title, &n.Lead, &n.Body, &n.RawContent, &n.WordCount, &created, &modified, &metadata, &n.Checksum, &tags, &snippet); err != nil {
			return nil, err
		}
		n.Created, _ = parseDBTime(created)
		n.Modified, _ = parseDBTime(modified)
		n.Metadata = parseMetadataJSON(metadata)
		if tags.Valid && tags.String != "" {
			n.Tags = strings.Split(tags.String, "\x01")
		} else {
			n.Tags = []string{}
		}
		if snippet != "" {
			n.Snippets = []string{snippet}
		} else {
			n.Snippets = []string{}
		}
		notes = append(notes, n)
	}
	if err := rows.Err(); err != nil {
		if joinFTS {
			return []Note{}, nil
		}
		return nil, err
	}
	if mentionedByCounts != nil {
		var expanded []Note
		for _, n := range notes {
			c := mentionedByCounts[n.ID]
			if c < 1 {
				c = 1
			}
			for i := 0; i < c; i++ {
				expanded = append(expanded, n)
			}
		}
		notes = expanded
		if opts.Limit > 0 && len(notes) > opts.Limit {
			notes = notes[:opts.Limit]
		}
	}
	return notes, nil
}

func uniqueInts(ids []int64) []int64 {
	seen := map[int64]bool{}
	var out []int64
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			out = append(out, id)
		}
	}
	return out
}

func parseMetadataJSON(s string) map[string]interface{} {
	m := map[string]interface{}{}
	if s == "" {
		return m
	}
	_ = jsonUnmarshal([]byte(s), &m)
	return m
}

// tagCondition builds the condition for a tag filter term.
func tagCondition(term string) (string, []interface{}, error) {
	negate := false
	t := term
	if strings.HasPrefix(t, "NOT") {
		negate = true
		t = strings.TrimSpace(t[3:])
	}
	var alts []string
	for _, part := range strings.Split(t, "|") {
		for _, p := range strings.Split(part, " OR ") {
			p = strings.TrimSpace(p)
			if p == "" {
				continue
			}
			alts = append(alts, p)
		}
	}
	if len(alts) == 0 {
		alts = []string{""}
	}
	if negate && len(alts) > 1 {
		return "", nil, fmt.Errorf("cannot negate a tag in a OR group: %s", term)
	}
	var globs []string
	var args []interface{}
	for _, a := range alts {
		globs = append(globs, "c.name GLOB ?")
		args = append(args, a)
	}
	sub := "SELECT nc.note_id FROM notes_collections nc JOIN collections c ON nc.collection_id = c.id WHERE c.kind = 'tag' AND (" + strings.Join(globs, " OR ") + ")"
	if negate {
		return "n.id NOT IN (" + sub + ")", args, nil
	}
	return "n.id IN (" + sub + ")", args, nil
}

// mentionPhrases returns the FTS phrases for the titles and aliases of the given notes.
func (nb *Notebook) mentionPhrases(ids []int64) ([]string, error) {
	var phrases []string
	for _, id := range ids {
		rows, err := nb.db.Query("SELECT title, metadata FROM notes WHERE id = ?", id)
		if err != nil {
			return nil, err
		}
		for rows.Next() {
			var title, meta string
			if err := rows.Scan(&title, &meta); err != nil {
				rows.Close()
				return nil, err
			}
			for _, p := range noteMentionTerms(title, parseMetadataJSON(meta)) {
				phrases = append(phrases, ftsPhrase(p))
			}
		}
		rows.Close()
	}
	return phrases, nil
}

func noteMentionTerms(title string, meta map[string]interface{}) []string {
	var terms []string
	if strings.TrimSpace(title) != "" {
		terms = append(terms, title)
	}
	if v, ok := meta["aliases"]; ok {
		switch x := v.(type) {
		case []interface{}:
			for _, a := range x {
				s := strings.TrimSpace(fmt.Sprint(a))
				if s != "" {
					terms = append(terms, s)
				}
			}
		case string:
			for _, a := range strings.Split(x, ",") {
				a = strings.TrimSpace(a)
				if a != "" {
					terms = append(terms, a)
				}
			}
		}
	}
	return terms
}

func ftsPhrase(s string) string {
	return `"` + strings.ReplaceAll(s, `"`, `""`) + `"`
}

// notesMentionedBy returns the ids of the notes whose title or aliases are
// mentioned in the given notes (with duplicates when mentioned several times).
func (nb *Notebook) notesMentionedBy(targetIDs []int64) ([]int64, error) {
	db := nb.db
	rows, err := db.Query("SELECT id, title, metadata FROM notes ORDER BY id")
	if err != nil {
		return nil, err
	}
	type cand struct {
		id    int64
		terms []string
	}
	var cands []cand
	for rows.Next() {
		var id int64
		var title, meta string
		if err := rows.Scan(&id, &title, &meta); err != nil {
			rows.Close()
			return nil, err
		}
		terms := noteMentionTerms(title, parseMetadataJSON(meta))
		if len(terms) > 0 {
			cands = append(cands, cand{id: id, terms: terms})
		}
	}
	rows.Close()
	var result []int64
	for _, t := range targetIDs {
		for _, c := range cands {
			if c.id == t {
				continue
			}
			var phrases []string
			for _, term := range c.terms {
				phrases = append(phrases, ftsPhrase(term))
			}
			ids, err := db.QueryInt64s("SELECT rowid FROM notes_fts WHERE rowid = ? AND notes_fts MATCH ?", t, strings.Join(phrases, " OR "))
			if err != nil {
				continue
			}
			if len(ids) > 0 {
				result = append(result, c.id)
			}
		}
	}
	return result, nil
}

// ---------------------------------------------------------------------------
// Tags

type Tag struct {
	ID        int64
	Kind      string
	Name      string
	NoteCount int
}

type TagSorter struct {
	Field     string // name, note-count
	Ascending bool
}

func parseTagSorters(terms []string) ([]TagSorter, error) {
	var sorters []TagSorter
	for _, term := range terms {
		orderSet := false
		asc := true
		name := term
		if strings.HasSuffix(name, "+") {
			name = name[:len(name)-1]
			orderSet = true
		} else if strings.HasSuffix(name, "-") {
			name = name[:len(name)-1]
			orderSet = true
			asc = false
		}
		var field string
		defaultAsc := true
		switch name {
		case "name", "n":
			field = "name"
		case "note-count", "nc":
			field = "note-count"
			defaultAsc = false
		default:
			return nil, fmt.Errorf("%s: unknown sorting term\ntry name or note-count", term)
		}
		if !orderSet {
			asc = defaultAsc
		}
		sorters = append(sorters, TagSorter{Field: field, Ascending: asc})
	}
	return sorters, nil
}

func (nb *Notebook) FindTags(sorters []TagSorter) ([]Tag, error) {
	db, err := nb.DB()
	if err != nil {
		return nil, err
	}
	var orderTerms []string
	for i := len(sorters) - 1; i >= 0; i-- {
		s := sorters[i]
		dir := "ASC"
		if !s.Ascending {
			dir = "DESC"
		}
		switch s.Field {
		case "name":
			orderTerms = append(orderTerms, "c.name "+dir)
		case "note-count":
			orderTerms = append(orderTerms, "COUNT(nc.id) "+dir)
		}
	}
	orderTerms = append(orderTerms, "c.name ASC")
	query := `SELECT c.id, c.kind, c.name, COUNT(nc.id) as count
		FROM collections c
		INNER JOIN notes_collections nc ON nc.collection_id = c.id
		WHERE c.kind = 'tag'
		GROUP BY c.id
		ORDER BY ` + strings.Join(orderTerms, ", ")
	rows, err := db.Query(query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	tags := []Tag{}
	for rows.Next() {
		var t Tag
		if err := rows.Scan(&t.ID, &t.Kind, &t.Name, &t.NoteCount); err != nil {
			return nil, err
		}
		tags = append(tags, t)
	}
	return tags, rows.Err()
}

// ---------------------------------------------------------------------------
// Links (for the graph)

type ResolvedLink struct {
	Link
	SourceID   int64
	SourcePath string
	TargetID   int64
	TargetPath string
}

func (nb *Notebook) FindLinksBetween(ids []int64) ([]ResolvedLink, error) {
	db, err := nb.DB()
	if err != nil {
		return nil, err
	}
	if len(ids) == 0 {
		return []ResolvedLink{}, nil
	}
	ph, args := int64sPlaceholders(ids)
	query := `SELECT l.id, l.source_id, l.source_path, l.target_id, l.target_path, l.title, l.href, l.type, l.external, l.rels, l.snippet, l.snippet_start, l.snippet_end
		FROM resolved_links l
		WHERE l.source_id IN ` + ph + ` AND l.target_id IN ` + ph + `
		ORDER BY l.source_id, l.target_id, l.id`
	allArgs := append(append([]interface{}{}, args...), args...)
	rows, err := db.Query(query, allArgs...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	links := []ResolvedLink{}
	for rows.Next() {
		var l ResolvedLink
		var id int64
		var rels string
		var targetPath NullString
		if err := rows.Scan(&id, &l.SourceID, &l.SourcePath, &l.TargetID, &targetPath, &l.Title, &l.Href, &l.Type, &l.IsExternal, &rels, &l.Snippet, &l.SnippetStart, &l.SnippetEnd); err != nil {
			return nil, err
		}
		l.TargetPath = targetPath.String
		l.Rels = decodeRels(rels)
		links = append(links, l)
	}
	return links, rows.Err()
}

