// ftsQuery converts a user query into an FTS5 query.
func ftsQuery(s string) string {
	var out []string
	var term strings.Builder

	flush := func(raw bool) {
		if term.Len() == 0 {
			return
		}
		t := term.String()
		term.Reset()
		if t == "AND" || t == "OR" || t == "NOT" || raw {
			out = append(out, t)
			return
		}
		out = append(out, `"`+strings.ReplaceAll(t, `"`, `""`)+`"`)
	}

	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			flush(false)
			i++
		case c == '"':
			end := strings.IndexByte(s[i+1:], '"')
			var content string
			if end < 0 {
				content = s[i+1:]
				i = len(s)
			} else {
				content = s[i+1 : i+1+end]
				i = i + 1 + end + 1
			}
			term.WriteString(content)
			if term.Len() == 0 {
				// empty phrase
				out = append(out, `""`)
			} else {
				flush(false)
			}
		case c == '(' || c == ')' || c == '*':
			flush(false)
			out = append(out, string(c))
			i++
		case c == ':':
			flush(true)
			out = append(out, ":")
			i++
		case c == '|':
			flush(false)
			out = append(out, "OR")
			i++
		case c == '-' && term.Len() == 0:
			out = append(out, "NOT")
			i++
		case c == '^' && term.Len() == 0:
			out = append(out, "^")
			i++
		default:
			term.WriteByte(c)
			i++
		}
	}
	flush(false)
	return strings.Join(out, " ")
}
