				i = len(s)
			} else {
				content = s[i+1 : i+1+end]
				i = i + 1 + end + 1
			}
			term.WriteString(content)
			if term.Len() == 0 {
				// empty phrase
				out = append(out, `""`)
			} else {
				flush(false)
			}
		case c == '(' || c == ')' || c == '*':
			flush(false)
			out = append(out, string(c))
			i++
		case c == ':':
			flush(true)
			out = append(out, ":")
			i++
		case c == '|':
			flush(false)
			out = append(out, "OR")
			i++
		case c == '-' && term.Len() == 0:
			out = append(out, "NOT")
			i++
		case c == '^' && term.Len() == 0:
			out = append(out, "^")
			i++
		default:
			term.WriteByte(c)
			i++
		}
	}
	flush(false)
	return strings.Join(out, " ")
}
