// bfs computes the distance from the start set (distance 0) following the adjacency.
func bfs(start []int64, adj map[int64][]int64, maxDist int) map[int64]int {
	dist := map[int64]int{}
	queue := []int64{}
	for _, s := range start {
		if _, ok := dist[s]; !ok {
			dist[s] = 0
			queue = append(queue, s)
		}
	}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		d := dist[cur]
		if maxDist > 0 && d >= maxDist {
			continue
		}
		for _, next := range adj[cur] {
			if _, ok := dist[next]; !ok {
				dist[next] = d + 1
				queue = append(queue, next)
			}
		}
	}
	return dist
}

