package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
	"time"
	"unicode"
)

// ---------------------------------------------------------------------------
// Date parsing

var dateLayouts = []string{
	time.RFC3339Nano,
	time.RFC3339,
	"2006-01-02",
}

// parseDate parses a date given by the user.
func parseDate(s string, now time.Time) (time.Time, error) {
	s = strings.TrimSpace(s)
	for _, l := range dateLayouts {
		if t, err := time.Parse(l, s); err == nil {
			return t, nil
		}
	}
	return parseNaturalDate(s, now)
}

type naturalDateError struct {
	start, end int
	text       string
}

func (e *naturalDateError) Error() string {
	return fmt.Sprintf("\nparse error near PegText (line 1 symbol %d - line 1 symbol %d):\n%q\n", e.start+1, e.end+1, e.text)
}

var numberWords = map[string]int{
	"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
	"eleven": 11, "twelve": 12,
}

var weekdays = map[string]time.Weekday{
	"sunday": time.Sunday, "monday": time.Monday, "tuesday": time.Tuesday, "wednesday": time.Wednesday,
	"thursday": time.Thursday, "friday": time.Friday, "saturday": time.Saturday,
}

var monthNames = map[string]time.Month{
	"january": time.January, "february": time.February, "march": time.March, "april": time.April,
	"may": time.May, "june": time.June, "july": time.July, "august": time.August,
	"september": time.September, "october": time.October, "november": time.November, "december": time.December,
}

type ndToken struct {
	text  string
	start int
	end   int
	num   int
	isNum bool
}

func truncateDay(t time.Time) time.Time {
	return time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
}

func unitName(s string) string {
	s = strings.TrimSuffix(s, "s")
	switch s {
	case "second", "minute", "hour", "day", "week", "month", "year":
		return s
	}
	return ""
}

func addUnit(t time.Time, unit string, n int, truncate bool) time.Time {
	switch unit {
	case "second":
		return t.Add(time.Duration(n) * time.Second)
	case "minute":
		return t.Add(time.Duration(n) * time.Minute)
	case "hour":
		return t.Add(time.Duration(n) * time.Hour)
	case "day":
		r := t.Add(time.Duration(n) * 24 * time.Hour)
		if truncate {
			return truncateDay(r)
		}
		return r
	case "week":
		r := t.Add(time.Duration(n) * 7 * 24 * time.Hour)
		if truncate {
			return truncateDay(r)
		}
		return r
	case "month":
		return t.AddDate(0, n, 0)
	case "year":
		return t.AddDate(n, 0, 0)
	}
	return t
}

func prevWeekday(t time.Time, wd time.Weekday) time.Time {
	d := truncateDay(t)
	diff := int(d.Weekday()) - int(wd)
	if diff <= 0 {
		diff += 7
	}
	return d.AddDate(0, 0, -diff)
}

func nextWeekday(t time.Time, wd time.Weekday) time.Time {
	d := truncateDay(t)
	diff := int(wd) - int(d.Weekday())
	if diff <= 0 {
		diff += 7
	}
	return d.AddDate(0, 0, diff)
}

// parseNaturalDate approximates the natural language date parser used by zk.
func parseNaturalDate(input string, now time.Time) (time.Time, error) {
	// tokenize
	var toks []ndToken
	i := 0
	for i < len(input) {
		c := input[i]
		if c == ' ' || c == '\t' || c == '\n' {
			i++
			continue
		}
		j := i
		for j < len(input) && input[j] != ' ' && input[j] != '\t' && input[j] != '\n' {
			j++
		}
		word := input[i:j]
		// split a leading number from trailing letters (e.g. 3pm, 3h)
		k := 0
		for k < len(word) && word[k] >= '0' && word[k] <= '9' {
			k++
		}
		if k > 0 {
			numText := word[:k]
			rest := word[k:]
			n, _ := strconv.Atoi(numText)
			if rest != "" {
				r := rest[0]
				if r == ':' {
					// time
					toks = append(toks, ndToken{text: strings.ToLower(word), start: i, end: j, num: n, isNum: false})
					i = j
					continue
				}
				if !unicode.IsLetter(rune(r)) {
					return time.Time{}, &naturalDateError{start: i, end: i + k, text: numText}
				}
				toks = append(toks, ndToken{text: numText, start: i, end: i + k, num: n, isNum: true})
				toks = append(toks, ndToken{text: strings.ToLower(rest), start: i + k, end: j})
			} else {
				toks = append(toks, ndToken{text: numText, start: i, end: j, num: n, isNum: true})
			}
			i = j
			continue
		}
		toks = append(toks, ndToken{text: strings.ToLower(word), start: i, end: j})
		i = j
	}

	t := now
	pos := 0
	peek := func(off int) *ndToken {
		if pos+off < len(toks) {
			return &toks[pos+off]
		}
		return nil
	}
	setTime := func(h, m, s int) {
		t = time.Date(t.Year(), t.Month(), t.Day(), h, m, s, 0, t.Location())
	}
	parseClock := func(text string) (int, int, int, bool, bool, bool) {
		// returns h, m, s, hasSeconds, hasMeridiem, ok
		meridiem := ""
		if strings.HasSuffix(text, "am") || strings.HasSuffix(text, "pm") {
			meridiem = text[len(text)-2:]
			text = text[:len(text)-2]
		}
		parts := strings.Split(text, ":")
		if len(parts) < 1 || len(parts) > 3 {
			return 0, 0, 0, false, false, false
		}
		var vals [3]int
		for idx, p := range parts {
			if p == "" {
				return 0, 0, 0, false, false, false
			}
			v, err := strconv.Atoi(p)
			if err != nil {
				return 0, 0, 0, false, false, false
			}
			vals[idx] = v
		}
		h, m, s := vals[0], vals[1], vals[2]
		if meridiem == "pm" && h < 12 {
			h += 12
		} else if meridiem == "am" && h == 12 {
			h = 0
		}
		return h, m, s, len(parts) == 3, meridiem != "", true
	}

	for pos < len(toks) {
		tok := toks[pos]
		w := tok.text
		switch {
		case tok.isNum:
			// number followed by unit?
			next := peek(1)
			if next != nil && !next.isNum {
				if unit := unitName(next.text); unit != "" {
					after := peek(2)
					if after != nil && after.text == "ago" {
						t = addUnit(t, unit, -tok.num, unit == "day" || unit == "week")
						pos += 3
						continue
					}
					if unit == "day" || unit == "week" || unit == "hour" || unit == "minute" {
						t = addUnit(t, unit, -tok.num, unit == "day" || unit == "week")
						pos += 2
						continue
					}
				}
				if next.text == "am" || next.text == "pm" {
					h := tok.num
					if next.text == "pm" && h < 12 {
						h += 12
					} else if next.text == "am" && h == 12 {
						h = 0
					}
					setTime(h, 0, 0)
					pos += 2
					continue
				}
			}
			if tok.num >= 1000 {
				t = time.Date(tok.num, t.Month(), t.Day(), t.Hour(), t.Minute(), t.Second(), 0, t.Location())
				pos++
				continue
			}
			if tok.num <= 24 {
				setTime(tok.num, 0, 0)
			}
			pos++
		case strings.Contains(w, ":"):
			h, m, s, hasSec, hasMer, ok := parseClock(w)
			if !ok {
				pos++
				continue
			}
			// "4:30 pm"
			next := peek(1)
			if !hasMer && next != nil && (next.text == "am" || next.text == "pm") {
				if next.text == "pm" && h < 12 {
					h += 12
				} else if next.text == "am" && h == 12 {
					h = 0
				}
				hasMer = true
				pos++
			}
			if !hasMer && !hasSec {
				t = time.Date(0, 1, 1, h, m, 0, 0, t.Location())
			} else {
				setTime(h, m, s)
			}
			pos++
		case w == "now":
			t = now
			pos++
		case w == "today":
			t = truncateDay(t)
			pos++
		case w == "yesterday":
			t = truncateDay(t).AddDate(0, 0, -1)
			pos++
		case w == "tomorrow":
			t = truncateDay(t).AddDate(0, 0, 1)
			pos++
		case w == "last" || w == "previous" || w == "past" || w == "next" || w == "this":
			dir := -1
			if w == "next" {
				dir = 1
			}
			next := peek(1)
			if next == nil {
				pos++
				continue
			}
			if next.isNum {
				after := peek(2)
				if after != nil {
					if unit := unitName(after.text); unit != "" {
						if w == "this" {
							pos += 3
							continue
						}
						t = addUnit(t, unit, dir*next.num, unit == "day" || unit == "week")
						pos += 3
						continue
					}
				}
				pos++
				continue
			}
			if n, ok := numberWords[next.text]; ok {
				after := peek(2)
				if after != nil {
					if unit := unitName(after.text); unit != "" {
						if w != "this" {
							t = addUnit(t, unit, dir*n, unit == "day" || unit == "week")
						}
						pos += 3
						continue
					}
				}
				pos++
				continue
			}
			if unit := unitName(next.text); unit != "" {
				if w != "this" {
					t = addUnit(t, unit, dir, unit == "day" || unit == "week")
				}
				pos += 2
				continue
			}
			if wd, ok := weekdays[next.text]; ok {
				if dir > 0 {
					t = nextWeekday(t, wd)
				} else {
					t = prevWeekday(t, wd)
				}
				pos += 2
				continue
			}
			if m, ok := monthNames[next.text]; ok {
				t = setMonth(t, m, dir)
				pos += 2
				continue
			}
			pos++
		case w == "in":
			next := peek(1)
			if next == nil {
				pos++
				continue
			}
			n := 0
			ok := false
			if next.isNum {
				n, ok = next.num, true
			} else if v, has := numberWords[next.text]; has {
				n, ok = v, true
			} else if next.text == "a" || next.text == "an" {
				n, ok = 1, true
			}
			if ok {
				after := peek(2)
				if after != nil {
					if unit := unitName(after.text); unit != "" {
						t = addUnit(t, unit, n, false)
						pos += 3
						continue
					}
				}
			}
			pos++
		case w == "at":
			pos++
		default:
			if n, ok := numberWords[w]; ok {
				next := peek(1)
				if next != nil {
					if unit := unitName(next.text); unit != "" {
						after := peek(2)
						if after != nil && after.text == "ago" {
							t = addUnit(t, unit, -n, unit == "day" || unit == "week")
							pos += 3
							continue
						}
						if unit == "day" || unit == "week" || unit == "hour" || unit == "minute" {
							t = addUnit(t, unit, -n, unit == "day" || unit == "week")
							pos += 2
							continue
						}
					}
				}
				pos++
				continue
			}
			if wd, ok := weekdays[w]; ok {
				t = prevWeekday(t, wd)
				pos++
				continue
			}
			if m, ok := monthNames[w]; ok {
				t = setMonth(t, m, -1)
				pos++
				continue
			}
			pos++
		}
	}
	return t, nil
}

func setMonth(t time.Time, m time.Month, dir int) time.Time {
	year := t.Year()
	if dir < 0 {
		if m >= t.Month() {
			year--
		}
	} else {
		if m <= t.Month() {
			year++
		}
	}
	return time.Date(year, m, t.Day(), t.Hour(), t.Minute(), t.Second(), 0, t.Location())
}

// ---------------------------------------------------------------------------
// Elapsed time formatting

func formatElapsed(t time.Time, now time.Time) string {
	d := now.Sub(t)
	if d < 0 {
		return "not yet"
	}
	secs := int64(d.Seconds())
	if secs < 60 {
		return "just now"
	}
	mins := secs / 60
	if mins < 60 {
		return fmt.Sprintf("%d %s ago", mins, pluralize("minute", int(mins)))
	}
	hours := secs / 3600
	if hours < 24 {
		return fmt.Sprintf("%d %s ago", hours, pluralize("hour", int(hours)))
	}
	days := secs / 86400
	if days == 1 {
		return "yesterday"
	}
	if days < 7 {
		return fmt.Sprintf("%d days ago", days)
	}
	weeks := int64(math.Ceil(float64(days) / 7))
	if weeks < 4 {
		return fmt.Sprintf("%d %s ago", weeks, pluralize("week", int(weeks)))
	}
	months := int64(math.Ceil(float64(days) / 30))
	if months < 12 {
		return fmt.Sprintf("%d %s ago", months, pluralize("month", int(months)))
	}
	years := int64(math.Ceil(float64(days) / 365))
	return fmt.Sprintf("%d %s ago", years, pluralize("year", int(years)))
}

// ---------------------------------------------------------------------------
// strftime

func strftime(format string, t time.Time) string {
	var sb strings.Builder
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' || i+1 >= len(format) {
			sb.WriteByte(c)
			continue
		}
		i++
		switch format[i] {
		case 'A':
			sb.WriteString(t.Weekday().String())
		case 'a':
			sb.WriteString(t.Weekday().String()[:3])
		case 'B':
			sb.WriteString(t.Month().String())
		case 'b', 'h':
			sb.WriteString(t.Month().String()[:3])
		case 'C':
			sb.WriteString(fmt.Sprintf("%02d", t.Year()/100))
		case 'c':
			sb.WriteString(t.Format("Mon Jan _2 15:04:05 2006"))
		case 'D':
			sb.WriteString(t.Format("01/02/06"))
		case 'd':
			sb.WriteString(fmt.Sprintf("%02d", t.Day()))
		case 'e':
			sb.WriteString(fmt.Sprintf("%2d", t.Day()))
		case 'F':
			sb.WriteString(t.Format("2006-01-02"))
		case 'H':
			sb.WriteString(fmt.Sprintf("%02d", t.Hour()))
		case 'I':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(fmt.Sprintf("%02d", h))
		case 'j':
			sb.WriteString(fmt.Sprintf("%03d", t.YearDay()))
		case 'k':
			sb.WriteString(fmt.Sprintf("%2d", t.Hour()))
		case 'l':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			sb.WriteString(fmt.Sprintf("%2d", h))
		case 'M':
			sb.WriteString(fmt.Sprintf("%02d", t.Minute()))
		case 'm':
			sb.WriteString(fmt.Sprintf("%02d", int(t.Month())))
		case 'n':
			sb.WriteByte('\n')
		case 'p':
			if t.Hour() < 12 {
				sb.WriteString("AM")
			} else {
				sb.WriteString("PM")
			}
		case 'R':
			sb.WriteString(t.Format("15:04"))
		case 'r':
			sb.WriteString(t.Format("03:04:05 PM"))
		case 'S':
			sb.WriteString(fmt.Sprintf("%02d", t.Second()))
		case 'T':
			sb.WriteString(t.Format("15:04:05"))
		case 't':
			sb.WriteByte('\t')
		case 'U':
			sb.WriteString(fmt.Sprintf("%02d", (t.YearDay()+6-int(t.Weekday()))/7))
		case 'u':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			sb.WriteString(strconv.Itoa(wd))
		case 'V':
			_, wk := t.ISOWeek()
			sb.WriteString(fmt.Sprintf("%02d", wk))
		case 'G':
			y, _ := t.ISOWeek()
			sb.WriteString(strconv.Itoa(y))
		case 'v':
			sb.WriteString(t.Format("_2-Jan-2006"))
		case 'W':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			sb.WriteString(fmt.Sprintf("%02d", (t.YearDay()+7-wd)/7))
		case 'w':
			sb.WriteString(strconv.Itoa(int(t.Weekday())))
		case 'X':
			sb.WriteString(t.Format("15:04:05"))
		case 'x':
			sb.WriteString(t.Format("01/02/06"))
		case 'Y':
			sb.WriteString(strconv.Itoa(t.Year()))
		case 'y':
			sb.WriteString(fmt.Sprintf("%02d", t.Year()%100))
		case 'Z':
			sb.WriteString(t.Format("MST"))
		case 'z':
			sb.WriteString(t.Format("-0700"))
		case 's':
			sb.WriteString(strconv.FormatInt(t.Unix(), 10))
		case 'f':
			sb.WriteString(fmt.Sprintf("%06d", t.Nanosecond()/1000))
		case '%':
			sb.WriteByte('%')
		default:
			sb.WriteByte('%')
			sb.WriteByte(format[i])
		}
	}
	return sb.String()
}

// formatDate implements the format-date helper.
func formatDate(t time.Time, format string, now time.Time) string {
	switch format {
	case "":
		return t.Format("2006-01-02")
	case "short":
		return t.Format("01/02/2006")
	case "medium":
		return t.Format("Jan 02, 2006")
	case "long":
		return t.Format("January 02, 2006")
	case "full":
		return t.Format("Monday, January 02, 2006")
	case "year":
		return t.Format("2006")
	case "time":
		return t.Format("15:04")
	case "timestamp":
		return t.Format("200601021504")
	case "timestamp-unix":
		return strconv.FormatInt(t.Unix(), 10)
	case "elapsed":
		return formatElapsed(t, now)
	}
	return strftime(format, t)
}
EOF
