// pagedWriter writes output through a pager when appropriate.
type pagedWriter struct {
	w      io.Writer
	cmd    *exec.Cmd
	pipe   io.WriteCloser
	buf    *bufio.Writer
	closed bool
}

// newPagedWriter returns a writer to stdout, possibly piped into a pager.
func newPagedWriter(usePager bool, pagerCmd *string) *pagedWriter {
	pw := &pagedWriter{}
	if usePager && stdoutIsTTY {
		pager := ""
		if pagerCmd != nil {
			pager = *pagerCmd
		} else if p, ok := os.LookupEnv("PAGER"); ok {
			pager = p
		} else {
			pager = "less -FIRX"
		}
		if strings.TrimSpace(pager) != "" {
			cmd := shellCommand(pager)
			cmd.Stdout = os.Stdout
			cmd.Stderr = os.Stderr
			pipe, err := cmd.StdinPipe()
			if err == nil {
				if err := cmd.Start(); err == nil {
					pw.cmd = cmd
					pw.pipe = pipe
					pw.buf = bufio.NewWriter(pipe)
					pw.w = pw.buf
					return pw
				}
			}
		}
	}
	pw.buf = bufio.NewWriter(os.Stdout)
	pw.w = pw.buf
	return pw
}

func (pw *pagedWriter) Write(p []byte) (int, error) {
	return pw.w.Write(p)
}

func (pw *pagedWriter) WriteString(s string) {
	io.WriteString(pw.w, s)
}

func (pw *pagedWriter) Close() {
	if pw.closed {
		return
	}
	pw.closed = true
	pw.buf.Flush()
	if pw.pipe != nil {
		pw.pipe.Close()
	}
	if pw.cmd != nil {
		pw.cmd.Wait()
	}
}

