func (f *NoteFormatter) context(n Note) noteFormatContext {
	abs := f.nb.AbsPath(n.Path)
	rel, err := filepath.Rel(f.workingDir, abs)
	if err != nil {
		rel = n.Path
	}
	rel = filepath.ToSlash(rel)
	filename := filepath.Base(n.Path)
	snippets := n.Snippets
	if snippets == nil {
		snippets = []string{}
	}
	tags := n.Tags
	if tags == nil {
		tags = []string{}
	}
	meta := n.Metadata
	if meta == nil {
		meta = map[string]interface{}{}
	}
	return noteFormatContext{
