func encodePath(p string) string {
	parts := strings.Split(p, "/")
	for i, part := range parts {
		parts[i] = url.PathEscape(part)
	}
	return strings.Join(parts, "/")
}

// formatLink renders a link to the note at the given notebook-relative path.
func (nb *Notebook) formatLink(relPath string, title string, workingDir string) string {
	cfg := nb.Config.Format
	format := cfg.LinkFormat
	if format == "" {
		format = "markdown"
	}
	abs := nb.AbsPath(relPath)
	p := relPath
	rel, err := filepath.Rel(workingDir, abs)
	if err != nil {
		rel = relPath
	}
	rel = filepath.ToSlash(rel)
	filename := filepath.Base(relPath)
	if cfg.LinkDropExtension {
		ext := filepath.Ext(p)
		p = strings.TrimSuffix(p, ext)
		rel = strings.TrimSuffix(rel, filepath.Ext(rel))
		abs = strings.TrimSuffix(abs, filepath.Ext(abs))
		filename = strings.TrimSuffix(filename, filepath.Ext(filename))
	}
	if cfg.LinkEncodePath {
		p = encodePath(p)
		rel = encodePath(rel)
		abs = encodePath(abs)
		filename = encodePath(filename)
	}
	var tplSrc string
	switch format {
	case "wiki":
		tplSrc = "[[{{path}}]]"
	case "markdown":
		tplSrc = "[{{title}}]({{path}})"
	default:
		tplSrc = format
	}
	tpl, err := hbParse(tplSrc)
	if err != nil {
		return ""
	}
	env := &TemplateEnv{NotebookDir: nb.Path}
	engine := env.newEngine()
	out, err := engine.Render(tpl, linkFormatContext{Filename: filename, Path: p, AbsPath: abs, RelPath: rel, Title: title})
	if err != nil {
		return ""
	}
	return out
}

