	Created      time.Time              `json:"created"`
	Modified     time.Time              `json:"modified"`
	Checksum     string                 `json:"checksum"`
}

func envMap() map[string]string {
	m := map[string]string{}
	for _, kv := range os.Environ() {
		if idx := strings.IndexByte(kv, '='); idx >= 0 {
			m[kv[:idx]] = kv[idx+1:]
		}
	}
	return m
}

// NoteFormatter renders notes with a template.
type NoteFormatter struct {
	nb         *Notebook
	workingDir string
	engine     *hbEngine
	tpl        *hbTemplate
	env        map[string]string
	styler     Styler
}

var predefinedNoteFormats = map[string]string{
	"path":    `{{path}}`,
	"link":    `{{link}}`,
	"oneline": `{{style "title" title}} {{style "path" path}} ({{format-date created "elapsed"}})`,
	"short": `{{style "title" title}} {{style "path" path}} ({{format-date created "elapsed"}})

{{list snippets}}`,
	"medium": `{{style "title" title}} {{style "path" path}}
Created: {{format-date created "short"}}

{{list snippets}}`,
	"long": `{{style "title" title}} {{style "path" path}}
Created: {{format-date created "short"}}
Modified: {{format-date modified "short"}}

{{list snippets}}`,
	"full": `{{style "title" title}} {{style "path" path}}
Created: {{format-date created "short"}}
Modified: {{format-date modified "short"}}
Tags: {{join tags ", "}}

{{prepend "  " body}}
`,
}

func resolveNoteFormat(format string) string {
	if format == "" {
		format = "short"
	}
	if tpl, ok := predefinedNoteFormats[format]; ok {
		return tpl
	}
	return format
}

func newNoteFormatter(nb *Notebook, workingDir string, format string, styler Styler) (*NoteFormatter, error) {
	env := &TemplateEnv{NotebookDir: nb.Path, Styler: styler}
	engine := env.newEngine()
	tpl, err := hbParse(resolveNoteFormat(format))
	if err != nil {
		return nil, fmt.Errorf("load template failed: %w", err)
	}
	return &NoteFormatter{nb: nb, workingDir: workingDir, engine: engine, tpl: tpl, env: envMap(), styler: styler}, nil
}

func (f *NoteFormatter) context(n Note) noteFormatContext {
	abs := f.nb.AbsPath(n.Path)
	rel, err := filepath.Rel(f.workingDir, abs)
	if err != nil {
		rel = n.Path
	}
	rel = filepath.ToSlash(rel)
	filename := filepath.Base(n.Path)
	snippets := n.Snippets
	if snippets == nil {
		snippets = []string{}
	}
	tags := n.Tags
	if tags == nil {
		tags = []string{}
	}
	meta := n.Metadata
	if meta == nil {
		meta = map[string]interface{}{}
	}
	return noteFormatContext{
		Filename:     filename,
		FilenameStem: strings.TrimSuffix(filename, filepath.Ext(filename)),
		Path:         rel,
		AbsPath:      abs,
		Title:        n.Title,
		Link:         f.nb.formatLink(n.Path, n.Title, f.workingDir),
		Lead:         n.Lead,
		Body:         n.Body,
		Snippets:     snippets,
		RawContent:   n.RawContent,
		WordCount:    n.WordCount,
		Tags:         tags,
		Metadata:     meta,
		Created:      n.Created,
		Modified:     n.Modified,
		Checksum:     n.Checksum,
		Env:          f.env,
	}
}

func (f *NoteFormatter) Format(n Note) (string, error) {
	out, err := f.engine.Render(f.tpl, f.context(n))
	if err != nil {
		if fm, ok := err.(*fatalMessage); ok {
			return "", fm
		}
		return "", fmt.Errorf("render template failed: %w", err)
	}
	return out, nil
}

func (f *NoteFormatter) JSON(n Note) noteJSON {
	c := f.context(n)
	return noteJSON{
		Filename:     c.Filename,
		FilenameStem: c.FilenameStem,
		Path:         c.Path,
		AbsPath:      c.AbsPath,
		Title:        c.Title,
		Link:         c.Link,
		Lead:         c.Lead,
		Body:         c.Body,
		Snippets:     c.Snippets,
		RawContent:   c.RawContent,
		WordCount:    c.WordCount,
		Tags:         c.Tags,
		Metadata:     c.Metadata,
		Created:      c.Created,
		Modified:     c.Modified,
		Checksum:     c.Checksum,
	}
}

func marshalJSON(v interface{}) string {
	b, err := json.Marshal(v)
	if err != nil {
		return ""
	}
	return string(b)
}

