// splitEscaped splits a comma separated list following kong's rules.
func splitEscaped(s string, sep rune) []string {
	var out []string
	escaped := false
	var token strings.Builder
	for i, ch := range s {
		switch {
		case escaped:
			token.WriteRune(ch)
			escaped = false
		case ch == '\\':
			escaped = true
		case ch == sep && i != 0:
			out = append(out, token.String())
			token.Reset()
		default:
			token.WriteRune(ch)
		}
	}
	if token.Len() != 0 {
		out = append(out, token.String())
	}
	return out
}

type cliParser struct {
