}

// splitEscaped splits a comma separated list following kong's rules.
func splitEscaped(s string, sep rune) []string {
	var out []string
	escaped := false
	var token strings.Builder
	for i, ch := range s {
		switch {
		case escaped:
			token.WriteRune(ch)
			escaped = false
		case ch == '\\':
			escaped = true
		case ch == sep && i != 0:
			out = append(out, token.String())
			token.Reset()
		default:
			token.WriteRune(ch)
		}
	}
	if token.Len() != 0 {
		out = append(out, token.String())
	}
	return out
}

type cliParser struct {
	root    *cmdSpec
	allowGlobals bool
}

// parse parses the arguments following the structure of the given spec.
func (p *cliParser) parse(args []string, spec *cmdSpec, includeGlobals bool) (*parsedArgs, error) {
	res := newParsedArgs()
	res.command = spec
	cmd := spec
	var cmdPath []string
	var positional []string
	onlyArgs := false

	// Collect active flags: globals + current command flags.
	activeFlags := func() []*flagSpec {
		var flags []*flagSpec
		if includeGlobals {
			flags = append(flags, globalFlags...)
		}
		// flags of the command chain
		flags = append(flags, cmd.flags...)
		return flags
	}
	findLong := func(name string) *flagSpec {
		for _, f := range activeFlags() {
			if f.long == name {
				return f
			}
		}
		return nil
	}
	findShort := func(name string) *flagSpec {
		for _, f := range activeFlags() {
			if f.short == name {
				return f
			}
		}
		return nil
	}

	setValue := func(f *flagSpec, value string, isEOL bool, isFlagLike string) error {
		switch f.kind {
		case flagBool:
			if value == "" {
				res.bools[f.long] = true
			} else {
				b, err := strconv.ParseBool(value)
				if err != nil {
					return &cliError{fmt.Sprintf("--%s: expected bool value but got %q", f.long, value)}
				}
				res.bools[f.long] = b
			}
			res.set[f.long] = true
			return nil
		case flagString, flagStrings, flagInt:
			typ := "string"
			if f.kind == flagInt {
				typ = "int"
			}
			if isEOL {
				return &cliError{fmt.Sprintf("--%s: expected %s value but got \"EOL\" (<EOL>)", f.long, typ)}
			}
			if isFlagLike != "" {
				return &cliError{fmt.Sprintf("--%s: expected %s value but got %q (%s); perhaps try --%s=%q?", f.long, typ, value, isFlagLike, f.long, value)}
			}
			if len(f.enum) > 0 {
				ok := false
				for _, e := range f.enum {
					if e == value {
						ok = true
					}
				}
				if !ok {
					quoted := make([]string, len(f.enum))
					for i, e := range f.enum {
						quoted[i] = fmt.Sprintf("%q", e)
					}
					return &cliError{fmt.Sprintf("--%s must be one of %s but got %q", f.long, strings.Join(quoted, ","), value)}
				}
			}
			switch f.kind {
			case flagString:
				res.strings[f.long] = value
			case flagInt:
				n, err := strconv.ParseInt(value, 10, 64)
				if err != nil {
					return &cliError{fmt.Sprintf("--%s: expected a valid 64 bit int but got %q", f.long, value)}
				}
				res.ints[f.long] = int(n)
			case flagStrings:
				res.lists[f.long] = append(res.lists[f.long], splitEscaped(value, ',')...)
			}
			res.set[f.long] = true
		}
		return nil
	}

	flagLikeKind := func(v string) string {
		if strings.HasPrefix(v, "--") {
			return "long flag"
		}
		if strings.HasPrefix(v, "-") && len(v) > 1 {
			return "short flag"
		}
		return ""
	}

	i := 0
	for i < len(args) {
		arg := args[i]
		if onlyArgs || arg == "-" || !strings.HasPrefix(arg, "-") {
			if !onlyArgs && arg == "-" {
				positional = append(positional, arg)
				i++
				continue
			}
			// subcommand?
			if !onlyArgs && len(cmd.subcommands) > 0 {
				if sub, ok := cmd.subcommands[arg]; ok {
					cmd = sub
					cmdPath = append(cmdPath, arg)
					i++
					continue
				}
			}
			positional = append(positional, arg)
			i++
			continue
		}
		if arg == "--" {
			onlyArgs = true
			i++
			continue
		}
		if strings.HasPrefix(arg, "--") {
			name := arg[2:]
			value := ""
			hasValue := false
			if idx := strings.IndexByte(name, '='); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			f := findLong(name)
			if f == nil {
				return nil, &cliError{unknownFlagMessage("--"+name, activeFlags())}
			}
			if f.long == "help" {
				res.help = true
				i++
				continue
			}
			if f.long == "version" {
				res.version = true
				i++
				continue
			}
			if f.kind == flagBool {
				if err := setValue(f, value, false, ""); err != nil {
					return nil, err
				}
				i++
				continue
			}
			if !hasValue {
				if i+1 >= len(args) {
					return nil, setValue(f, "", true, "")
				}
				value = args[i+1]
				i++
			}
			if err := setValue(f, value, false, flagLikeKind(value)); err != nil {
				return nil, err
			}
			i++
			continue
		}
		// short flags, possibly grouped
		shorts := arg[1:]
		j := 0
		for j < len(shorts) {
			name := string(shorts[j])
			f := findShort(name)
			if f == nil {
				return nil, &cliError{unknownFlagMessage("-"+name, activeFlags())}
			}
			if f.long == "help" {
				res.help = true
				j++
				continue
			}
			if f.kind == flagBool {
				if err := setValue(f, "", false, ""); err != nil {
					return nil, err
				}
				j++
				continue
			}
			// value flag
			rest := shorts[j+1:]
			if rest != "" {
				if err := setValue(f, rest, false, flagLikeKind(rest)); err != nil {
					return nil, err
				}
				j = len(shorts)
				break
			}
			if i+1 >= len(args) {
				return nil, setValue(f, "", true, "")
			}
			value := args[i+1]
			i++
			if err := setValue(f, value, false, flagLikeKind(value)); err != nil {
				return nil, err
			}
			j = len(shorts)
		}
		i++
	}

	// default subcommand
	if len(cmd.subcommands) > 0 && cmd.defaultSub != "" {
		if len(positional) == 0 {
			cmd = cmd.subcommands[cmd.defaultSub]
			cmdPath = append(cmdPath, cmd.name)
		}
	}
	res.command = cmd
	res.cmdPath = cmdPath
	if !res.help && !res.version {
		if cmd.maxArgs >= 0 && len(positional) > cmd.maxArgs {
			return nil, &cliError{"unexpected argument " + positional[cmd.maxArgs]}
		}
	}
	res.args = positional
	return res, nil
}

// unknownFlagMessage builds kong's "unknown flag" error with suggestions.
func unknownFlagMessage(flag string, flags []*flagSpec) string {
	var candidates []string
	for _, f := range flags {
		if f.long != "" && f.long != "version" {
			candidates = append(candidates, "--"+f.long)
		}
		if f.short != "" {
			candidates = append(candidates, "-"+f.short)
		}
	}
	var suggestions []string
	for _, c := range candidates {
		if levenshtein(flag, c) <= 2 || (strings.HasPrefix(c, flag) && len(flag) > 2) {
			suggestions = append(suggestions, c)
		}
	}
	msg := "unknown flag " + flag
	if len(suggestions) == 1 {
		msg += fmt.Sprintf(", did you mean %q?", suggestions[0])
	} else if len(suggestions) > 1 {
		quoted := make([]string, len(suggestions))
		for i, s := range suggestions {
			quoted[i] = fmt.Sprintf("%q", s)
		}
		msg += ", did you mean one of " + strings.Join(quoted, ", ") + "?"
	}
	return msg
}

func levenshtein(a, b string) int {
	ra := []rune(a)
	rb := []rune(b)
	if len(ra) == 0 {
		return len(rb)
	}
	if len(rb) == 0 {
		return len(ra)
	}
	prev := make([]int, len(rb)+1)
	cur := make([]int, len(rb)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ra); i++ {
		cur[0] = i
		for j := 1; j <= len(rb); j++ {
			cost := 1
			if ra[i-1] == rb[j-1] {
				cost = 0
			}
			cur[j] = minInt(prev[j]+1, minInt(cur[j-1]+1, prev[j-1]+cost))
		}
		prev, cur = cur, prev
	}
	return prev[len(rb)]
}

func minInt(a, b int) int {
	if a < b {
		return a
	}
	return b
}

// shellSplit splits a string into words following basic shell quoting rules.
func shellSplit(s string) []string {
	var out []string
	var cur strings.Builder
	inWord := false
	quote := byte(0)
	for i := 0; i < len(s); i++ {
		c := s[i]
		if quote != 0 {
			if c == quote {
				quote = 0
				continue
			}
			if quote == '"' && c == '\\' && i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
				continue
			}
			cur.WriteByte(c)
			continue
		}
		switch c {
		case ' ', '\t', '\n':
			if inWord {
				out = append(out, cur.String())
				cur.Reset()
				inWord = false
			}
		case '"', '\'':
			quote = c
			inWord = true
		case '\\':
			if i+1 < len(s) {
				i++
				cur.WriteByte(s[i])
			}
			inWord = true
		default:
			cur.WriteByte(c)
			inWord = true
		}
	}
	if inWord {
		out = append(out, cur.String())
	}
	return out
}
