type newNoteContext struct {
	ID           string
	Title        string
	Content      string
	Dir          string
	Filename     string
	FilenameStem string
	Extra        map[string]string
	Now          time.Time
	Env          map[string]string
}

func (c newNoteContext) HBGet(key string) (interface{}, bool) {
	switch key {
	case "id":
		return c.ID, true
	case "title":
		return c.Title, true
	case "content":
		return c.Content, true
	case "dir":
		return c.Dir, true
	case "filename":
		return c.Filename, true
	case "filename-stem":
		return c.FilenameStem, true
	case "extra":
		return c.Extra, true
	case "now":
		return c.Now, true
	case "env":
		return c.Env, true
	}
	return nil, false
}

func idCharset(name string) []rune {
	switch name {
	case "alphanum", "":
		return []rune("0123456789abcdefghijklmnopqrstuvwxyz")
	case "hex":
		return []rune("0123456789abcdef")
	case "letters":
		return []rune("abcdefghijklmnopqrstuvwxyz")
	case "numbers":
		return []rune("0123456789")
	}
	return []rune(name)
}

func generateID(cfg NoteConfig) string {
	charset := idCharset(cfg.IDCharset)
	length := cfg.IDLength
	if length <= 0 {
		length = 4
	}
	if len(charset) == 0 {
		charset = []rune("0123456789abcdefghijklmnopqrstuvwxyz")
	}
	var sb strings.Builder
	for i := 0; i < length; i++ {
		r := charset[rand.Intn(len(charset))]
		switch cfg.IDCase {
		case "upper":
			r = []rune(strings.ToUpper(string(r)))[0]
		case "mixed":
			if rand.Intn(2) == 0 {
				r = []rune(strings.ToUpper(string(r)))[0]
			} else {
				r = []rune(strings.ToLower(string(r)))[0]
			}
		default:
			r = []rune(strings.ToLower(string(r)))[0]
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

func (a *app) cmdNew(p *parsedArgs) int {
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	if err := a.indexQuietly(nb); err != nil {
		printError(err)
		return 1
	}
	rand.Seed(time.Now().UnixNano())

	dirArg := ""
	if len(p.args) > 0 {
		dirArg = p.args[0]
	}
	absDir := absFrom(a.workingDir, dirArg)
	relDir, err := filepath.Rel(nb.Path, absDir)
	if err != nil {
		printError(fmt.Errorf("new note: %w", err))
		return 1
	}
	relDir = filepath.ToSlash(relDir)
	if relDir == "." {
		relDir = ""
	}
	if fi, err := os.Stat(absDir); err != nil || !fi.IsDir() {
		name := dirArg
		if name == "" {
			name = relDir
		}
		printError(fmt.Errorf("new note: %s: directory not found", name))
		return 1
	}

	// Group config
	noteCfg := nb.Config.Note
	extra := map[string]string{}
	for k, v := range nb.Config.Extra {
		extra[k] = v
	}
	groupName := ""
	if p.set["group"] {
		groupName = p.strings["group"]
		g, ok := nb.Config.GroupConfigNamed(groupName)
		if !ok {
			printError(fmt.Errorf("new note: no group named `%s` found in the config", groupName))
			return 1
		}
		noteCfg = g.Note
		extra = map[string]string{}
		for k, v := range g.Extra {
			extra[k] = v
		}
	} else if name := nb.Config.GroupNameForPath(relDir); name != "" {
		g := nb.Config.Groups[name]
		noteCfg = g.Note
		extra = map[string]string{}
		for k, v := range g.Extra {
			extra[k] = v
		}
	}
	for _, kv := range p.lists["extra"] {
		idx := strings.IndexByte(kv, '=')
		if idx < 0 {
			printError(fmt.Errorf("new note: --extra: expected key=value but got %q", kv))
			return 1
		}
		extra[kv[:idx]] = kv[idx+1:]
	}

	now := time.Now()
	if p.set["date"] {
		d, err := parseDate(p.strings["date"], now)
		if err != nil {
			printError(err)
			return 1
		}
		now = d
	}

	title := noteCfg.DefaultTitle
	if p.set["title"] {
		title = p.strings["title"]
	}
	content := ""
	if p.bools["interactive"] {
		b, err := io.ReadAll(os.Stdin)
		if err != nil {
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
		content = string(b)
	}

	env := &TemplateEnv{NotebookDir: nb.Path, Now: now}
	engine := env.newEngine()

	ext := noteCfg.Extension
	if ext == "" {
		ext = "md"
	}

	// Filename
	filenameTpl, err := hbParse(noteCfg.FilenameTemplate)
	if err != nil {
		printError(fmt.Errorf("new note: %w", err))
		return 1
	}

	var id, filename, absPath string
	genID := func() string {
		if p.set["id"] {
			return p.strings["id"]
		}
		return generateID(noteCfg)
	}
	for attempt := 0; attempt < 50; attempt++ {
		id = genID()
		ctx := newNoteContext{ID: id, Title: title, Content: content, Dir: relDir, Extra: extra, Now: now, Env: envMap()}
		stem, err := engine.Render(filenameTpl, ctx)
		if err != nil {
			if fm, ok := err.(*fatalMessage); ok {
				fmt.Fprintf(os.Stderr, "zk: %s\n", fm.msg)
				return 1
			}
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
		filename = stem + "." + ext
		absPath = filepath.Join(absDir, filename)
		if _, err := os.Stat(absPath); err == nil {
			if p.set["id"] || !strings.Contains(noteCfg.FilenameTemplate, "{{id}}") {
				break
			}
			continue
		}
		break
	}
	ctx := newNoteContext{
		ID: id, Title: title, Content: content, Dir: relDir,
		Filename: filename, FilenameStem: strings.TrimSuffix(filename, "."+ext),
		Extra: extra, Now: now, Env: envMap(),
	}

	// Body template
	tplPath := ""
	if p.set["template"] {
		tplPath = nb.ResolveTemplatePath(p.strings["template"])
	} else if noteCfg.BodyTemplatePath != "" {
		tplPath = nb.ResolveTemplatePath(noteCfg.BodyTemplatePath)
	}
	body := ""
	if tplPath != "" {
		src, err := os.ReadFile(tplPath)
		if err != nil {
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
		tpl, err := hbParse(string(src))
		if err != nil {
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
		body, err = engine.Render(tpl, ctx)
		if err != nil {
			if fm, ok := err.(*fatalMessage); ok {
				fmt.Fprintf(os.Stderr, "zk: %s\n", fm.msg)
				return 1
			}
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
	}

	if p.bools["dry-run"] {
		fmt.Fprintln(os.Stderr, absPath)
		fmt.Print(body)
		return 0
	}

	exists := false
	if _, err := os.Stat(absPath); err == nil {
		exists = true
	}
	if !exists {
		if err := os.WriteFile(absPath, []byte(body), 0644); err != nil {
			printError(fmt.Errorf("new note: %w", err))
			return 1
		}
		// index the new note
		nb.Index(false, nil)
	}
	if p.bools["print-path"] {
		fmt.Println(absPath)
		return 0
	}
	if err := a.openEditor(nb, []string{absPath}); err != nil {
		printError(err)
		return 1
	}
	return 0
}

