)

// ---------------------------------------------------------------------------
// init

func (a *app) cmdInit(p *parsedArgs) int {
	dir := a.workingDir
	if len(p.args) > 0 {
		dir = absFrom(a.workingDir, p.args[0])
	}
	dir = filepath.Clean(dir)

	wiki := true
	hashtags := true
	colonTags := false
	multiword := false
	if !a.noInput {
		if !stdinIsTTY {
			fmt.Print("\x1b[0G\x1b[2K\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mDo you prefer [[WikiLinks]] over regular Markdown links? \x1b[0m\x1b[0;37m(y/N) \x1b[0m\x1b[?25l\x1b7\x1b[999;999f\x1b[6n\x1b8\x1b[?25h\x1b[6n")
			printError(errors.New("EOF"))
			return 1
		}
		reader := bufio.NewReader(os.Stdin)
		fmt.Fprint(os.Stdout, "\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mDo you prefer [[WikiLinks]] over regular Markdown links? \x1b[0m\x1b[0;37m(y/N) \x1b[0m")
		line, err := reader.ReadString('\n')
		if err != nil && line == "" {
			printError(errors.New("EOF"))
			return 1
		}
		ans := strings.TrimSpace(strings.ToLower(line))
		wiki = ans == "y" || ans == "yes"
		answer := "No"
		if wiki {
