		}
		fmt.Fprintf(os.Stdout, "\x1b[1A\x1b[2K\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mDo you prefer [[WikiLinks]] over regular Markdown links? \x1b[0m\x1b[0;36m%s\x1b[0m\n", answer)
		fmt.Fprint(os.Stdout, "\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mChoose your favorite inline tag syntaxes: \x1b[0m\x1b[0;36m(hashtag, multiword, colon) \x1b[0m")
		line, _ = reader.ReadString('\n')
		hashtags, multiword, colonTags = false, false, false
		var chosen []string
		for _, w := range strings.Fields(strings.ToLower(line)) {
			switch {
