				chosen = append(chosen, "#Bear's multi-word tag#")
			case strings.HasPrefix(w, "colon") || strings.HasPrefix(w, ":"):
				colonTags = true
				chosen = append(chosen, ":colon:tag:")
			}
		}
		fmt.Fprintf(os.Stdout, "\x1b[1A\x1b[2K\x1b[0;1;92m? \x1b[0m\x1b[0;1;99mChoose your favorite inline tag syntaxes: \x1b[0m\x1b[0;36m%s\x1b[0m\n", strings.Join(chosen, ", "))
	}
	fmt.Println()

	if existing, ok := findNotebookDir(dir); ok {
		printError(fmt.Errorf("init: a notebook already exists in %s", existing))
		return 1
	}
	if err := os.MkdirAll(dir, 0755); err != nil {
		printError(fmt.Errorf("init: %w", err))
		return 1
	}
	zkDir := filepath.Join(dir, zkDirName)
	if err := os.MkdirAll(filepath.Join(zkDir, "templates"), 0755); err != nil {
		printError(fmt.Errorf("init: %w", err))
