	cfg := strings.ReplaceAll(defaultConfigTemplate, "{{LINK_FORMAT}}", linkFormat)
	cfg = strings.ReplaceAll(cfg, "{{HASHTAGS}}", fmt.Sprint(hashtags))
	cfg = strings.ReplaceAll(cfg, "{{COLON_TAGS}}", fmt.Sprint(colonTags))
	cfg = strings.ReplaceAll(cfg, "{{MULTIWORD_TAGS}}", fmt.Sprint(multiword))
	if err := os.WriteFile(filepath.Join(zkDir, "config.toml"), []byte(cfg), 0644); err != nil {
		printError(fmt.Errorf("init: %w", err))
