}

// ---------------------------------------------------------------------------
// index

func (a *app) cmdIndex(p *parsedArgs) int {
	force := p.bools["force"]
	verbose := p.bools["verbose"]
	quiet := p.bools["quiet"]
	if verbose && quiet {
		printError(errors.New("--verbose and --quiet can't be used together"))
		return 1
	}
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	var logger func(string)
	if verbose {
		logger = func(s string) { fmt.Println(s) }
	}
	stats, err := nb.Index(force, logger)
	if verbose {
		fmt.Println()
	}
	if stdinIsTTY {
		fmt.Fprint(os.Stderr, "\r\r")
	}
	if err != nil {
		printError(err)
		return 1
	}
	if !quiet {
		fmt.Println(stats.String())
	}
	return 0
}

// ---------------------------------------------------------------------------
// Filtering options shared by list, edit and graph

func (a *app) buildFindOpts(nb *Notebook, p *parsedArgs, now time.Time) (NoteFindOpts, error) {
	opts := NoteFindOpts{}
	if p.bools["exact-match"] {
		return opts, errors.New("the --exact-match (-e) option is deprecated, use --match-strategy=exact (-Me) instead")
	}
	// Expand named filters in positional arguments.
	var paths []string
	lists := map[string][]string{}
	for k, v := range p.lists {
		lists[k] = append([]string{}, v...)
	}
	strs := map[string]string{}
	for k, v := range p.strings {
		strs[k] = v
	}
	ints := map[string]int{}
	for k, v := range p.ints {
		ints[k] = v
	}
	bools := map[string]bool{}
	for k, v := range p.bools {
		bools[k] = v
	}
	set := map[string]bool{}
	for k, v := range p.set {
		set[k] = v
	}
	filterSpec := buildFilterSpec()
	for _, arg := range p.args {
		if f, ok := nb.Config.Filters[arg]; ok {
			parser := &cliParser{}
			fp, err := parser.parse(shellSplit(f), filterSpec, false)
			if err != nil {
				return opts, fmt.Errorf("failed to expand named filter `%s`: %w", arg, err)
			}
			for k, v := range fp.lists {
				lists[k] = append(v, lists[k]...)
			}
			for k, v := range fp.strings {
				if !p.set[k] {
					strs[k] = v
				}
			}
			for k, v := range fp.ints {
				if !p.set[k] {
					ints[k] = v
				}
			}
			for k, v := range fp.bools {
				if v {
					bools[k] = true
				}
			}
			for k := range fp.set {
				set[k] = true
			}
			paths = append(paths, fp.args...)
			continue
		}
		paths = append(paths, arg)
	}
	if bools["exact-match"] {
		return opts, errors.New("the --exact-match (-e) option is deprecated, use --match-strategy=exact (-Me) instead")
	}

	relPaths := func(ps []string) []string {
		var out []string
		for _, p := range ps {
			out = append(out, a.notebookRelPath(nb, p))
		}
		return out
	}

	opts.IncludePaths = relPaths(paths)
	opts.ExcludePaths = relPaths(lists["exclude"])
	opts.Match = lists["match"]
	switch strs["match-strategy"] {
	case "", "fts", "f":
		opts.MatchStrategy = "fts"
	case "re", "r":
		opts.MatchStrategy = "re"
	case "exact", "e":
		opts.MatchStrategy = "exact"
	default:
		return opts, fmt.Errorf("%s: unknown match strategy\ntry fts (full-text search), re (regular expression) or exact", strs["match-strategy"])
	}
	opts.Tags = lists["tag"]
	opts.Mention = relPaths(lists["mention"])
	opts.MentionedBy = relPaths(lists["mentioned-by"])
	opts.LinkTo = relPaths(lists["link-to"])
	opts.NoLinkTo = relPaths(lists["no-link-to"])
	opts.LinkedBy = relPaths(lists["linked-by"])
	opts.NoLinkedBy = relPaths(lists["no-linked-by"])
	opts.Orphan = bools["orphan"]
	opts.Tagless = bools["tagless"]
	opts.MissingBacklink = bools["missing-backlink"]
	opts.Related = relPaths(lists["related"])
	opts.MaxDistance = ints["max-distance"]
	opts.Recursive = bools["recursive"]
	opts.Limit = ints["limit"]

	parseDay := func(key string) (*time.Time, *time.Time, error) {
		v, ok := strs[key]
		if !ok {
			return nil, nil, nil
		}
		t, err := parseDate(v, now)
		if err != nil {
			return nil, nil, err
		}
		start := time.Date(t.Year(), t.Month(), t.Day(), 0, 0, 0, 0, t.Location())
		end := start.AddDate(0, 0, 1)
		return &start, &end, nil
	}
	parseBound := func(key string) (*time.Time, error) {
		v, ok := strs[key]
		if !ok {
			return nil, nil
		}
		t, err := parseDate(v, now)
		if err != nil {
			return nil, err
		}
		return &t, nil
	}
	var err error
	if s, e, err := parseDay("created"); err != nil {
		return opts, err
	} else if s != nil {
		opts.CreatedStart, opts.CreatedEnd = s, e
	}
	if s, e, err := parseDay("modified"); err != nil {
		return opts, err
	} else if s != nil {
		opts.ModifiedStart, opts.ModifiedEnd = s, e
	}
	if t, err := parseBound("created-after"); err != nil {
		return opts, err
	} else if t != nil {
		opts.CreatedStart = t
	}
	if t, err := parseBound("created-before"); err != nil {
		return opts, err
	} else if t != nil {
		opts.CreatedEnd = t
	}
	if t, err := parseBound("modified-after"); err != nil {
		return opts, err
	} else if t != nil {
		opts.ModifiedStart = t
	}
	if t, err := parseBound("modified-before"); err != nil {
		return opts, err
	} else if t != nil {
		opts.ModifiedEnd = t
	}
	opts.Sorters, err = parseNoteSorters(lists["sort"])
	if err != nil {
		return opts, err
	}
	return opts, nil
}

// notebookRelPath converts a user-provided path into a notebook-relative path.
func (a *app) notebookRelPath(nb *Notebook, p string) string {
	abs := absFrom(a.workingDir, p)
	rel, err := filepath.Rel(nb.Path, abs)
	if err != nil {
		return p
	}
	return filepath.ToSlash(rel)
}

func unescapeSeparator(s string) string {
	s = strings.ReplaceAll(s, `\n`, "\n")
	s = strings.ReplaceAll(s, `\t`, "\t")
	return s
}

type listOutputOpts struct {
	format    string
	header    string
	footer    string
	delimiter string
	isJSON    bool
	jsonl     bool
}

func parseListOutputOpts(p *parsedArgs, kind string) (listOutputOpts, error) {
	o := listOutputOpts{delimiter: "\n", footer: "\n"}
	o.format = p.strings["format"]
	if p.set["delimiter"] && p.bools["delimiter0"] {
		return o, errors.New("--delimiter and --delimiter0 can't be used together")
	}
	if p.bools["delimiter0"] && (p.set["footer"] || p.set["header"]) {
		return o, errors.New("--footer and --delimiter0 can't be used together")
	}
	if p.set["header"] {
		o.header = unescapeSeparator(p.strings["header"])
	}
	if p.set["footer"] {
		o.footer = unescapeSeparator(p.strings["footer"])
	}
	if p.set["delimiter"] {
		o.delimiter = unescapeSeparator(p.strings["delimiter"])
	}
	if p.bools["delimiter0"] {
		o.delimiter = "\x00"
		o.footer = "\x00"
	}
	switch o.format {
	case "json":
		o.isJSON = true
	case "jsonl":
		o.isJSON = true
		o.jsonl = true
	}
	if o.isJSON {
		if p.set["header"] {
			return o, errors.New("--header can't be used with JSON format")
		}
		if p.set["footer"] || p.bools["delimiter0"] {
			return o, errors.New("--footer can't be used with JSON format")
		}
		if p.set["delimiter"] {
			return o, errors.New("--delimiter can't be used with JSON format")
		}
	}
	return o, nil
}

// ---------------------------------------------------------------------------
// list

func (a *app) cmdList(p *parsedArgs) int {
	out, err := parseListOutputOpts(p, "note")
	if err != nil {
		printError(err)
		return 1
	}
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	if err := a.indexQuietly(nb); err != nil {
		printError(err)
		return 1
	}
	styler := Styler{Enabled: stdoutIsTTY}
	opts, err := a.buildFindOpts(nb, p, time.Now())
	if err != nil {
		printError(fmt.Errorf("incorrect criteria: %w", err))
		return 1
	}
	if styler.Enabled {
		opts.SnippetStart = "\x1b[31m"
		opts.SnippetEnd = "\x1b[0m"
	}
	notes, err := nb.FindNotes(opts)
	if err != nil {
		printError(err)
		return 1
	}
	var formatter *NoteFormatter
	if !out.isJSON {
		formatter, err = newNoteFormatter(nb, a.workingDir, out.format, styler)
		if err != nil {
			printError(err)
			return 1
		}
	} else {
		formatter, _ = newNoteFormatter(nb, a.workingDir, "path", styler)
	}
	count := len(notes)
	if count > 0 {
		w := newPagedWriter(!p.bools["no-pager"], nb.Config.Tool.Pager)
		if out.isJSON {
			if out.jsonl {
				for _, n := range notes {
					w.WriteString(marshalJSON(formatter.JSON(n)) + "\n")
				}
			} else {
				items := make([]noteJSON, len(notes))
				for i, n := range notes {
					items[i] = formatter.JSON(n)
				}
				w.WriteString(marshalJSON(items) + "\n")
			}
		} else {
			w.WriteString(out.header)
			for i, n := range notes {
				s, err := formatter.Format(n)
				if err != nil {
					w.Close()
					if fm, ok := err.(*fatalMessage); ok {
						fmt.Fprintf(os.Stderr, "zk: %s\n", fm.msg)
						return 1
					}
					printError(err)
					return 1
				}
				if i > 0 {
					w.WriteString(out.delimiter)
				}
				w.WriteString(s)
			}
			w.WriteString(out.footer)
		}
		w.Close()
	}
	if !p.bools["quiet"] {
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", count, pluralize("note", count))
	}
	return 0
}

// ---------------------------------------------------------------------------
// graph

func (a *app) cmdGraph(p *parsedArgs) int {
	if !p.set["format"] {
		printError(errors.New("missing flags: --format=STRING"))
		return 1
	}
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	if err := a.indexQuietly(nb); err != nil {
		printError(err)
		return 1
	}
	opts, err := a.buildFindOpts(nb, p, time.Now())
	if err != nil {
		printError(fmt.Errorf("incorrect criteria: %w", err))
		return 1
	}
	notes, err := nb.FindNotes(opts)
	if err != nil {
		printError(err)
		return 1
	}
	formatter, _ := newNoteFormatter(nb, a.workingDir, "path", Styler{})
	ids := make([]int64, len(notes))
	for i, n := range notes {
		ids[i] = n.ID
	}
	links, err := nb.FindLinksBetween(ids)
	if err != nil {
		printError(err)
		return 1
	}
	var noteItems []string
	for _, n := range notes {
		noteItems = append(noteItems, "    "+marshalJSON(formatter.JSON(n)))
	}
	var linkItems []string
	for _, l := range links {
		linkItems = append(linkItems, "    "+marshalJSON(linkJSONOf(l)))
	}
	var sb strings.Builder
	sb.WriteString("{\n")
	sb.WriteString("  \"notes\": [\n")
	sb.WriteString(strings.Join(noteItems, ",\n"))
	sb.WriteString("\n  ],\n")
	sb.WriteString("  \"links\": [\n")
	sb.WriteString(strings.Join(linkItems, ",\n"))
	sb.WriteString("\n  ]\n")
	sb.WriteString("}\n")
	fmt.Print(sb.String())
	if !p.bools["quiet"] {
		fmt.Fprintf(os.Stderr, "\n\nFound %d %s\n", len(notes), pluralize("note", len(notes)))
	}
	return 0
}

type linkJSON struct {
	Title        string   `json:"title"`
	Href         string   `json:"href"`
	Type         string   `json:"type"`
	IsExternal   bool     `json:"isExternal"`
	Rels         []string `json:"rels"`
	Snippet      string   `json:"snippet"`
	SnippetStart int      `json:"snippetStart"`
	SnippetEnd   int      `json:"snippetEnd"`
	SourceID     int64    `json:"sourceId"`
	SourcePath   string   `json:"sourcePath"`
	TargetID     int64    `json:"targetId"`
	TargetPath   string   `json:"targetPath"`
}

func linkJSONOf(l ResolvedLink) linkJSON {
	rels := l.Rels
	if rels == nil {
		rels = []string{}
	}
	return linkJSON{
		Title: l.Title, Href: l.Href, Type: l.Type, IsExternal: l.IsExternal, Rels: rels,
		Snippet: l.Snippet, SnippetStart: l.SnippetStart, SnippetEnd: l.SnippetEnd,
		SourceID: l.SourceID, SourcePath: l.SourcePath, TargetID: l.TargetID, TargetPath: l.TargetPath,
	}
}

// ---------------------------------------------------------------------------
// edit

func (a *app) cmdEdit(p *parsedArgs) int {
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	if err := a.indexQuietly(nb); err != nil {
		printError(err)
		return 1
	}
	opts, err := a.buildFindOpts(nb, p, time.Now())
	if err != nil {
		printError(fmt.Errorf("incorrect criteria: %w", err))
		return 1
	}
	notes, err := nb.FindNotes(opts)
	if err != nil {
		printError(err)
		return 1
	}
	count := len(notes)
	if count == 0 {
		fmt.Fprintln(os.Stderr, "Found 0 notes.")
		return 0
	}
	if count > 5 && !p.bools["force"] {
		yes, _ := confirm(fmt.Sprintf("Are you sure you want to open %d notes in the editor?", count), a.noInput)
		if !yes {
			printError(errors.New("too many notes to be opened in the editor, aborting…"))
			return 1
		}
	}
	paths := make([]string, len(notes))
	for i, n := range notes {
		paths[i] = nb.AbsPath(n.Path)
	}
	if err := a.openEditor(nb, paths); err != nil {
		printError(err)
		return 1
	}
	return 0
}

func shellQuote(s string) string {
	if s == "" {
		return "''"
	}
	safe := true
	for _, r := range s {
		if !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || strings.ContainsRune("-_./=:@%+,", r)) {
			safe = false
			break
		}
	}
	if safe {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'"'"'`) + "'"
}

func (a *app) editorCommand(nb *Notebook) (string, error) {
	if e := os.Getenv("ZK_EDITOR"); e != "" {
		return e, nil
	}
	if nb.Config.Tool.Editor != "" {
		return nb.Config.Tool.Editor, nil
	}
	if e := os.Getenv("VISUAL"); e != "" {
		return e, nil
	}
	if e := os.Getenv("EDITOR"); e != "" {
		return e, nil
	}
	return "", errors.New("no editor set in config")
}

func (a *app) openEditor(nb *Notebook, paths []string) error {
	editor, err := a.editorCommand(nb)
	if err != nil {
		return err
	}
	quoted := make([]string, len(paths))
	for i, p := range paths {
		quoted[i] = shellQuote(p)
	}
	cmdStr := editor + " " + strings.Join(quoted, " ")
	cmd := shellCommand(cmdStr + " </dev/tty")
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Dir = a.workingDir
	cmd.Env = append(os.Environ(), "ZK_NOTEBOOK_DIR="+nb.Path)
	if err := cmd.Start(); err != nil {
		return fmt.Errorf("failed to launch editor: %s: %w", cmdStr, err)
	}
	if err := cmd.Wait(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			return fmt.Errorf("operation aborted by editor: %s: %w", cmdStr, err)
		}
		return fmt.Errorf("operation aborted by editor: %s: %w", cmdStr, err)
	}
	return nil
}

