func (a *app) cmdTagList(p *parsedArgs) int {
	out, err := parseListOutputOpts(p, "tag")
	if err != nil {
		printError(err)
		return 1
	}
	nb, ok := a.requireNotebook()
	if !ok {
		return 1
	}
	if err := a.indexQuietly(nb); err != nil {
		printError(err)
		return 1
	}
	sorters, err := parseTagSorters(p.lists["sort"])
	if err != nil {
		printError(err)
		return 1
	}
	tags, err := nb.FindTags(sorters)
	if err != nil {
		printError(err)
		return 1
	}
	styler := Styler{Enabled: stdoutIsTTY}
	count := len(tags)
	if count > 0 {
		w := newPagedWriter(!p.bools["no-pager"], nb.Config.Tool.Pager)
		if out.isJSON {
			if out.jsonl {
				for _, t := range tags {
					w.WriteString(marshalJSON(tagJSON{ID: t.ID, Kind: t.Kind, Name: t.Name, NoteCount: t.NoteCount}) + "\n")
				}
			} else {
				items := make([]tagJSON, len(tags))
				for i, t := range tags {
					items[i] = tagJSON{ID: t.ID, Kind: t.Kind, Name: t.Name, NoteCount: t.NoteCount}
				}
				w.WriteString(marshalJSON(items) + "\n")
			}
		} else {
			formatter, err := newTagFormatter(nb, out.format, styler)
			if err != nil {
				w.Close()
				printError(err)
				return 1
			}
			w.WriteString(out.header)
			for i, t := range tags {
				s, err := formatter.Format(t)
				if err != nil {
					w.Close()
					if fm, ok := err.(*fatalMessage); ok {
						fmt.Fprintf(os.Stderr, "zk: %s\n", fm.msg)
						return 1
					}
					printError(err)
					return 1
				}
				if i > 0 {
					w.WriteString(out.delimiter)
				}
				w.WriteString(s)
			}
			w.WriteString(out.footer)
		}
		w.Close()
	}
	if !p.bools["quiet"] {
		fmt.Fprintf(os.Stderr, "\nFound %d %s\n", count, pluralize("tag", count))
	}
	return 0
}

