	ID      json.RawMessage `json:"id,omitempty"`
	Method  string          `json:"method,omitempty"`
	Params  json.RawMessage `json:"params,omitempty"`
}

func writeRPC(w io.Writer, payload interface{}) {
	b, _ := json.Marshal(payload)
	fmt.Fprintf(w, "Content-Length: %d\r\n\r\n%s", len(b), b)
}

// cmdLSP implements a minimal language server.
func (a *app) cmdLSP(p *parsedArgs) int {
	reader := bufio.NewReader(os.Stdin)
	for {
		// headers
		contentLength := -1
		for {
			line, err := reader.ReadString('\n')
			if err != nil {
				return 0
			}
			line = strings.TrimRight(line, "\r\n")
			if line == "" {
				break
			}
			if strings.HasPrefix(strings.ToLower(line), "content-length:") {
				n, err := strconv.Atoi(strings.TrimSpace(line[len("content-length:"):]))
				if err == nil {
					contentLength = n
				}
			}
		}
		if contentLength < 0 {
			return 0
		}
		buf := make([]byte, contentLength)
		if _, err := io.ReadFull(reader, buf); err != nil {
			return 0
		}
		var msg rpcMessage
		if err := json.Unmarshal(buf, &msg); err != nil {
			continue
		}
		switch msg.Method {
		case "initialize":
			result := map[string]interface{}{
				"capabilities": map[string]interface{}{
					"textDocumentSync": map[string]interface{}{"openClose": true, "change": 2, "save": true},
					"completionProvider": map[string]interface{}{
						"triggerCharacters": []string{"(", "[", "#", ":"},
						"resolveProvider":   true,
					},
					"hoverProvider":        true,
					"definitionProvider":   true,
					"referencesProvider":   map[string]interface{}{},
					"codeActionProvider":   true,
					"documentLinkProvider": map[string]interface{}{"resolveProvider": true},
					"executeCommandProvider": map[string]interface{}{
						"commands": []string{"zk.index", "zk.new", "zk.list", "zk.tag.list"},
					},
				},
				"serverInfo": map[string]interface{}{"name": "zk", "version": "dev"},
			}
			writeRPC(os.Stdout, map[string]interface{}{"id": msg.ID, "result": result, "jsonrpc": "2.0"})
		case "shutdown":
			writeRPC(os.Stdout, map[string]interface{}{"id": msg.ID, "result": nil, "jsonrpc": "2.0"})
		case "exit":
			return 0
		default:
			if len(msg.ID) > 0 {
				writeRPC(os.Stdout, map[string]interface{}{"id": msg.ID, "result": nil, "jsonrpc": "2.0"})
			}
		}
	}
}
