{"command":"cd /workspace && cat > fzf.go <<'EOF'
package main

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// selectNotesInteractively filters the notes with fzf when running interactively.
func (a *app) selectNotesInteractively(nb *Notebook, notes []Note) ([]Note, error) {
	if !stdinIsTTY || !stdoutIsTTY {
		return notes, nil
	}
	if len(notes) == 0 {
		return notes, nil
	}
	fzfPath, err := exec.LookPath("fzf")
	if err != nil {
		return nil, errors.New("failed to launch fzf: executable file not found in $PATH")
	}
	lineTpl := nb.Config.Tool.FzfLine
	if lineTpl == "" {
		lineTpl = `{{style "title" title-or-path}} {{style "understate" body}}`
	}
	formatter, err := newNoteFormatter(nb, a.workingDir, strings.ReplaceAll(lineTpl, "title-or-path", "title"), Styler{Enabled: true})
	if err != nil {
		return nil, err
	}
	var input bytes.Buffer
	byPath := map[string]Note{}
	for _, n := range notes {
		line, err := formatter.Format(n)
		if err != nil {
			return nil, err
		}
		if n.Title == "" {
			line = strings.Replace(line, "\x1b[1;33m\x1b[0m", "\x1b[1;33m"+n.Path+"\x1b[0m", 1)
		}
		line = strings.ReplaceAll(line, "\n", " ")
		abs := nb.AbsPath(n.Path)
		byPath[abs] = n
		input.WriteString(line + "\x01" + abs + "\n")
	}
	args := []string{
		"--delimiter", "\x01",
		"--tiebreak", "begin",
		"--exact",
		"--tabstop", "4",
		"--height", "100%",
		"--layout", "reverse",
		"--no-hscroll",
		"--color", "hl:-1,hl+:-1",
		"--preview-window", "wrap",
		"--ansi",
		"--multi",
		"--with-nth", "1",
	}
	preview := "cat {-1}"
	if nb.Config.Tool.FzfPreview != nil {
		preview = *nb.Config.Tool.FzfPreview
	}
	if strings.TrimSpace(preview) != "" {
		args = append(args, "--preview", preview)
	}
	if nb.Config.Tool.FzfOptions != "" {
		args = append(args, shellSplit(nb.Config.Tool.FzfOptions)...)
	}
	cmd := exec.Command(fzfPath, args...)
	cmd.Stdin = &input
	cmd.Stderr = os.Stderr
	cmd.Env = append(os.Environ(), "ZK_NOTEBOOK_DIR="+nb.Path)
	out, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 130 {
			return []Note{}, nil
		}
		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
			return []Note{}, nil
		}
		return nil, fmt.Errorf("failed to launch fzf: %w", err)
	}
	var selected []Note
	for _, line := range strings.Split(strings.TrimRight(string(out), "\n"), "\n") {
		idx := strings.LastIndex(line, "\x01")
		if idx < 0 {
			continue
		}
		path := line[idx+1:]
		if n, ok := byPath[path]; ok {
			selected = append(selected, n)
		}
	}
	return selected, nil
}
