				return stats, err
			}
			i++
		case i >= len(files) || existingPaths[j] < files[i].rel:
			if err := remove(existingPaths[j]); err != nil {
				return stats, err
			}
			j++
		default:
			if err := process(files[i], existing[files[i].rel], true); err != nil {
				return stats, err
			}
			i++
			j++
		}
	}
'''
